# v2.5.26: 외부직원 통합상태. /gupgrade는 가드봇→메인봇→페이퍼봇→WS→micro 순서로 변경분만 적용.
def gexternal_state_text() -> str:
    w = ws_sidecar_state_dict()
    m = micro_state_dict()
    w_ok = bool(w.get("ok") or (w.get("alive") and int(w.get("fresh") or 0) > 0 and (str(w.get("last_error") or "-") in {"", "-", "None", "none"} or _is_reconnect_notice(w.get("last_error")))))
    m_ok = bool(m.get("ok"))
    overall = "✅ 정상" if w_ok and m_ok else ("⚠️ 확인 필요" if (w_ok or m_ok) else "❌ 외부직원 문제")
    notes = []
    if w.get("stop_suspect"):
        notes.append("- WS 마지막 종료가 signal/normal stop 계열: 가드 재시작 연동 종료 의심")
    if m.get("stop_suspect"):
        notes.append("- 호가·체결 마지막 종료가 signal/normal stop 계열: 가드 재시작 연동 종료 의심")
    if str(w.get("management_warning") or "-") != "-":
        notes.append("- WS 구조경고: " + str(w.get("management_warning")))
    if str(m.get("management_warning") or "-") != "-":
        notes.append("- 호가·체결 구조경고: " + str(m.get("management_warning")))
    if not w.get("alive"):
        notes.append("- WS 꺼짐: /gws_start 또는 /gws_restart")
    elif not w_ok:
        notes.append("- WS 확인 필요: /gws_state")
    if m.get("desired_enabled") and not m.get("alive"):
        notes.append("- 호가·체결은 켜져 있어야 하는데 꺼짐: /gmicro_start")
    elif not m_ok:
        notes.append("- 호가·체결 확인 필요: /gmicro_state")
    if any("구조경고" in str(x) for x in notes):
        overall = "⚠️ 구조 확인 필요"
    if not notes:
        notes.append("- 이상 없음")
    return "\n".join([
        "🛰 외부직원 통합상태 /gexternal_state",
        overall,
        "",
        "[0/2] 서버자원",
        *resource_status_lines(),
        "",
        "[1/2] 웹소켓 직원",
        f"{'✅' if w_ok else '⚠️'} 상태: {w.get('verdict','-')}",
        f"- pid {w.get('used_pid') or '-'} / alive {w.get('alive')} / age {w.get('age_text','-')}",
        f"- 관리방식 {w.get('management','-')} / 구조경고 {w.get('management_warning','-')}",
        f"- 수신 raw {w.get('raw_total',0)} / match {w.get('match_ok',0)} / cache {w.get('cached',0)} / fresh {w.get('fresh',0)}",
        f"- 상태메모 {('재구독 중' if _is_reconnect_notice(w.get('last_error','-')) else w.get('last_error','-'))}",
        "",
        "[2/2] 호가·체결 직원",
        f"{'✅' if m_ok else '⚠️'} 상태: {m.get('verdict','-')}",
        f"- pid {m.get('used_pid') or '-'} / alive {m.get('alive')} / age {m.get('age_text','-')}",
        f"- 관리방식 {m.get('management','-')} / 구조경고 {m.get('management_warning','-')}",
        f"- desired {'enabled' if m.get('desired_enabled') else 'disabled'}",
        f"- 수집 targets {m.get('targets',0)} / cache {m.get('cached',0)} / fresh {m.get('fresh',0)}",
        f"- 호가OK {m.get('orderbook_ok',0)} / 체결OK {m.get('trade_ok',0)} / 오류 {m.get('last_error','-')}",
        "",
        "판독",
        *notes,
        "",
        "",
        "[worker]",
        *[format_worker_state_line(worker_state_dict(n)) for n in WORKER_SPECS],
        "",
        "명령",
        "- /gws_state: 웹소켓 상세",
        "- /gmicro_state: 호가·체결 상세",
        "- /gworker_state: 리뉴얼 worker 상세",
    ])


def service_status() -> str:
    active = is_main_service_active()
    bot_version, target, deployed, latest = get_bot_versions()
    pv = get_paper_versions()
    wsv = ws_sidecar_state_dict()
    msv = micro_state_dict()
    status = read_json(BOT_DIR / GUARD_RELEASE_RESULT_FILE) or read_json(BOT_DIR / UPGRADE_STATUS_FILE)
    last_ok = "없음"
    if status:
        bundle_v2291 = status.get('bundle') or status.get('target') or status.get('stage') or '?'
        stage_v2291 = str(status.get('stage') or '').lower()
        ok_v2291 = bool(status.get('ok')) or stage_v2291 == 'done'
        when_v2291 = status.get('finished') or status.get('finished_at') or status.get('time') or '?'
        last_ok = f"{when_v2291} / {'성공' if ok_v2291 else '실패/확인필요'} / {bundle_v2291}"
    issue_bits = []
    if active != "active": issue_bits.append("메인봇 inactive")
    if not wsv.get("ok"): issue_bits.append("WS 확인 필요")
    # v2292: a management-layout note is not a health incident when the existing
    # WS owner is alive, synchronized and proving fresh successful reception.
    if (not wsv.get("ok")) and str(wsv.get("management_warning") or "-") != "-": issue_bits.append("WS 구조경고")
    if not msv.get("ok"): issue_bits.append("micro 확인 필요")
    if str(msv.get("management_warning") or "-") != "-": issue_bits.append("micro 구조경고")
    head = "✅ 결론" if not issue_bits else "❔ 결론: 확인 필요 - " + ", ".join(issue_bits[:4])
    return (
        f"🛡 가드봇 /guard\n"
        f"{head}\n"
        f"- 메인봇: {active} / {bot_version}\n"
        f"- 페이퍼봇: {pv['service']} / {pv['active_version']}\n"
        f"- 웹소켓직원: {wsv.get('verdict')} / active {wsv.get('version')} / status {wsv.get('status_version','-')}\n"
        f"- 호가·체결직원: {msv.get('verdict')} / {msv.get('version')}\n"
        f"- 업그레이드: /gupgrade 전체 또는 /gupgrade_menu에서 개별 적용\n\n"
        f"📊 상태\n"
        f"- guard: {VERSION}\n"
        f"- main service: {MAIN_SERVICE}\n"
        f"- paper service: {PAPER_SERVICE}\n"
        f"- 최신 수익형 파일: {latest}\n"
        f"- 최신 paper 파일: {pv['latest']}\n"
        f"- 웹소켓 pid: {wsv.get('used_pid') or '-'} / alive: {wsv.get('alive')}\n"
        f"- 호가·체결 pid: {msv.get('used_pid') or '-'} / alive: {msv.get('alive')}\n"
        f"- 최근 적용: {last_ok}\n\n"
        f"🧭 자주 쓰는 명령\n"
        f"- /gdeploy 배포상태\n"
        f"- /gupgrade 전체 최신화(변경분만 교체/재시작)\n"
        f"- /gpaper_restart 페이퍼봇 재시작\n"
        f"- /gpaper_reset 페이퍼 실행연결 재설치\n"
        f"- /gpaper_service 페이퍼봇 서비스화 안내\n"
        f"- /gws_state 웹소켓직원 상태\n"
        f"- /gws_restart 웹소켓직원 재시작\n"
        f"- /gmicro_state 호가·체결직원 상태\n"
        f"- /gmicro_upgrade 호가·체결직원 최신 적용\n"
        f"- /gguard_upgrade 가드봇 자체 업그레이드\n"
        f"- /glog 최근 오류\n"
        f"- /gdeep_audit 작업자 지연·디스크 증가 원인 통합감사\n"
        f"- /gresource_owner Paper·Strategy·Review·Candle 자원 owner 정밀감사\n"
        f"- /gcleanup 디스크 순환정리"
    )

def glog(lines: int = 80) -> str:
    lines = max(20, min(160, int(lines or 80)))
    started = perf_now()
    out = recent_journal(lines=lines, timeout_sec=4)
    took = perf_now() - started
    focus = []
    for line in (out or "").splitlines():
        if any(x in line for x in ["Traceback", "NameError", "SyntaxError", "ImportError", "Exception", "ERROR", "Failed", "failure", "timeout"]):
            focus.append(line)
    if "journalctl timeout" in (out or ""):
        head = "⚠️ journalctl 지연 - 가드봇 보호를 위해 status fallback만 표시"
    elif focus:
        head = "❌ 오류 의심 줄\n" + "\n".join(focus[-16:])
    else:
        head = "✅ 최근 로그에서 뚜렷한 Python 오류 줄 없음"
    return f"🧾 최근 로그 /glog {lines}\n- 방식: 짧은 timeout journal tail / {took:.1f}s\n\n{head}\n\n[tail]\n{tail(out, 2200)}"


def unlock_deploy() -> str:
    removed = []
    for p in [Path("/tmp/tradingbot_auto_deploy.lock"), BOT_DIR / "tradingbot_auto_deploy.lock"]:
        try:
            if p.exists():
                p.unlink()
                removed.append(str(p))
        except Exception as e:
            removed.append(f"{p}: {type(e).__name__}: {e}")
    return "🔓 lock 해제 /gunlock\n- removed: " + (", ".join(removed) if removed else "없음")



# =============================================================================
# guard v2.5.69 / v927: 작업자 지연 + 디스크 증가 통합 원인 감사
# - 읽기 전용. OPEN/CLOSED/trade_log 및 매매 기준을 수정하지 않는다.
# - 한 번의 명령에서 현재 용량/프로세스/worker cycle을 수집하고 짧은 구간 파일 증가량을 재측정한다.
# - journal, 삭제됐지만 열린 파일, 중복 프로세스, runtime reset/backup/trace 증가를 분리한다.
# =============================================================================

def _audit_int(value, default: int = 0) -> int:
    try:
        return int(float(value))
    except Exception:
        return int(default)


def _audit_float(value, default: float = 0.0) -> float:
    try:
        return float(value)
    except Exception:
        return float(default)


def _audit_age(path: Path) -> float:
    try:
        return max(0.0, time.time() - path.stat().st_mtime) if path.exists() else 999999.0
    except Exception:
        return 999999.0


def _audit_rel(path) -> str:
    try:
        pp = Path(path)
        return str(pp.relative_to(BOT_DIR))
    except Exception:
        return str(path)


def _audit_fmt_delta(value) -> str:
    n = _audit_int(value, 0)
    sign = "+" if n >= 0 else "-"
    return sign + _fmt_bytes(abs(n))


def _audit_scan_files(root: Path, max_files: int = 50000) -> dict:
    files: dict[str, int] = {}
    errors = 0
    scanned = 0
    truncated = False
    try:
        root = root.resolve()
    except Exception:
        root = Path(root)
    if not root.exists():
        return {"root": str(root), "files": files, "total": 0, "scanned": 0, "errors": 0, "truncated": False}
    try:
        for dirpath, dirnames, filenames in os.walk(str(root), followlinks=False):
            # 가상/마운트 하위가 섞이지 않도록 symlink directory는 내려가지 않는다.
            safe_dirs = []
            for name in dirnames:
                dp = Path(dirpath) / name
                try:
                    if not dp.is_symlink():
                        safe_dirs.append(name)
                except Exception:
                    errors += 1
            dirnames[:] = safe_dirs
            for name in filenames:
                if scanned >= max_files:
                    truncated = True
                    break
                fp = Path(dirpath) / name
                scanned += 1
                try:
                    if fp.is_symlink() or not fp.is_file():
                        continue
                    files[str(fp)] = int(fp.stat().st_size)
                except Exception:
                    errors += 1
            if truncated:
                break
    except Exception:
        errors += 1
    return {"root": str(root), "files": files, "total": int(sum(files.values())), "scanned": scanned, "errors": errors, "truncated": truncated}


def _audit_category(path: str) -> str:
    low = str(path).lower()
    name = Path(path).name.lower()
    if any(x in name for x in ("paper_bot_open", "paper_bot_closed", "trade_log", "closed_result", "score_ledger")):
        return "핵심원장"
    if ".paper_runtime_reset_" in low:
        return "paper_runtime_reset"
    if "backup" in name or name.endswith(".bak"):
        return "backup"
    if name.startswith("coinbot_update_v") and name.endswith(".zip"):
        return "update_zip"
    if name.endswith(".zip"):
        return "zip"
    if name.endswith((".log", ".out", ".err")):
        return "log"
    if name.endswith(".jsonl"):
        return "jsonl_trace"
    if name.endswith(".gz"):
        return "gzip_archive"
    if name.endswith(".json"):
        return "json_cache_status"
    if name.endswith(".py"):
        return "python_code"
    return "other"


def _audit_category_totals(files: dict[str, int]) -> dict[str, dict]:
    out: dict[str, dict] = {}
    for path, size in files.items():
        cat = _audit_category(path)
        row = out.setdefault(cat, {"bytes": 0, "count": 0})
        row["bytes"] += int(size)
        row["count"] += 1
    return dict(sorted(out.items(), key=lambda kv: kv[1]["bytes"], reverse=True))


def _audit_top_files(files: dict[str, int], limit: int = 15) -> list[dict]:
    return [
        {"path": _audit_rel(path), "bytes": int(size), "category": _audit_category(path)}
        for path, size in sorted(files.items(), key=lambda kv: kv[1], reverse=True)[:max(1, limit)]
    ]


def _audit_du_bytes(path: Path, timeout: int = 12) -> int:
    if not path.exists():
        return 0
    rc, out = run(["du", "-sx", "-B1", str(path)], timeout=timeout)
    if rc == 0 and out:
        try:
            return int(out.split()[0])
        except Exception:
            pass
    return 0


def _audit_journal_bytes() -> tuple[int, str]:
    rc, out = run(["journalctl", "--disk-usage", "--no-pager"], timeout=8)
    text = (out or "").strip()
    if rc != 0:
        return 0, tail(text, 300)
    # 예: Archived and active journals take up 1.2G in the file system.
    m = re.search(r"([0-9]+(?:\.[0-9]+)?)\s*([KMGT])(?:i?B|B)?", text, re.I)
    if not m:
        return 0, text
    val = float(m.group(1))
    unit = m.group(2).upper()
    mult = {"K": 1024, "M": 1024**2, "G": 1024**3, "T": 1024**4}.get(unit, 1)
    return int(val * mult), text


def _audit_proc_rows() -> list[dict]:
    rc, out = run(["ps", "-eo", "pid=,ppid=,etimes=,pcpu=,pmem=,rss=,nlwp=,args="], timeout=8)
    rows = []
    if rc != 0:
        return rows
    def classify(args: str) -> str:
        tokens = [Path(tok.strip("'\"")).name for tok in args.split() if tok.strip("'\"").endswith(".py")]
        for base in tokens:
            if base == "backga_guard_bot.py" or base.startswith("backga_guard_bot_v"):
                return "guard"
            if base == "paper_bot.py" or base.startswith("paper_bot_v"):
                return "paper"
            if base == "ws_sidecar.py" or base.startswith("ws_sidecar_v"):
                return "ws"
            if base == "bithumb_micro_sidecar.py" or base.startswith("bithumb_micro_sidecar_v"):
                return "micro"
            for n, spec in WORKER_SPECS.items():
                active = str(spec.get("active") or "")
                prefix = str(spec.get("prefix") or "")
                if base == active or (prefix and base.startswith(prefix + "_v")):
                    return n
            if base == "bot.py" or base.startswith("coinbot_main_v"):
                return "main"
        return ""

    for line in (out or "").splitlines():
        parts = line.strip().split(None, 7)
        if len(parts) < 8:
            continue
        pid, ppid, etimes, pcpu, pmem, rss, nlwp, args = parts
        first_exec = Path(args.split()[0]).name.lower() if args.split() else ""
        if "python" not in first_exec:
            continue
        component = classify(args)
        if not component:
            continue
        rows.append({
            "component": component,
            "pid": _audit_int(pid),
            "ppid": _audit_int(ppid),
            "elapsed_sec": _audit_int(etimes),
            "cpu_pct": _audit_float(pcpu),
            "mem_pct": _audit_float(pmem),
            "rss_bytes": _audit_int(rss) * 1024,
            "threads": _audit_int(nlwp),
            "args": args[:500],
        })
    return rows


def _audit_open_fd_snapshot() -> dict:
    owners: dict[str, list[dict]] = {}
    deleted: list[dict] = []
    proc_root = Path("/proc")
    checked = 0
    errors = 0
    try:
        bot_real = str(BOT_DIR.resolve())
    except Exception:
        bot_real = str(BOT_DIR)
    for pd in proc_root.iterdir():
        if not pd.name.isdigit():
            continue
        pid = _audit_int(pd.name)
        if pid <= 0:
            continue
        try:
            cmd_raw = (pd / "cmdline").read_bytes().replace(b"\x00", b" ").decode("utf-8", errors="ignore").strip()
            comm = (pd / "comm").read_text(encoding="utf-8", errors="ignore").strip()
        except Exception:
            cmd_raw, comm = "", ""
        fd_dir = pd / "fd"
        try:
            fds = list(fd_dir.iterdir())
        except Exception:
            continue
        for fd in fds:
            checked += 1
            try:
                target = os.readlink(str(fd))
            except Exception:
                errors += 1
                continue
            is_deleted = target.endswith(" (deleted)")
            clean = target[:-10] if is_deleted else target
            try:
                real = os.path.realpath(clean) if clean.startswith("/") else clean
            except Exception:
                real = clean
            if is_deleted:
                try:
                    size = int(os.stat(str(fd)).st_size)
                except Exception:
                    size = 0
                deleted.append({"pid": pid, "fd": fd.name, "bytes": size, "target": clean, "cmd": (cmd_raw or comm)[:300]})
            if real.startswith(bot_real + os.sep) or real == bot_real or real.startswith("/var/log/"):
                flags_val=0
                try:
                    info=(pd/'fdinfo'/fd.name).read_text(encoding='utf-8',errors='ignore')
                    for line in info.splitlines():
                        if line.startswith('flags:'):
                            flags_val=int(line.split(':',1)[1].strip(),8); break
                except Exception:
                    flags_val=0
                mode_bits=flags_val & 3
                low=(cmd_raw or comm).lower()
                component='unknown'
                patterns=(('review',r'review_worker(?:_v[^ /]+)?\.py'),('strategy',r'strategy_worker(?:_v[^ /]+)?\.py'),('paper',r'paper_bot(?:_v[^ /]+)?\.py'),('guard',r'backga_guard_bot(?:_v[^ /]+)?\.py'),('main',r'(?:coinbot_main_v[^ /]+|bot)\.py'))
                for cname,pat in patterns:
                    if re.search(pat,low): component=cname; break
                if component=='unknown':
                    for n,spec in WORKER_SPECS.items():
                        prefix=str(spec.get('prefix') or '').lower()
                        active=str(spec.get('active') or '').lower()
                        if active and active in low or (prefix and re.search(re.escape(prefix)+r'(?:_v[^ /]+)?\.py',low)):
                            component=n; break
                owners.setdefault(real, []).append({"pid": pid, "cmd": (cmd_raw or comm)[:240], "mode": "write" if mode_bits in (1,2) else "read", "component": component})
    deleted.sort(key=lambda r: r.get("bytes", 0), reverse=True)
    return {"owners": owners, "deleted": deleted, "deleted_bytes": sum(int(r.get("bytes", 0)) for r in deleted), "checked": checked, "errors": errors}


def _audit_worker_rows(proc_rows: list[dict]) -> list[dict]:
    by_component: dict[str, list[dict]] = {}
    for row in proc_rows:
        by_component.setdefault(str(row.get("component")), []).append(row)
    out = []
    for name in WORKER_SPECS:
        st = worker_state_dict(name)
        raw = st.get("raw") if isinstance(st.get("raw"), dict) else {}
        cycle = None
        for key in ("last_sec", "cycle_sec", "last_cycle_sec", "loop_sec", "elapsed_sec"):
            if raw.get(key) not in (None, "", "-"):
                cycle = _audit_float(raw.get(key), -1.0)
                break
        prows = by_component.get(name, [])
        out.append({
            "name": name,
            "label": st.get("label"),
            "service": st.get("service"),
            "service_active": st.get("service_active"),
            "status_age_sec": _audit_float(st.get("age"), 999999.0),
            "cycle_sec": cycle,
            "row_count": raw.get("row_count", raw.get("evaluated", "-")),
            "phase": raw.get("phase", raw.get("last_phase", "-")),
            "process_count": len(prows),
            "cpu_pct": sum(_audit_float(x.get("cpu_pct")) for x in prows),
            "rss_bytes": sum(_audit_int(x.get("rss_bytes")) for x in prows),
            "threads": sum(_audit_int(x.get("threads")) for x in prows),
            "pids": [x.get("pid") for x in prows],
            "error": st.get("last_error"),
            "status_rss_bytes": int(_audit_float(raw.get("rss_mb"),0.0)*1024*1024),
            "rss_delta_bytes": sum(_audit_int(x.get("rss_bytes")) for x in prows)-int(_audit_float(raw.get("rss_mb"),0.0)*1024*1024),
        })
    out.sort(key=lambda r: max(_audit_float(r.get("cycle_sec"), 0.0), _audit_float(r.get("status_age_sec"), 0.0)), reverse=True)
    return out


def _audit_service_rows(proc_rows: list[dict]) -> list[dict]:
    services = {
        "main": MAIN_SERVICE,
        "paper": PAPER_SERVICE,
        "guard": GUARD_SERVICE,
        "ws": WS_SERVICE,
        "micro": MICRO_SERVICE,
    }
    services.update({n: str(spec["service"]) for n, spec in WORKER_SPECS.items()})
    by_comp: dict[str, list[dict]] = {}
    for row in proc_rows:
        by_comp.setdefault(str(row.get("component")), []).append(row)
    out = []
    for comp, svc in services.items():
        rc, txt = run(["systemctl", "show", svc, "-p", "ActiveState", "-p", "SubState", "-p", "MainPID", "-p", "NRestarts", "-p", "MemoryCurrent", "-p", "TasksCurrent", "-p", "CPUUsageNSec"], timeout=6)
        props = {}
        if rc == 0:
            for line in (txt or "").splitlines():
                if "=" in line:
                    k, v = line.split("=", 1)
                    props[k.strip()] = v.strip()
        prows = by_comp.get(comp, [])
        out.append({
            "component": comp,
            "service": svc,
            "active": props.get("ActiveState", "?"),
            "sub": props.get("SubState", "?"),
            "main_pid": _audit_int(props.get("MainPID")),
            "restart_count": _audit_int(props.get("NRestarts")),
            "memory_bytes": _audit_int(props.get("MemoryCurrent")),
            "tasks": _audit_int(props.get("TasksCurrent")),
            "cpu_total_sec": _audit_float(props.get("CPUUsageNSec")) / 1_000_000_000.0,
            "process_count": len(prows),
            "pids": [r.get("pid") for r in prows],
            "cpu_pct": sum(_audit_float(r.get("cpu_pct")) for r in prows),
            "rss_bytes": sum(_audit_int(r.get("rss_bytes")) for r in prows),
        })
    return out


def _audit_file_deltas(before: dict[str, int], after: dict[str, int], owners: dict[str, list[dict]], limit: int = 18) -> list[dict]:
    rows = []
    for path in set(before) | set(after):
        delta = int(after.get(path, 0)) - int(before.get(path, 0))
        if delta == 0:
            continue
        owner_rows = owners.get(os.path.realpath(path), [])
        rows.append({
            "path": _audit_rel(path),
            "before": int(before.get(path, 0)),
            "after": int(after.get(path, 0)),
            "delta": delta,
            "category": _audit_category(path),
            "owners": owner_rows[:4],
        })
    rows.sort(key=lambda r: abs(int(r.get("delta", 0))), reverse=True)
    return rows[:max(1, limit)]


def _audit_previous_delta(current_files: dict[str, int], current_disk_used: int) -> dict:
    state = read_json(BOT_DIR / GUARD_DEEP_AUDIT_STATE_FILE)
    prev_files = state.get("files") if isinstance(state.get("files"), dict) else {}
    prev_ts = _audit_float(state.get("ts"), 0.0)
    prev_used = _audit_int(state.get("disk_used"), 0)
    deltas = []
    if prev_files:
        for rel, size in current_files.items():
            old = _audit_int(prev_files.get(rel), 0)
            d = int(size) - old
            if d:
                deltas.append({"path": rel, "delta": d, "before": old, "after": int(size), "category": _audit_category(rel)})
        for rel, old in prev_files.items():
            if rel not in current_files:
                deltas.append({"path": rel, "delta": -_audit_int(old), "before": _audit_int(old), "after": 0, "category": _audit_category(rel)})
        deltas.sort(key=lambda r: abs(int(r.get("delta", 0))), reverse=True)
    return {
        "available": bool(prev_files and prev_ts),
        "age_sec": max(0.0, time.time() - prev_ts) if prev_ts else None,
        "disk_used_delta": int(current_disk_used) - prev_used if prev_used else None,
        "file_deltas": deltas[:20],
    }


def _audit_save_baseline(files: dict[str, int], disk_used: int) -> None:
    # 64KB 이상만 저장해 상태파일 자체가 새 디스크 문제를 만들지 않게 제한한다.
    rows = [(_audit_rel(path), int(size)) for path, size in files.items() if int(size) >= 64 * 1024]
    rows.sort(key=lambda kv: kv[1], reverse=True)
    write_json(BOT_DIR / GUARD_DEEP_AUDIT_STATE_FILE, {
        "schema": "guard_deep_audit_state_v928",
        "ts": time.time(),
        "time": now(),
        "disk_used": int(disk_used),
        "files": dict(rows[:5000]),
    })


def _audit_suspicions(report: dict) -> list[str]:
    out = []
    sample = report.get("sample") or {}
    delta = _audit_int(sample.get("disk_used_delta"), 0)
    if delta > 25 * 1024 * 1024:
        out.append(f"짧은 표본 동안 디스크 사용량이 {_fmt_bytes(delta)} 증가")
    growth = [r for r in sample.get("file_deltas", []) if _audit_int(r.get("delta"), 0) > 5 * 1024 * 1024]
    if growth:
        out.append("빠르게 커진 파일 있음: " + ", ".join(f"{r['path']} +{_fmt_bytes(r['delta'])}" for r in growth[:3]))
    deleted_bytes = _audit_int((report.get("open_fds") or {}).get("deleted_bytes"), 0)
    if deleted_bytes > 20 * 1024 * 1024:
        out.append(f"삭제됐지만 프로세스가 잡고 있는 파일 {_fmt_bytes(deleted_bytes)}")
    journal = _audit_int((report.get("areas") or {}).get("journal_bytes"), 0)
    if journal > 512 * 1024 * 1024:
        out.append(f"systemd journal 사용량 큼: {_fmt_bytes(journal)}")
    dup = [r for r in report.get("services", []) if _audit_int(r.get("process_count"), 0) > 1]
    if dup:
        out.append("중복 프로세스 의심: " + ", ".join(f"{r['component']} {r['process_count']}개" for r in dup[:6]))
    slow = [r for r in report.get("workers", []) if _audit_float(r.get("status_age_sec"), 999999.0) < 900000 and (_audit_float(r.get("cycle_sec"), 0.0) > 30 or _audit_float(r.get("status_age_sec"), 0.0) > 60)]
    if slow:
        out.append("느린 작업자: " + ", ".join(f"{r['name']} cycle {r.get('cycle_sec')}s/age {r.get('status_age_sec'):.1f}s" for r in slow[:5]))
    resets = _audit_int((report.get("categories") or {}).get("paper_runtime_reset", {}).get("bytes"), 0)
    if resets > 100 * 1024 * 1024:
        out.append(f"paper runtime reset 백업 누적 {_fmt_bytes(resets)}")
    if not out:
        out.append("현재 20초 표본에서 단일 급증 원인은 확정되지 않음. 이전 감사 대비 증가량을 다음 호출에서 대조")
    return out


def _audit_format(report: dict) -> str:
    r0 = report.get("resource_before") or {}
    r1 = report.get("resource_after") or {}
    sample = report.get("sample") or {}
    prev = report.get("previous") or {}
    lines = [
        f"🔬 작업자·디스크 통합감사 /gdeep_audit · {VERSION}",
        f"- 읽기 전용 / 표본 {report.get('sample_sec')}초 / 삭제·정리 0건",
        f"- 디스크: 사용 {_fmt_bytes(r1.get('disk_used',0))} / 남음 {_fmt_bytes(r1.get('disk_free',0))} / {r1.get('disk_pct',0):.1f}%",
        f"- 표본 변화: 사용량 {_audit_fmt_delta(sample.get('disk_used_delta',0))}",
    ]
    if prev.get("available"):
        d = prev.get("disk_used_delta")
        lines.append(f"- 이전 감사 대비: {prev.get('age_sec',0)/60:.1f}분 / 디스크 {_audit_fmt_delta(d or 0)}")
    lines += ["", "[판정]"] + [f"- {x}" for x in report.get("suspicions", [])]

    lines += ["", "[느린 작업자 TOP]"]
    for row in (report.get("workers") or [])[:9]:
        cycle = row.get("cycle_sec")
        cycle_text = "-" if cycle is None or cycle < 0 else f"{cycle:.1f}s"
        lines.append(
            f"- {row['name']}: cycle {cycle_text} / status age {row['status_age_sec']:.1f}s / CPU {row['cpu_pct']:.1f}% / canonical RSS {_fmt_bytes(row['rss_bytes'])} / worker self-sample {(_fmt_bytes(row.get('status_rss_bytes',0)) if row.get('status_rss_bytes',0) else 'not_published')} / proc {row['process_count']} / phase {row.get('phase','-')}"
        )

    lines += ["", "[중복·서비스]"]
    duplicate_found = False
    for row in report.get("services", []):
        if row.get("component") in {"main", "paper", "guard", "ws", "micro", *WORKER_SPECS.keys()} and (_audit_int(row.get("process_count"),0) != 1 or _audit_int(row.get("restart_count"),0) > 0):
            duplicate_found = True
            lines.append(f"- {row['component']}: svc {row['active']}/{row['sub']} / proc {row['process_count']} / pid {row.get('pids') or '-'} / restart {row['restart_count']} / mem {_fmt_bytes(row['memory_bytes'])}")
    if not duplicate_found:
        lines.append("- 확인된 관리대상 중복 프로세스 없음")

    lines += ["", f"[파일 증가 TOP · {report.get('sample_sec')}초]"]
    growth_rows = sample.get("file_deltas", [])
    if not growth_rows:
        lines.append("- BOT_DIR 안에서 크기 변화 파일 없음")
    else:
        for row in growth_rows[:12]:
            d = _audit_int(row.get("delta"))
            owner = row.get("owners") or []
            owner_text = ",".join(str(x.get("pid")) for x in owner) if owner else "-"
            lines.append(f"- {row['path']}: {_audit_fmt_delta(d)} / {row['category']} / writer PID {owner_text}")
    log_growth = sample.get("var_log_file_deltas", [])
    if log_growth:
        lines += ["", f"[/var/log 증가 TOP · {report.get('sample_sec')}초]"]
        for row in log_growth[:8]:
            d = _audit_int(row.get("delta"))
            owner = row.get("owners") or []
            owner_text = ",".join(str(x.get("pid")) for x in owner) if owner else "-"
            lines.append(f"- {row['path']}: {_audit_fmt_delta(d)} / writer PID {owner_text}")

    # v1016: read the candle writer's own proof. lsof sampling often misses an
    # append-only file because it is opened only for milliseconds. The status
    # writer is the canonical evidence for PID/source/operation bytes/reset.
    candle_status=read_json(BOT_DIR / "clean_candle_status.json") or {}
    if isinstance(candle_status,dict):
        lines += ["", "[Candle delta v1016 증거]"]
        lines.append(
            f"- writer PID {candle_status.get('delta_writer_pid_v1016','-')} / version {candle_status.get('delta_writer_version_v1016','-')} / build {candle_status.get('delta_writer_build_v1016','-')}"
        )
        lines.append(f"- source {candle_status.get('delta_writer_source_v1016','-')} / base {candle_status.get('delta_base_checkpoint_id_v1016','-')}")
        lines.append(
            f"- changed {candle_status.get('delta_changed_tickers_v1016',0)} / prepared {candle_status.get('delta_prepared_records_v1016',0)} / appended {candle_status.get('delta_appended_records_v1016',0)} records · {_fmt_bytes(candle_status.get('delta_appended_bytes_v1016',0))}"
        )
        lines.append(
            f"- ops avg/max {candle_status.get('delta_avg_ops_v1016',0)}/{candle_status.get('delta_max_ops_v1016',0)} / record avg/max {_fmt_bytes(candle_status.get('delta_avg_record_bytes_v1016',0))}/{_fmt_bytes(candle_status.get('delta_max_record_bytes_v1016',0))}"
        )
        lines.append(
            f"- delta before/projected/after {_fmt_bytes(candle_status.get('delta_size_before_v1016',0))}/{_fmt_bytes(candle_status.get('delta_projected_bytes_v1016',0))}/{_fmt_bytes(candle_status.get('delta_size_after_v1016',0))} / cap {_fmt_bytes(candle_status.get('delta_max_bytes_v1016',0))}"
        )
        lines.append(
            f"- checkpoint due={candle_status.get('checkpoint_due_v1016')} reason={candle_status.get('checkpoint_reason_v1016') or '-'} success={candle_status.get('checkpoint_success_v1016')} error={candle_status.get('checkpoint_error_v1016') or '-'}"
        )
        lines.append(
            f"- reset count {candle_status.get('reset_count_v1016',0)} / last bytes {_fmt_bytes(candle_status.get('last_reset_bytes_v1016',0))} / reset before→after {_fmt_bytes(candle_status.get('checkpoint_reset_before_bytes_v1016',0))}→{_fmt_bytes(candle_status.get('checkpoint_reset_after_bytes_v1016',0))}"
        )

    compact = report.get('runtime_compaction_v928') or {}
    st = compact.get('strategy') if isinstance(compact.get('strategy'), dict) else {}
    rt = compact.get('target_router') if isinstance(compact.get('target_router'), dict) else {}
    lines += ['', '[v928 경량화 상태]']
    if not st and not rt:
        lines.append('- v928 worker status 생성 대기')
    else:
        if st:
            fb = st.get('file_bytes') if isinstance(st.get('file_bytes'), dict) else {}
            hold = st.get('hold') if isinstance(st.get('hold'), dict) else {}
            lines.append(f"- strategy cycle {st.get('cycle_sec','-')}s / trace {_fmt_bytes(fb.get('single_pass_trace',0))} / reject {_fmt_bytes(fb.get('reject_summary',0))}")
            lines.append(f"- S1 hold {hold.get('count',0)}개 / 원본추정 {_fmt_bytes(hold.get('full_row_bytes_before_v928',0))} → compact {_fmt_bytes(hold.get('compact_row_bytes_after_v928',0))} / JSONL mirror retired")
        if rt:
            lines.append(f"- target_router source {rt.get('recheck_source','-')} / source rows {rt.get('recheck_source_rows',0)} / queue {_fmt_bytes(rt.get('queue_file_bytes',0))}")
            lines.append(f"- full JSONL 매 cycle 읽기: {rt.get('full_jsonl_read_each_cycle')} / candidate lite {_fmt_bytes(rt.get('candidate_lite_file_bytes',0))}")

    areas = report.get("areas") or {}
    lines += [
        "",
        "[현재 용량 위치]",
        f"- 봇폴더: {_fmt_bytes(areas.get('bot_dir_bytes',0))}",
        f"- 봇 상위 홈: {_fmt_bytes(areas.get('bot_parent_bytes',0))}",
        f"- /var/log: {_fmt_bytes(areas.get('var_log_bytes',0))}",
        f"- systemd journal: {_fmt_bytes(areas.get('journal_bytes',0))}",
        f"- /var/cache: {_fmt_bytes(areas.get('var_cache_bytes',0))} / docker: {_fmt_bytes(areas.get('docker_bytes',0))}",
        f"- /tmp: {_fmt_bytes(areas.get('tmp_bytes',0))} / /var/tmp: {_fmt_bytes(areas.get('var_tmp_bytes',0))}",
    ]
    lines += ["", "[봇폴더 종류별]"]
    for cat, row in list((report.get("categories") or {}).items())[:10]:
        lines.append(f"- {cat}: {_fmt_bytes(row.get('bytes',0))} / {row.get('count',0)}개")

    fd = report.get("open_fds") or {}
    lines += ["", "[삭제됐지만 열린 파일]"]
    if not fd.get("deleted"):
        lines.append("- 없음")
    else:
        lines.append(f"- 합계 {_fmt_bytes(fd.get('deleted_bytes',0))} / {len(fd.get('deleted') or [])}개")
        for row in (fd.get("deleted") or [])[:8]:
            lines.append(f"- PID {row['pid']} / {_fmt_bytes(row['bytes'])} / {row['target']}")

    lines += ["", "[큰 파일 TOP]"]
    for row in (report.get("top_files") or [])[:12]:
        lines.append(f"- {row['path']}: {_fmt_bytes(row['bytes'])} / {row['category']}")
    if report.get("var_log_top_files"):
        lines += ["", "[/var/log 큰 파일 TOP]"]
        for row in (report.get("var_log_top_files") or [])[:8]:
            lines.append(f"- {row['path']}: {_fmt_bytes(row['bytes'])}")
    lines += [
        "",
        "[보존]",
        "- OPEN/CLOSED/trade_log/score 핵심 원장 수정·삭제 없음",
        f"- 전체 JSON: {GUARD_DEEP_AUDIT_JSON}",
        f"- 전체 TXT: {GUARD_DEEP_AUDIT_TEXT}",
        "- 다음 호출은 이전 감사 대비 증가량까지 비교",
    ]
    return "\n".join(lines)


def gdeep_audit_text(sample_sec: int = 20) -> str:
    sample_sec = max(5, min(30, _audit_int(sample_sec, 20)))
    t0 = perf_now()
    before_res = server_resource_snapshot()
    before_scan = _audit_scan_files(BOT_DIR, max_files=60000)
    before_var_log = _audit_scan_files(Path("/var/log"), max_files=25000)
    prev_map = {_audit_rel(k): int(v) for k, v in before_scan.get("files", {}).items() if int(v) >= 64 * 1024}
    previous = _audit_previous_delta(prev_map, _audit_int(before_res.get("disk_used")))
    proc_rows = _audit_proc_rows()
    workers = _audit_worker_rows(proc_rows)
    services = _audit_service_rows(proc_rows)
    journal_bytes, journal_text = _audit_journal_bytes()
    areas = {
        "bot_dir_bytes": _audit_int(before_scan.get("total")),
        "bot_parent_bytes": _audit_du_bytes(BOT_DIR.parent, timeout=14),
        "var_log_bytes": _audit_du_bytes(Path("/var/log"), timeout=12),
        "journal_bytes": journal_bytes,
        "journal_text": journal_text,
        "var_cache_bytes": _audit_du_bytes(Path("/var/cache"), timeout=10),
        "docker_bytes": _audit_du_bytes(Path("/var/lib/docker"), timeout=10),
        "tmp_bytes": _audit_du_bytes(Path("/tmp"), timeout=8),
        "var_tmp_bytes": _audit_du_bytes(Path("/var/tmp"), timeout=8),
    }
    # 실제 증가 파일을 잡기 위한 짧은 동일구간 재측정.
    time.sleep(sample_sec)
    after_res = server_resource_snapshot()
    after_scan = _audit_scan_files(BOT_DIR, max_files=60000)
    after_var_log = _audit_scan_files(Path("/var/log"), max_files=25000)
    fd_snapshot = _audit_open_fd_snapshot()
    file_deltas = _audit_file_deltas(before_scan.get("files", {}), after_scan.get("files", {}), fd_snapshot.get("owners", {}), limit=24)
    var_log_deltas = _audit_file_deltas(before_var_log.get("files", {}), after_var_log.get("files", {}), fd_snapshot.get("owners", {}), limit=16)
    report = {
        "schema": "guard_deep_runtime_disk_audit_v928",
        "time": now(),
        "ts": time.time(),
        "guard_version": VERSION,
        "sample_sec": sample_sec,
        "elapsed_sec": perf_now() - t0,
        "read_only": True,
        "resource_before": before_res,
        "resource_after": after_res,
        "sample": {
            "disk_used_delta": _audit_int(after_res.get("disk_used")) - _audit_int(before_res.get("disk_used")),
            "disk_free_delta": _audit_int(after_res.get("disk_free")) - _audit_int(before_res.get("disk_free")),
            "bot_dir_delta": _audit_int(after_scan.get("total")) - _audit_int(before_scan.get("total")),
            "file_deltas": file_deltas,
            "var_log_file_deltas": var_log_deltas,
            "scan_before": {k: v for k, v in before_scan.items() if k != "files"},
            "scan_after": {k: v for k, v in after_scan.items() if k != "files"},
        },
        "previous": previous,
        "workers": workers,
        "services": services,
        "processes": proc_rows,
        "areas": areas,
        "categories": _audit_category_totals(after_scan.get("files", {})),
        "top_files": _audit_top_files(after_scan.get("files", {}), limit=24),
        "var_log_top_files": _audit_top_files(after_var_log.get("files", {}), limit=16),
        "open_fds": fd_snapshot,
        "runtime_compaction_v928": {
            "strategy": read_json(BOT_DIR / "clean_strategy_storage_status_v928.json"),
            "target_router": read_json(BOT_DIR / "clean_target_router_compact_status_v928.json"),
            "storage_fix": read_json(BOT_DIR / V928_STORAGE_FIX_JSON),
        },
    }
    report["suspicions"] = _audit_suspicions(report)
    text = _audit_format(report)
    try:
        write_json(BOT_DIR / GUARD_DEEP_AUDIT_JSON, report)
        (BOT_DIR / GUARD_DEEP_AUDIT_TEXT).write_text(text + "\n", encoding="utf-8")
        current_map = {_audit_rel(k): int(v) for k, v in after_scan.get("files", {}).items()}
        _audit_save_baseline(current_map, _audit_int(after_res.get("disk_used")))
    except Exception as exc:
        text += f"\n- 감사 결과파일 저장 실패: {exc.__class__.__name__}: {str(exc)[:160]}"
    return text



# =============================================================================
# guard v2.5.119 / v1063: CORE V2 exact reset/rebreak shadow verifier
# - Reads live canonical files only.
# - Never writes OPEN/CLOSED/decision/performance ledgers.
# - Writes the audit report outside BOT_DIR under ~/coinbot_core_v2_shadow_output.
# - Compares current Strategy S1 contract with a stricter future CORE V2 contract:
#   universal cooldown + actual entry-price RR + same-ticker + source contract.
# =============================================================================
CORE_V2_SHADOW_SCHEMA_V1061 = 'coinbot_core_v2_shadow_report_v1063'
CORE_V2_SHADOW_OUTPUT_DIR_V1061 = BOT_DIR.parent / 'coinbot_core_v2_shadow_output'


def _v1061_num(*values, default=None):
    for value in values:
        if value in (None, '', [], {}):
            continue
        try:
            return float(str(value).replace(',', '').replace('%', '').strip())
        except (TypeError, ValueError):
            continue
    return default


def _v1061_bool(*values):
    for value in values:
        if isinstance(value, bool):
            return value
    return None


def _v1061_ticker(value) -> str:
    text = str(value or '').strip().upper().replace('/', '-').replace('_', '-')
    parts = [p for p in text.split('-') if p]
    if len(parts) >= 2:
        non_krw = [p for p in parts if p != 'KRW']
        text = non_krw[-1] if non_krw else parts[-1]
    if text.endswith('KRW') and len(text) > 3:
        text = text[:-3]
    return text


def _v1061_rows(obj):
    if isinstance(obj, list):
        return [dict(x) for x in obj if isinstance(x, dict)]
    if isinstance(obj, dict):
        for key in ('rows', 'items', 'candidates', 'active_rows', 'display_rows', 'top_candidates'):
            value = obj.get(key)
            if isinstance(value, list):
                return [dict(x) for x in value if isinstance(x, dict)]
        if obj and all(isinstance(v, dict) for v in obj.values()):
            rows = []
            for key, value in obj.items():
                row = dict(value)
                row.setdefault('pos_id', key)
                rows.append(row)
            return rows
    return []


def _v1061_dict(*values):
    for value in values:
        if isinstance(value, dict):
            return value
    return {}


def _v1061_file_age(path: Path):
    try:
        return max(0.0, time.time() - path.stat().st_mtime)
    except OSError:
        return None


def _v1061_gate(row):
    return _v1061_dict(row.get('swing_entry_gate_v977'))


def _v1061_trigger_gate(row):
    gate = _v1061_gate(row)
    diag = _v1061_dict(row.get('paper_final_safety_diagnostics'))
    ctx = _v1061_dict(row.get('entry_context'))
    return _v1061_dict(
        diag.get('trigger_gate'),
        row.get('trigger_gate_v738'),
        row.get('trigger_gate_v790'),
        ctx.get('trigger_gate_v738'),
        gate.get('trigger_gate'),
    )


def _v1061_structure(row):
    gate = _v1061_gate(row)
    plan = _v1061_dict(row.get('swing_structure_plan_v977'), gate.get('structure_plan'))
    levels = _v1061_dict(row.get('structure_levels'))
    trigger = _v1061_num(
        row.get('swing_trigger_price_v977'), row.get('trigger_price'),
        gate.get('trigger_price'), plan.get('trigger_price'), levels.get('trigger_price'),
    )
    invalid = _v1061_num(
        row.get('swing_invalid_price_v977'), row.get('invalid_price'),
        gate.get('invalid_price'), plan.get('invalid_price'), levels.get('invalid_price'),
    )
    target = _v1061_num(
        row.get('swing_target_price_v977'), row.get('target_price'),
        gate.get('target_price'), plan.get('target_price'), levels.get('target_price'),
    )
    return trigger, invalid, target


def _v1061_entry_price(row):
    trigger_gate = _v1061_trigger_gate(row)
    ctx = _v1061_dict(row.get('entry_context'))
    return _v1061_num(
        trigger_gate.get('entry_price'), trigger_gate.get('current_confirmation_price'),
        row.get('entry_price'), row.get('live_price'), row.get('current_price'),
        row.get('price'), ctx.get('entry_price'), ctx.get('live_price'), ctx.get('current_price'), ctx.get('price'),
    )


def _v1061_actual_rr(entry, invalid, target):
    if entry is None or invalid is None or target is None:
        return None
    if not (invalid < entry < target):
        return None
    risk = entry - invalid
    return None if risk <= 0 else (target - entry) / risk


def _v1061_stage(row) -> str:
    return str(row.get('s_stage') or row.get('candidate_stage') or row.get('candidate_grade') or row.get('stage') or row.get('grade') or '').strip().upper()


def _v1061_strategy_contract(row):
    gate = _v1061_gate(row)
    mode = str(row.get('strategy_mode') or row.get('strategy_mode_v977') or gate.get('strategy_mode') or '').strip().upper()
    decision_key = str(row.get('swing_gate_decision_key_v977') or row.get('paper_decision_key_v926') or gate.get('decision_key') or '').strip()
    state = str(gate.get('final_trade_state') or row.get('final_trade_state') or '').strip()
    checks = {
        'stage_s1': _v1061_stage(row) == 'S1',
        'mode': mode == 'ALT_SWING_V977',
        'schema': gate.get('schema') == 'swing_entry_gate_v977_single_owner',
        'hard_pass': gate.get('hard_pass') is True,
        'final_state': state == 'S1_PASS',
        'decision_key': bool(decision_key),
        'source_fresh': gate.get('source_fresh') is True or row.get('source_fresh') is True,
        'open_flags': row.get('open_eligible') is not False and row.get('paper_bot_open') is not False and row.get('trade_ready') is not False,
    }
    return not [name for name, ok in checks.items() if not ok], checks, decision_key


def _v1061_limits_from_active_paper():
    result = {'max_open_strict': None, 'max_new_per_cycle': None, 'source': PAPER_ACTIVE_FILE}
    path = BOT_DIR / PAPER_ACTIVE_FILE
    try:
        raw = path.read_text(encoding='utf-8', errors='ignore')
    except OSError:
        return result
    for key in ('max_open_strict', 'max_new_per_cycle'):
        match = re.search(rf'[\"\']{re.escape(key)}[\"\']\s*:\s*(-?\d+)', raw)
        if match:
            result[key] = int(match.group(1))
    result['unlimited_open'] = result.get('max_open_strict') == 0
    result['unlimited_cycle'] = result.get('max_new_per_cycle') == 0
    return result


def _v1061_route(row) -> str:
    return ' '.join(str(row.get(k) or '') for k in ('strategy', 'strategy_key', 'strategy_label', 'final_entry_label', 'route', 'source_lane', '_source_file')).strip()



def _v1063_text(value) -> str:
    if value in (None, '', '-', [], {}):
        return ''
    return str(value).strip()


def _v1063_first_dict(*values):
    for value in values:
        if isinstance(value, dict) and value:
            return value
    return {}


def _v1063_candidate_key(row, gate):
    occurrence = _v1063_first_dict(
        row.get('trigger_occurrence_v1037'),
        gate.get('trigger_occurrence_v1037'),
        ((_v1061_dict(gate.get('structure_plan'))).get('trigger_occurrence_v1037')),
    )
    evidence = _v1063_first_dict(row.get('entry_evidence_v983'), row.get('entry_evidence'))
    for value in (
        occurrence.get('candidate_key'),
        row.get('trigger_occurrence_candidate_key_v1037'),
        row.get('candidate_entry_build_key'),
        row.get('entry_build_key'),
        evidence.get('candidate_key'),
        row.get('event_id'),
        row.get('event_key'),
    ):
        text = _v1063_text(value)
        if text:
            return text
    return ''


def _v1063_loss_reentry_gate(row, prior, trigger_gate, decision_key):
    gate = _v1061_gate(row)
    plan = _v1061_dict(gate.get('structure_plan'))
    occurrence = _v1063_first_dict(
        gate.get('trigger_occurrence_v1037'),
        row.get('trigger_occurrence_v1037'),
        plan.get('trigger_occurrence_v1037'),
    )
    ticker = _v1061_ticker(row.get('ticker') or row.get('market') or row.get('symbol'))
    candidate = _v1063_candidate_key(row, gate)
    trigger_price = _v1061_num(
        trigger_gate.get('trigger_price'), occurrence.get('trigger_price'),
        row.get('swing_trigger_price_v977'), row.get('trigger_price'),
        gate.get('trigger_price'), plan.get('trigger_price'),
        default=0.0,
    ) or 0.0
    trigger_reached = trigger_gate.get('trigger_reached') is True
    current = {
        'ticker': ticker,
        'candidate_key': candidate or None,
        'decision_key': decision_key or None,
        'trigger_price': trigger_price or None,
        'trigger_reached': trigger_reached,
        'occurrence': occurrence or None,
    }
    if not isinstance(prior, dict) or not prior:
        return {
            'schema': 'loss_reentry_gate_v1037',
            'allowed': True,
            'state': 'NO_PRIOR_LOSS',
            'reason': None,
            'current': current,
            'prior': None,
            'requirements': {},
        }
    prior_candidate = _v1063_text(prior.get('candidate_key'))
    prior_decision = _v1063_text(prior.get('decision_key'))
    prior_closed = _v1061_num(prior.get('closed_ts'), default=0.0) or 0.0
    prior_trigger = _v1061_num(prior.get('trigger_price'), default=0.0) or 0.0
    prior_exit = _v1061_num(prior.get('exit_price'), default=0.0) or 0.0
    reset_ts = _v1061_num(occurrence.get('reset_ts'), default=0.0) or 0.0
    rebreak_ts = _v1061_num(occurrence.get('rebreak_ts'), default=0.0) or 0.0
    plan_frozen_ts = _v1061_num(occurrence.get('plan_frozen_ts'), default=0.0) or 0.0
    exit_reset = bool(prior_closed > 0 and prior_trigger > 0 and prior_exit > 0 and prior_exit < prior_trigger)
    occurrence_reset = bool(reset_ts > prior_closed > 0)
    occurrence_rebreak = bool(str(occurrence.get('kind') or '') == 'REBREAK' and rebreak_ts > reset_ts > prior_closed > 0)
    initial_after_exit_reset = bool(
        exit_reset
        and str(occurrence.get('kind') or '') == 'INITIAL_OR_MIGRATED_ABOVE'
        and plan_frozen_ts > prior_closed > 0
        and trigger_reached
    )
    requirements = {
        'prior_identity_complete': bool(prior.get('identity_complete') and prior_candidate and prior_decision and prior_trigger > 0 and prior_closed > 0),
        'current_candidate_key_ready': bool(candidate),
        'current_decision_key_ready': bool(decision_key),
        'new_candidate_key': bool(candidate and prior_candidate and candidate != prior_candidate),
        'new_decision_key': bool(decision_key and prior_decision and decision_key != prior_decision),
        'reset_after_loss': bool(exit_reset or occurrence_reset),
        'trigger_rebreak_after_reset': bool(occurrence_rebreak or initial_after_exit_reset),
        'paper_trigger_reached': trigger_reached,
    }
    allowed = all(requirements.values())
    if not requirements['prior_identity_complete']:
        state, reason = 'PRIOR_IDENTITY_MISSING_BLOCK', '이전 손실 identity 근거 불완전'
    elif not requirements['current_candidate_key_ready'] or not requirements['current_decision_key_ready']:
        state, reason = 'CURRENT_IDENTITY_MISSING', '현재 candidate 또는 decision key 누락'
    elif not requirements['new_candidate_key'] or not requirements['new_decision_key']:
        state, reason = 'SAME_EVENT_BLOCK', '이전 손실과 같은 candidate 또는 decision 사건'
    elif not requirements['reset_after_loss']:
        state, reason = 'WAIT_TRIGGER_RESET', '이전 손실 뒤 trigger 아래 리셋 미확인'
    elif not requirements['trigger_rebreak_after_reset'] or not requirements['paper_trigger_reached']:
        state, reason = 'WAIT_TRIGGER_REBREAK', '리셋 이후 새 trigger 재돌파 미확인'
    else:
        state, reason = 'NEW_TRIGGER_REBREAK_CONFIRMED', None
    return {
        'schema': 'loss_reentry_gate_v1037',
        'allowed': allowed,
        'state': state,
        'reason': reason,
        'current': current,
        'prior': prior,
        'requirements': requirements,
        'policy': 'same Paper v1037 reset/rebreak contract; cooldown flag alone is observation only',
    }

def _v1061_run_shadow(ticker_filter: str = ''):
    ticker_filter = _v1061_ticker(ticker_filter)
    hold_path = BOT_DIR / 'paper_s1_hold_cache.json'
    risk_path = BOT_DIR / 'clean_risk_filter_cache.json'
    paper_status_path = BOT_DIR / 'paper_bot_status.json'
    open_path = BOT_DIR / 'paper_bot_open.json'

    hold_obj = read_json(hold_path) or {}
    risk_obj = read_json(risk_path) or {}
    paper_status = read_json(paper_status_path) or {}
    open_obj = read_json(open_path) or {}
    rows = _v1061_rows(hold_obj)
    if ticker_filter:
        rows = [row for row in rows if _v1061_ticker(row.get('ticker') or row.get('market') or row.get('symbol')) == ticker_filter]
    open_rows = _v1061_rows(open_obj)
    open_tickers = {
        _v1061_ticker(row.get('ticker') or row.get('market') or row.get('symbol'))
        for row in open_rows
        if _v1061_ticker(row.get('ticker') or row.get('market') or row.get('symbol'))
    }
    cooldown_map = risk_obj.get('cooldown') if isinstance(risk_obj.get('cooldown'), dict) else {}
    prior_loss_map = risk_obj.get('last_loss_event_by_ticker') if isinstance(risk_obj.get('last_loss_event_by_ticker'), dict) else {}
    risk_contract = paper_status.get('risk_paper_contract_v1059') if isinstance(paper_status.get('risk_paper_contract_v1059'), dict) else {}
    pick_stats = paper_status.get('pick_stats') if isinstance(paper_status.get('pick_stats'), dict) else {}

    risk_ready = bool(
        risk_contract.get('schema') == 'paper_risk_contract_status_v1059'
        and risk_contract.get('ready') is True
        and risk_contract.get('closed_signature_match') is True
        and risk_contract.get('consumer_evidence_present') is True
    )

    results = []
    blockers_count = {}
    strategy_pass_count = 0
    strict_pass_count = 0
    extra_block_count = 0
    key_missing_count = 0
    structure_missing_count = 0
    hot_rows = hot_extra_block = hot_cooldown = 0
    reentry_allowed_new_trigger = 0
    reentry_blocked = 0
    reentry_no_prior = 0

    for row in rows:
        ticker = _v1061_ticker(row.get('ticker') or row.get('market') or row.get('symbol'))
        current_pass, current_checks, decision_key = _v1061_strategy_contract(row)
        if current_pass:
            strategy_pass_count += 1
        if not decision_key:
            key_missing_count += 1
        trigger, invalid, target = _v1061_structure(row)
        structure_ok = bool(trigger is not None and invalid is not None and target is not None and invalid < trigger < target)
        if not structure_ok:
            structure_missing_count += 1
        entry = _v1061_entry_price(row)
        actual_rr = _v1061_num(row.get('actual_entry_rr_v1034'))
        if actual_rr is None:
            actual_rr = _v1061_actual_rr(entry, invalid, target)
        trigger_gate = _v1061_trigger_gate(row)
        chase = _v1061_num(trigger_gate.get('trigger_gap_pct'), row.get('trigger_gap_pct'))
        spread = _v1061_num(row.get('spread_pct'), row.get('micro_spread_pct'), row.get('orderbook_spread_pct'))
        cooldown_item = cooldown_map.get(ticker) if isinstance(cooldown_map.get(ticker), dict) else {}
        cooldown_active = bool(cooldown_item)
        same_open = ticker in open_tickers
        prior_loss = prior_loss_map.get(ticker) if isinstance(prior_loss_map.get(ticker), dict) else {}
        reentry = _v1063_loss_reentry_gate(row, prior_loss, trigger_gate, decision_key)
        reentry_state = str(reentry.get('state') or 'UNKNOWN')
        if reentry_state == 'NEW_TRIGGER_REBREAK_CONFIRMED':
            reentry_allowed_new_trigger += 1
        elif reentry_state == 'NO_PRIOR_LOSS':
            reentry_no_prior += 1
        elif reentry.get('allowed') is not True:
            reentry_blocked += 1
        route = _v1061_route(row)
        hot = 'hot-rank' in route.lower() or 'hot_rank' in route.lower() or '급등 상위 재확인' in route
        if hot:
            hot_rows += 1
            if cooldown_active:
                hot_cooldown += 1

        blockers = []
        if not risk_ready:
            blockers.append('risk_source_not_ready')
        if not structure_ok:
            blockers.append('structure_incomplete')
        if same_open:
            blockers.append('same_ticker_open')
        # v1063 correction: cooldown presence is observation only.
        # Block only when the exact Paper v1037 reset/rebreak contract rejects it.
        if reentry.get('allowed') is not True:
            blockers.append('loss_reentry_blocked')
        if entry is None or entry <= 0:
            blockers.append('entry_price_missing')
        if actual_rr is None:
            blockers.append('actual_rr_missing')
        elif actual_rr < 1.5:
            blockers.append('actual_rr_below_1_5')
        if spread is None:
            blockers.append('spread_missing')
        elif spread > 1.2:
            blockers.append('spread_over_1_2')
        if chase is not None and chase > 0.6:
            blockers.append('trigger_chase_over_0_6')

        blockers = list(dict.fromkeys(blockers))
        strict_pass = bool(current_pass and not blockers)
        if strict_pass:
            strict_pass_count += 1
        if current_pass and not strict_pass:
            extra_block_count += 1
            if hot:
                hot_extra_block += 1
            for reason in blockers:
                blockers_count[reason] = int(blockers_count.get(reason, 0)) + 1

        results.append({
            'ticker': ticker,
            'route': route or None,
            'hot_rank': hot,
            'strategy_s1_pass': current_pass,
            'core_v2_shadow_pass': strict_pass,
            'difference': bool(current_pass != strict_pass),
            'blockers': blockers,
            'decision_key': decision_key or None,
            'structure': {'trigger': trigger, 'invalid': invalid, 'target': target, 'complete': structure_ok},
            'execution': {'entry_price': entry, 'actual_rr': round(actual_rr, 6) if actual_rr is not None else None, 'spread_pct': spread, 'trigger_chase_pct': chase},
            'risk': {
                'cooldown_active': cooldown_active,
                'same_ticker_open': same_open,
                'loss_reentry_allowed': reentry.get('allowed'),
                'loss_reentry_state': reentry_state,
                'loss_reentry_reason': reentry.get('reason'),
                'loss_reentry_requirements': reentry.get('requirements'),
            },
            'current_checks': current_checks,
        })

    sorted_blockers = sorted(blockers_count.items(), key=lambda kv: (-kv[1], kv[0]))
    diff_samples = [r for r in results if r.get('difference')][:12]
    limits = _v1061_limits_from_active_paper()
    source_ages = {
        's1_hold_sec': _v1061_file_age(hold_path),
        'risk_sec': _v1061_file_age(risk_path),
        'paper_status_sec': _v1061_file_age(paper_status_path),
        'open_sec': _v1061_file_age(open_path),
    }
    if not risk_ready:
        verdict = 'CHECK_RISK_SOURCE'
    elif not rows:
        verdict = 'READY_NO_CURRENT_S1'
    elif key_missing_count or structure_missing_count:
        verdict = 'CHECK_CONTRACT_MISSING'
    else:
        verdict = 'READY_WITH_SAMPLE'

    report = {
        'schema': CORE_V2_SHADOW_SCHEMA_V1061,
        'version': 'v1063',
        'guard_version': VERSION,
        'generated_ts': time.time(),
        'verdict': verdict,
        'ticker_filter': ticker_filter or None,
        'sources': {
            'paper_s1_hold_cache': {'path': str(hold_path), 'schema': hold_obj.get('schema'), 'age_sec': source_ages['s1_hold_sec']},
            'risk': {'path': str(risk_path), 'schema': risk_obj.get('schema'), 'age_sec': source_ages['risk_sec']},
            'paper_status': {'path': str(paper_status_path), 'age_sec': source_ages['paper_status_sec']},
            'paper_open': {'path': str(open_path), 'age_sec': source_ages['open_sec']},
        },
        'risk_paper_contract': {
            'ready': risk_ready,
            'schema': risk_contract.get('schema'),
            'closed_signature_match': risk_contract.get('closed_signature_match'),
            'consumer_evidence_present': risk_contract.get('consumer_evidence_present'),
            'latest_loss_selection': risk_contract.get('latest_loss_selection'),
            'reason': risk_contract.get('reason'),
        },
        'paper_last_cycle': {
            's1_seen': pick_stats.get('s1_seen'),
            'selected_s1': pick_stats.get('selected_s1'),
            'opened_count': paper_status.get('opened_count'),
            'elapsed_sec': paper_status.get('elapsed_sec'),
        },
        'counts': {
            'hold_rows': len(rows),
            'open_rows': len(open_rows),
            'strategy_s1_pass': strategy_pass_count,
            'core_v2_shadow_pass': strict_pass_count,
            'additional_block': extra_block_count,
            'decision_key_missing': key_missing_count,
            'structure_missing': structure_missing_count,
            'hot_rows': hot_rows,
            'hot_additional_block': hot_extra_block,
            'hot_cooldown_active': hot_cooldown,
            'reentry_allowed_new_trigger': reentry_allowed_new_trigger,
            'reentry_blocked': reentry_blocked,
            'reentry_no_prior_loss': reentry_no_prior,
        },
        'additional_blockers': dict(sorted_blockers),
        'limits': limits,
        'results': results,
        'live_trade_write_performed': False,
        'live_files_modified': [],
        'policy': 'read-only shadow; no OPEN/CLOSED/decision/performance mutation; auto-buy unchanged',
    }

    CORE_V2_SHADOW_OUTPUT_DIR_V1061.mkdir(parents=True, exist_ok=True)
    stamp = time.strftime('%Y%m%d_%H%M%S', time.localtime(report['generated_ts']))
    suffix = f'_{ticker_filter}' if ticker_filter else ''
    json_path = CORE_V2_SHADOW_OUTPUT_DIR_V1061 / f'core_v2_shadow_v1063_{stamp}{suffix}.json'
    latest_path = CORE_V2_SHADOW_OUTPUT_DIR_V1061 / 'core_v2_shadow_latest_v1063.json'
    payload = json.dumps(report, ensure_ascii=False, indent=2, default=str)
    json_path.write_text(payload, encoding='utf-8')
    latest_path.write_text(payload, encoding='utf-8')

    lines = [
        '🧪 CORE V2 정확 재진입 shadow /gcore_shadow · v1063',
        f'- 판정: {verdict}',
        f'- 대상: {ticker_filter or "현재 S1 전체"}',
        f'- 라이브 거래원장 쓰기: 0 / 자동매수 변경: 0',
        '',
        '[현재 → 새 본선 비교]',
        f'- S1 hold {len(rows)} / 현재 Strategy 계약통과 {strategy_pass_count}',
        f'- CORE V2 strict 통과 {strict_pass_count} / 추가 차단 {extra_block_count}',
        f'- 현재 OPEN {len(open_rows)} / Paper 최근 선택 {pick_stats.get("selected_s1", "-")}',
        f'- hot-rank S1 {hot_rows} / 추가 차단 {hot_extra_block} / cooldown 활성 {hot_cooldown}',
        '',
        '[Risk·계약]',
        f'- source {"READY" if risk_ready else "CHECK"} / signature {risk_contract.get("closed_signature_match")} / latest {risk_contract.get("latest_loss_selection") or "-"}',
        f'- 재진입: 새 trigger 허용 {reentry_allowed_new_trigger} / 차단 {reentry_blocked} / 이전손실 없음 {reentry_no_prior}',
        f'- key 누락 {key_missing_count} / 구조 누락 {structure_missing_count}',
        '',
        '[현재 한도]',
        f'- 전체 OPEN {limits.get("max_open_strict")} / cycle 신규 {limits.get("max_new_per_cycle")}',
        f'- 해석: {"둘 다 무제한" if limits.get("unlimited_open") and limits.get("unlimited_cycle") else "명시 한도 있음 또는 확인 필요"}',
    ]
    if sorted_blockers:
        lines += ['', '[추가 차단 사유]']
        labels = {
            'actual_rr_below_1_5': '실제 진입가 RR<1.5',
            'actual_rr_missing': '실제 RR 계산불가',
            'same_ticker_open': '동일종목 OPEN',
            'spread_missing': 'spread 누락',
            'spread_over_1_2': 'spread 초과',
            'trigger_chase_over_0_6': 'trigger 추격초과',
            'risk_source_not_ready': 'Risk source CHECK',
            'structure_incomplete': '구조 계약 누락',
            'entry_price_missing': '진입 예정가 누락',
            'loss_reentry_blocked': '손실 재진입 차단',
        }
        for reason, count in sorted_blockers[:8]:
            lines.append(f'- {labels.get(reason, reason)} {count}')
    if diff_samples:
        lines += ['', '[차이 표본]']
        for row in diff_samples[:6]:
            rr = row.get('execution', {}).get('actual_rr')
            reason = ', '.join(row.get('blockers') or [])
            state = (row.get('risk') or {}).get('loss_reentry_state') or '-'
            lines.append(f'- {row.get("ticker")}: RR {rr if rr is not None else "-"} / 재진입 {state} / {reason[:110]}')
    lines += [
        '',
        '[결과 파일]',
        f'- {json_path}',
        '- 다음: 과차단 제거 결과로 CORE V2 Candidate→Risk→Execution 전환 범위를 확정',
    ]
    return '\n'.join(lines), report


def _v1063_gcore_shadow_text(args=None) -> str:
    args = list(args or [])
    ticker = str(args[0]) if args else ''
    try:
        text, _report = _v1061_run_shadow(ticker)
        return text
    except Exception as exc:
        return '\n'.join([
            '🧪 ❌ CORE V2 shadow 실패',
            f'- {exc.__class__.__name__}: {exc}',
            '- 라이브 거래원장 쓰기 0',
            '- 확인: /gpaper_state /gstrategy_state /gworker_state',
        ])



# =============================================================================
# guard v2.5.120 / v1064: CORE V2 full lifecycle mirror shadow
