_V1064_CORE_SOURCE = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""Coinbot CORE V2 full lifecycle shadow v1064.\n\nRead-only against the live trading_bot directory. All state is written to a\nseparate output directory. The first target is faithful lifecycle mirroring and\nstage-by-stage parity, not stricter entry rules.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nimport re\nimport time\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Tuple\n\nSCHEMA = "coinbot_core_v2_full_shadow_v1064"\nVERSION = "v1064"\nDEFAULT_INTERVAL_SEC = 30.0\nMAX_EVENTS = 5000\nMAX_SEEN_KEYS = 20000\n\nSOURCE_SPECS: Dict[str, Dict[str, Any]] = {\n    "scanner": {\n        "owner": "scanner_worker",\n        "status": "clean_scanner_status.json",\n        "data": ["clean_scanner_market_cache.json", "clean_scanner_candidate_pool.json", "clean_scanner_hot_rank_cache.json"],\n    },\n    "candle": {\n        "owner": "candle_worker",\n        "status": "clean_candle_status.json",\n        "data": ["clean_candle_cache.json", "clean_candle_delta_v1014.jsonl"],\n    },\n    "market": {\n        "owner": "market_regime_worker",\n        "status": "clean_market_regime_status.json",\n        "data": ["clean_market_regime_cache.json"],\n    },\n    "feature": {\n        "owner": "feature_worker",\n        "status": "clean_feature_status.json",\n        "data": ["clean_feature_cache.json"],\n    },\n    "target_router": {\n        "owner": "target_router_worker",\n        "status": "clean_target_router_status.json",\n        "data": ["clean_target_router_queue.json", "clean_ws_targets.json", "clean_micro_targets.json"],\n    },\n    "orderflow": {\n        "owner": "orderflow_worker",\n        "status": "clean_orderflow_status.json",\n        "data": ["clean_orderflow_summary_cache.json", "clean_ws_live_cache.json", "clean_bithumb_micro_cache.json"],\n    },\n    "strategy": {\n        "owner": "strategy_worker",\n        "status": "clean_strategy_worker_status.json",\n        "data": ["paper_s1_hold_cache.json", "paper_candidates_latest.jsonl", "clean_strategy_swing_gate_status_v977.json"],\n    },\n    "risk": {\n        "owner": "risk_worker",\n        "status": "clean_risk_status.json",\n        "data": ["clean_risk_filter_cache.json"],\n    },\n    "paper": {\n        "owner": "paper_bot",\n        "status": "paper_bot_status.json",\n        "data": ["paper_bot_open.json", "paper_bot_closed.jsonl"],\n    },\n    "performance": {\n        "owner": "paper_bot_single_canonical_performance_writer",\n        "status": "canonical_performance_snapshot_v987.json",\n        "data": ["canonical_performance_snapshot_v987.json"],\n    },\n}\n\n\ndef _json_default(value: Any) -> Any:\n    if isinstance(value, Path):\n        return str(value)\n    return str(value)\n\n\ndef _atomic_write_json(path: Path, obj: Any) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    tmp = path.with_name(path.name + f".tmp.{os.getpid()}.{time.time_ns()}")\n    tmp.write_text(json.dumps(obj, ensure_ascii=False, indent=2, default=_json_default), encoding="utf-8")\n    os.replace(tmp, path)\n\n\ndef _append_jsonl(path: Path, obj: Mapping[str, Any]) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    payload = json.dumps(dict(obj), ensure_ascii=False, separators=(",", ":"), default=_json_default) + "\\n"\n    with path.open("a", encoding="utf-8") as handle:\n        handle.write(payload)\n\n\ndef _read_json(path: Path, default: Any = None) -> Any:\n    try:\n        if not path.exists() or not path.is_file():\n            return default\n        return json.loads(path.read_text(encoding="utf-8", errors="ignore"))\n    except (OSError, json.JSONDecodeError):\n        return default\n\n\ndef _read_jsonl_tail(path: Path, limit: int = 2000, max_bytes: int = 32 * 1024 * 1024) -> List[Dict[str, Any]]:\n    if not path.exists() or not path.is_file():\n        return []\n    try:\n        size = path.stat().st_size\n        take = min(size, max_bytes)\n        with path.open("rb") as handle:\n            if size > take:\n                handle.seek(size - take)\n                handle.readline()\n            data = handle.read(take)\n    except OSError:\n        return []\n    rows: List[Dict[str, Any]] = []\n    for raw in data.splitlines()[-limit:]:\n        try:\n            obj = json.loads(raw.decode("utf-8", errors="ignore"))\n        except json.JSONDecodeError:\n            continue\n        if isinstance(obj, dict):\n            rows.append(obj)\n    return rows\n\n\ndef _rows(obj: Any) -> List[Dict[str, Any]]:\n    if isinstance(obj, list):\n        return [dict(x) for x in obj if isinstance(x, dict)]\n    if not isinstance(obj, dict):\n        return []\n    for key in ("rows", "items", "candidates", "active_rows", "display_rows", "top_candidates", "positions", "open_positions"):\n        value = obj.get(key)\n        if isinstance(value, list):\n            return [dict(x) for x in value if isinstance(x, dict)]\n        if isinstance(value, dict):\n            out: List[Dict[str, Any]] = []\n            for k, v in value.items():\n                if isinstance(v, dict):\n                    row = dict(v)\n                    row.setdefault("pos_id", k)\n                    out.append(row)\n            return out\n    if obj and all(isinstance(v, dict) for v in obj.values()):\n        out = []\n        for key, value in obj.items():\n            row = dict(value)\n            row.setdefault("pos_id", key)\n            out.append(row)\n        return out\n    return []\n\n\ndef _num(*values: Any, default: Optional[float] = None) -> Optional[float]:\n    for value in values:\n        if value in (None, "", [], {}):\n            continue\n        try:\n            out = float(str(value).replace(",", "").replace("%", "").strip())\n            if math.isfinite(out):\n                return out\n        except (TypeError, ValueError):\n            continue\n    return default\n\n\ndef _bool(*values: Any) -> Optional[bool]:\n    for value in values:\n        if isinstance(value, bool):\n            return value\n    return None\n\n\ndef _text(*values: Any) -> str:\n    for value in values:\n        if value in (None, "", "-", [], {}):\n            continue\n        text = str(value).strip()\n        if text:\n            return text\n    return ""\n\n\ndef _dict(*values: Any) -> Dict[str, Any]:\n    for value in values:\n        if isinstance(value, dict):\n            return value\n    return {}\n\n\ndef _ticker(value: Any) -> str:\n    text = str(value or "").strip().upper().replace("/", "-").replace("_", "-")\n    parts = [part for part in text.split("-") if part]\n    if len(parts) >= 2:\n        non_krw = [part for part in parts if part != "KRW"]\n        text = non_krw[-1] if non_krw else parts[-1]\n    if text.endswith("KRW") and len(text) > 3:\n        text = text[:-3]\n    return text\n\n\ndef _parse_ts(*values: Any) -> float:\n    for value in values:\n        if value in (None, "", [], {}):\n            continue\n        if isinstance(value, (int, float)):\n            ts = float(value)\n            if ts > 1e12:\n                ts /= 1000.0\n            if ts > 1e9:\n                return ts\n        text = str(value).strip()\n        try:\n            ts = float(text)\n            if ts > 1e12:\n                ts /= 1000.0\n            if ts > 1e9:\n                return ts\n        except ValueError:\n            pass\n        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M:%S%z"):\n            try:\n                return datetime.strptime(text.replace(" KST", ""), fmt).timestamp()\n            except ValueError:\n                continue\n    return 0.0\n\n\ndef _age(path: Path, now_ts: Optional[float] = None) -> Optional[float]:\n    try:\n        return max(0.0, (now_ts or time.time()) - path.stat().st_mtime)\n    except OSError:\n        return None\n\n\ndef _sha12(path: Path, max_bytes: int = 4 * 1024 * 1024) -> str:\n    try:\n        size = path.stat().st_size\n        h = hashlib.sha256()\n        with path.open("rb") as handle:\n            if size > max_bytes:\n                handle.seek(max(0, size - max_bytes))\n            while True:\n                chunk = handle.read(1024 * 1024)\n                if not chunk:\n                    break\n                h.update(chunk)\n        return h.hexdigest()[:12]\n    except OSError:\n        return ""\n\n\ndef _identity(row: Mapping[str, Any]) -> Dict[str, Optional[str]]:\n    gate = _dict(row.get("swing_entry_gate_v977"))\n    occurrence = _dict(row.get("trigger_occurrence_v1037"), gate.get("trigger_occurrence_v1037"))\n    evidence = _dict(row.get("entry_evidence_v983"), row.get("entry_evidence"))\n    ticker = _ticker(row.get("ticker") or row.get("market") or row.get("symbol"))\n    candidate_key = _text(\n        occurrence.get("candidate_key"), row.get("trigger_occurrence_candidate_key_v1037"),\n        row.get("canonical_candidate_exact_key"), row.get("candidate_exact_key"), row.get("canonical_candidate_key"),\n        row.get("candidate_entry_build_key"), row.get("entry_build_key"), row.get("entry_build_exact_key"), evidence.get("candidate_key"),\n        row.get("event_id"), row.get("event_key"),\n    ) or None\n    decision_key = _text(\n        row.get("paper_decision_key_v926"), row.get("swing_gate_decision_key_v977"), gate.get("decision_key"),\n        evidence.get("decision_key"), row.get("canonical_decision_key"), row.get("decision_key"),\n    ) or None\n    pos_id = _text(row.get("pos_id"), row.get("position_id"), row.get("paper_pos_id_v926")) or None\n    if not pos_id and decision_key:\n        pos_id = f"decision:{decision_key}"\n    return {\n        "ticker": ticker,\n        "candidate_key": candidate_key,\n        "decision_key": decision_key,\n        "pos_id": pos_id,\n        "occurrence_key": _text(occurrence.get("occurrence_key"), occurrence.get("candidate_key")) or None,\n    }\n\n\ndef _structure(row: Mapping[str, Any]) -> Dict[str, Any]:\n    gate = _dict(row.get("swing_entry_gate_v977"))\n    plan = _dict(row.get("swing_structure_plan_v977"), gate.get("structure_plan"))\n    levels = _dict(row.get("structure_levels"))\n    return {\n        "trigger": _num(row.get("swing_trigger_price_v977"), row.get("trigger_price"), gate.get("trigger_price"), plan.get("trigger_price"), levels.get("trigger_price")),\n        "invalid": _num(row.get("swing_invalid_price_v977"), row.get("invalid_price"), gate.get("invalid_price"), plan.get("invalid_price"), levels.get("invalid_price"), row.get("stop_price")),\n        "target": _num(row.get("swing_target_price_v977"), row.get("target_price"), gate.get("target_price"), plan.get("target_price"), levels.get("target_price"), row.get("target1_price")),\n        "trigger_tf": _text(row.get("trigger_timeframe"), gate.get("trigger_timeframe"), plan.get("trigger_timeframe")) or None,\n        "invalid_tf": _text(row.get("invalid_timeframe"), gate.get("invalid_timeframe"), plan.get("invalid_timeframe")) or None,\n        "target_tf": _text(row.get("target_timeframe"), gate.get("target_timeframe"), plan.get("target_timeframe")) or None,\n        "source_fresh": _bool(gate.get("source_fresh"), row.get("source_fresh")),\n    }\n\n\ndef _entry(row: Mapping[str, Any]) -> Dict[str, Any]:\n    gate = _dict(row.get("swing_entry_gate_v977"))\n    diag = _dict(row.get("paper_final_safety_diagnostics"))\n    trigger_gate = _dict(diag.get("trigger_gate"), row.get("trigger_gate_v738"), row.get("trigger_gate_v790"), gate.get("trigger_gate"))\n    ctx = _dict(row.get("entry_context"))\n    structure = _structure(row)\n    entry_price = _num(\n        trigger_gate.get("entry_price"), trigger_gate.get("current_confirmation_price"),\n        row.get("entry_price"), row.get("open_price"), row.get("buy_price"), row.get("live_price"),\n        row.get("current_price"), row.get("price"), ctx.get("entry_price"), ctx.get("live_price"), ctx.get("current_price"),\n    )\n    actual_rr = _num(row.get("actual_entry_rr_v1034"), row.get("actual_rr"))\n    invalid = _num(structure.get("invalid"))\n    target = _num(structure.get("target"))\n    if actual_rr is None and entry_price and invalid is not None and target is not None and invalid < entry_price < target:\n        risk = entry_price - invalid\n        actual_rr = (target - entry_price) / risk if risk > 0 else None\n    return {\n        "entry_price": entry_price,\n        "actual_rr": actual_rr,\n        "spread_pct": _num(row.get("spread_pct"), row.get("entry_spread_pct"), ctx.get("spread_pct")),\n        "slippage_pct": _num(row.get("paper_slippage_pct"), row.get("confirmed_slippage_pct_v925"), ctx.get("slippage_pct")),\n        "trigger_chase_pct": _num(trigger_gate.get("trigger_gap_pct"), row.get("trigger_gap_pct")),\n        "quote_fresh": _bool(row.get("quote_fresh"), gate.get("execution_fresh_ok_v1039")),\n        "micro_fresh": _bool(row.get("micro_fresh")),\n        "trigger_reached": _bool(trigger_gate.get("trigger_reached"), row.get("trigger_reached")),\n    }\n\n\ndef _candidate_contract(row: Mapping[str, Any]) -> Dict[str, Any]:\n    gate = _dict(row.get("swing_entry_gate_v977"))\n    identity = _identity(row)\n    structure = _structure(row)\n    execution = _entry(row)\n    stage = _text(row.get("s_stage"), row.get("candidate_stage"), row.get("candidate_grade"), row.get("stage")).upper()\n    checks = {\n        "stage_s1": stage == "S1",\n        "strategy_mode": _text(row.get("strategy_mode"), row.get("strategy_mode_v977"), gate.get("strategy_mode")).upper() == "ALT_SWING_V977",\n        "gate_schema": gate.get("schema") == "swing_entry_gate_v977_single_owner",\n        "hard_pass": gate.get("hard_pass") is True,\n        "final_state": _text(gate.get("final_trade_state"), row.get("final_trade_state")) == "S1_PASS",\n        "decision_key": bool(identity.get("decision_key")),\n        "source_fresh": gate.get("source_fresh") is True or row.get("source_fresh") is True,\n        "open_flags": row.get("open_eligible") is not False and row.get("paper_bot_open") is not False and row.get("trade_ready") is not False,\n    }\n    return {\n        "identity": identity,\n        "structure": structure,\n        "execution": execution,\n        "stage": stage,\n        "route": " ".join(_text(row.get(k)) for k in ("strategy", "strategy_key", "strategy_label", "final_entry_label", "route", "source_lane") if _text(row.get(k))),\n        "current_strategy_pass": all(checks.values()),\n        "checks": checks,\n        "raw": dict(row),\n    }\n\n\ndef _source_status(base: Path, now_ts: float) -> Dict[str, Any]:\n    out: Dict[str, Any] = {}\n    for stage, spec in SOURCE_SPECS.items():\n        status_path = base / spec["status"]\n        status_obj = _read_json(status_path, {}) or {}\n        data_items = []\n        for name in spec["data"]:\n            path = base / name\n            data_items.append({\n                "name": name,\n                "exists": path.exists(),\n                "age_sec": _age(path, now_ts),\n                "bytes": path.stat().st_size if path.exists() else 0,\n            })\n        row_count = _num(\n            status_obj.get("row_count"), status_obj.get("rows"), status_obj.get("market_count"),\n            status_obj.get("candidate_count"), status_obj.get("target_count"), status_obj.get("evaluated"),\n            default=None,\n        ) if isinstance(status_obj, dict) else None\n        err = _text(status_obj.get("error"), status_obj.get("last_error"), status_obj.get("err")) if isinstance(status_obj, dict) else ""\n        out[stage] = {\n            "owner": spec["owner"],\n            "status_file": spec["status"],\n            "status_exists": status_path.exists(),\n            "status_age_sec": _age(status_path, now_ts),\n            "version": _text(status_obj.get("version"), status_obj.get("worker_version")) if isinstance(status_obj, dict) else "",\n            "phase": _text(status_obj.get("phase")) if isinstance(status_obj, dict) else "",\n            "row_count": int(row_count) if row_count is not None else None,\n            "error": err or None,\n            "data": data_items,\n        }\n    return out\n\n\ndef _risk_contract(paper_status: Mapping[str, Any], risk_obj: Mapping[str, Any]) -> Dict[str, Any]:\n    contract = _dict(paper_status.get("risk_paper_contract_v1059"))\n    source_contract = _dict(risk_obj.get("loss_reentry_source_contract_v1057"))\n    return {\n        "ready": _bool(contract.get("ready"), paper_status.get("loss_reentry_source_ready_v1057")),\n        "closed_signature_match": _bool(contract.get("closed_signature_match"), paper_status.get("loss_reentry_source_closed_signature_match_v1057")),\n        "latest_loss_selection": _text(contract.get("latest_loss_selection"), source_contract.get("latest_loss_selection")) or None,\n        "consumer_evidence_present": _bool(contract.get("consumer_evidence_present")),\n        "heartbeat_preserve_mode": _bool(contract.get("heartbeat_preserve_mode")),\n        "reason": _text(contract.get("reason")) or None,\n    }\n\n\ndef _extract_open_rows(base: Path) -> List[Dict[str, Any]]:\n    return _rows(_read_json(base / "paper_bot_open.json", {}) or {})\n\n\ndef _extract_candidates(base: Path) -> List[Dict[str, Any]]:\n    return _rows(_read_json(base / "paper_s1_hold_cache.json", {}) or {})\n\n\ndef _closed_key(row: Mapping[str, Any]) -> str:\n    identity = _identity(row)\n    return _text(identity.get("pos_id"), identity.get("decision_key"), row.get("closed_id"), row.get("trade_id"))\n\n\ndef _open_key(row: Mapping[str, Any]) -> str:\n    identity = _identity(row)\n    return _text(identity.get("pos_id"), identity.get("decision_key"), identity.get("candidate_key"), f"ticker:{identity.get(\'ticker\')}")\n\n\ndef _position_contract(row: Mapping[str, Any], now_ts: float) -> Dict[str, Any]:\n    identity = _identity(row)\n    structure = _structure(row)\n    execution = _entry(row)\n    opened_ts = _parse_ts(row.get("opened_ts"), row.get("opened_at"), row.get("entry_ts"), row.get("created_at"), row.get("time"))\n    current = _num(row.get("current_price"), row.get("mark_price"), row.get("latest_price"), row.get("price"))\n    entry_price = _num(execution.get("entry_price"), row.get("entry_price"), row.get("open_price"), row.get("buy_price"))\n    net_pct = _num(row.get("pnl_pct"), row.get("net_pct"), row.get("current_pnl_pct"), row.get("profit_pct"))\n    if net_pct is None and entry_price and current:\n        net_pct = (current / entry_price - 1.0) * 100.0\n    peak_pct = _num(row.get("mfe_pct"), row.get("peak_pct"), row.get("max_profit_pct"), row.get("highest_pnl_pct"))\n    if peak_pct is None and entry_price:\n        highest = _num(row.get("highest_price"), row.get("peak_price"), row.get("max_price"))\n        if highest:\n            peak_pct = (highest / entry_price - 1.0) * 100.0\n    mae_pct = _num(row.get("mae_pct"), row.get("max_adverse_pct"), row.get("lowest_pnl_pct"))\n    contract = _dict(row.get("exit_contract_v1038"), row.get("alt_swing_exit_contract_v1038"))\n    trailing_enabled = contract.get("schema") == "alt_swing_exit_contract_v1038" and contract.get("trailing_exit") is True\n    return {\n        "identity": identity,\n        "strategy_mode": _text(row.get("strategy_mode"), row.get("strategy_mode_v977")) or None,\n        "route": _text(row.get("entry_method"), row.get("actual_entry_method"), row.get("strategy"), row.get("strategy_label")) or None,\n        "opened_ts": opened_ts or None,\n        "age_min": max(0.0, (now_ts - opened_ts) / 60.0) if opened_ts else None,\n        "entry_price": entry_price,\n        "current_price": current,\n        "net_pct": net_pct,\n        "peak_pct": peak_pct,\n        "mae_pct": mae_pct,\n        "giveback_pct": max(0.0, (peak_pct or 0.0) - (net_pct or 0.0)) if peak_pct is not None and net_pct is not None else None,\n        "structure": structure,\n        "execution": execution,\n        "exit_contract": {\n            "schema": contract.get("schema"),\n            "trailing_enabled": trailing_enabled,\n            "trailing_trigger_pct": _num(contract.get("trailing_trigger_pct"), default=2.0 if trailing_enabled else None),\n            "trailing_giveback_pct": _num(contract.get("trailing_giveback_pct"), default=0.8 if trailing_enabled else None),\n        },\n        "raw": dict(row),\n    }\n\n\ndef _exit_decision(position: Mapping[str, Any]) -> Dict[str, Any]:\n    current = _num(position.get("current_price"))\n    net = _num(position.get("net_pct"), default=0.0) or 0.0\n    peak = _num(position.get("peak_pct"), default=0.0) or 0.0\n    age_min = _num(position.get("age_min"), default=0.0) or 0.0\n    structure = _dict(position.get("structure"))\n    target = _num(structure.get("target"))\n    invalid = _num(structure.get("invalid"))\n    giveback = max(0.0, peak - net)\n    result = {\n        "action": "hold",\n        "reason": "structure_hold",\n        "current_price": current,\n        "target": target,\n        "invalid": invalid,\n        "net_pct": round(net, 6),\n        "peak_pct": round(peak, 6),\n        "giveback_pct": round(giveback, 6),\n        "age_min": round(age_min, 4),\n    }\n    # Mirror the actual v1059 function order: target, invalid, emergency, trailing, time exits.\n    if current is not None and target and current >= target:\n        result.update(action="close", reason="structure_target")\n        return result\n    if current is not None and invalid and current <= invalid:\n        result.update(action="close", reason="structure_invalid")\n        return result\n    if not invalid and net <= -2.5:\n        result.update(action="close", reason="swing_emergency_stop")\n        return result\n    contract = _dict(position.get("exit_contract"))\n    if contract.get("trailing_enabled") is True:\n        trigger = _num(contract.get("trailing_trigger_pct"), default=2.0) or 2.0\n        giveback_limit = _num(contract.get("trailing_giveback_pct"), default=0.8) or 0.8\n        if peak >= trigger and giveback >= giveback_limit and net > 0:\n            result.update(action="close", reason="swing_trailing")\n            return result\n    if age_min >= 360.0 and peak < 0.35 and net <= 0.0:\n        result.update(action="close", reason="swing_no_progress")\n        return result\n    if age_min >= 4320.0 and peak < 1.0 and net <= 0.25:\n        result.update(action="close", reason="swing_max_weak_hold")\n        return result\n    return result\n\n\ndef _pnl(row: Mapping[str, Any]) -> Optional[float]:\n    return _num(row.get("net_pnl_pct"), row.get("pnl_pct_after_cost"), row.get("pnl_pct"), row.get("profit_pct"), row.get("return_pct"))\n\n\ndef _performance(rows: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:\n    values = [value for value in (_pnl(row) for row in rows) if value is not None]\n    wins = sum(1 for value in values if value > 0)\n    losses = sum(1 for value in values if value < 0)\n    total = sum(values)\n    reasons: Dict[str, int] = {}\n    for row in rows:\n        reason = _text(row.get("close_reason"), row.get("reason"), row.get("exit_reason")) or "unknown"\n        reasons[reason] = reasons.get(reason, 0) + 1\n    return {\n        "count": len(values),\n        "wins": wins,\n        "losses": losses,\n        "flat": len(values) - wins - losses,\n        "sum_pct": round(total, 6),\n        "avg_pct": round(total / len(values), 6) if values else 0.0,\n        "close_reasons": dict(sorted(reasons.items(), key=lambda item: (-item[1], item[0]))[:12]),\n    }\n\n\ndef _state_default(now_ts: float) -> Dict[str, Any]:\n    return {\n        "schema": SCHEMA,\n        "version": VERSION,\n        "created_ts": now_ts,\n        "updated_ts": now_ts,\n        "cycle_seq": 0,\n        "seen_candidate_keys": [],\n        "shadow_open": {},\n        "shadow_closed": [],\n        "last_live_open_keys": [],\n        "last_live_closed_keys": [],\n        "last_snapshot_id": None,\n        "counters": {\n            "candidate_events": 0,\n            "mirror_open_events": 0,\n            "mirror_close_events": 0,\n            "orphan_close_wait": 0,\n        },\n    }\n\n\ndef _load_state(path: Path, now_ts: float) -> Dict[str, Any]:\n    obj = _read_json(path, {}) or {}\n    if not isinstance(obj, dict) or obj.get("schema") != SCHEMA:\n        return _state_default(now_ts)\n    obj.setdefault("seen_candidate_keys", [])\n    obj.setdefault("shadow_open", {})\n    obj.setdefault("shadow_closed", [])\n    obj.setdefault("last_live_open_keys", [])\n    obj.setdefault("last_live_closed_keys", [])\n    obj.setdefault("counters", {})\n    return obj\n\n\ndef _trim_state(state: Dict[str, Any]) -> None:\n    seen = list(dict.fromkeys(str(x) for x in state.get("seen_candidate_keys", []) if x))\n    state["seen_candidate_keys"] = seen[-MAX_SEEN_KEYS:]\n    closed = [dict(x) for x in state.get("shadow_closed", []) if isinstance(x, dict)]\n    state["shadow_closed"] = closed[-2000:]\n\n\ndef _event(output_dir: Path, state: Dict[str, Any], kind: str, payload: Mapping[str, Any]) -> None:\n    event = {\n        "schema": "coinbot_core_v2_shadow_event_v1064",\n        "ts": time.time(),\n        "cycle_seq": state.get("cycle_seq"),\n        "kind": kind,\n        **dict(payload),\n    }\n    _append_jsonl(output_dir / "core_v2_shadow_events_v1064.jsonl", event)\n\n\ndef run_full_shadow_cycle(base: Path, output_dir: Path, *, now_ts: Optional[float] = None) -> Dict[str, Any]:\n    now_ts = float(now_ts or time.time())\n    base = base.resolve()\n    output_dir = output_dir.resolve()\n    if output_dir == base or base in output_dir.parents:\n        raise ValueError("shadow output directory must be outside live trading_bot directory")\n    output_dir.mkdir(parents=True, exist_ok=True)\n    state_path = output_dir / "core_v2_shadow_state_v1064.json"\n    state = _load_state(state_path, now_ts)\n    state["cycle_seq"] = int(state.get("cycle_seq") or 0) + 1\n    state["updated_ts"] = now_ts\n\n    sources = _source_status(base, now_ts)\n    paper_status = _read_json(base / "paper_bot_status.json", {}) or {}\n    risk_obj = _read_json(base / "clean_risk_filter_cache.json", {}) or {}\n    risk_contract = _risk_contract(paper_status, risk_obj)\n    candidate_rows = _extract_candidates(base)\n    candidate_contracts = [_candidate_contract(row) for row in candidate_rows]\n    seen_set = set(str(x) for x in state.get("seen_candidate_keys", []) if x)\n    new_candidates = 0\n    candidate_key_missing = 0\n    decision_key_missing = 0\n    structure_missing = 0\n    for candidate in candidate_contracts:\n        identity = candidate["identity"]\n        key = _text(identity.get("candidate_key"), identity.get("decision_key"))\n        if not identity.get("candidate_key"):\n            candidate_key_missing += 1\n        if not identity.get("decision_key"):\n            decision_key_missing += 1\n        structure = candidate["structure"]\n        if None in (structure.get("trigger"), structure.get("invalid"), structure.get("target")):\n            structure_missing += 1\n        if key and key not in seen_set:\n            seen_set.add(key)\n            new_candidates += 1\n            state["counters"]["candidate_events"] = int(state["counters"].get("candidate_events") or 0) + 1\n            _event(output_dir, state, "CANDIDATE_SEEN", {\n                "identity": identity,\n                "stage": candidate.get("stage"),\n                "route": candidate.get("route"),\n                "current_strategy_pass": candidate.get("current_strategy_pass"),\n                "structure": structure,\n            })\n    state["seen_candidate_keys"] = list(seen_set)\n\n    live_open_rows = _extract_open_rows(base)\n    live_open_contracts = {_open_key(row): _position_contract(row, now_ts) for row in live_open_rows if _open_key(row)}\n    prior_shadow_open = dict(state.get("shadow_open") or {})\n    shadow_open: Dict[str, Dict[str, Any]] = {}\n    new_open_count = 0\n    for key, position in live_open_contracts.items():\n        if key not in prior_shadow_open:\n            new_open_count += 1\n            state["counters"]["mirror_open_events"] = int(state["counters"].get("mirror_open_events") or 0) + 1\n            _event(output_dir, state, "MIRROR_OPEN", {\n                "open_key": key,\n                "identity": position.get("identity"),\n                "entry_price": position.get("entry_price"),\n                "structure": position.get("structure"),\n            })\n            position["shadow_first_seen_ts"] = now_ts\n            position["shadow_seeded_existing"] = state.get("cycle_seq") == 1\n        else:\n            position["shadow_first_seen_ts"] = prior_shadow_open[key].get("shadow_first_seen_ts")\n            position["shadow_seeded_existing"] = prior_shadow_open[key].get("shadow_seeded_existing")\n        position["shadow_last_seen_ts"] = now_ts\n        position["shadow_exit_decision"] = _exit_decision(position)\n        shadow_open[key] = position\n\n    closed_tail = _read_jsonl_tail(base / "paper_bot_closed.jsonl", limit=2500, max_bytes=48 * 1024 * 1024)\n    closed_by_key = {_closed_key(row): row for row in closed_tail if _closed_key(row)}\n    newly_closed: List[Dict[str, Any]] = []\n    orphan_wait = 0\n    for key, previous in prior_shadow_open.items():\n        if key in live_open_contracts:\n            continue\n        closed_row = closed_by_key.get(key)\n        if closed_row is None:\n            identity = _dict(previous.get("identity"))\n            alt_key = _text(identity.get("decision_key"), identity.get("pos_id"))\n            closed_row = closed_by_key.get(alt_key) if alt_key else None\n        if closed_row is not None:\n            closed_event = {\n                "shadow_close_ts": now_ts,\n                "open_key": key,\n                "identity": previous.get("identity"),\n                "live_closed": dict(closed_row),\n                "shadow_last_exit_decision": previous.get("shadow_exit_decision"),\n                "pnl_pct": _pnl(closed_row),\n                "close_reason": _text(closed_row.get("close_reason"), closed_row.get("reason"), closed_row.get("exit_reason")) or None,\n            }\n            newly_closed.append(closed_event)\n            state["counters"]["mirror_close_events"] = int(state["counters"].get("mirror_close_events") or 0) + 1\n            _event(output_dir, state, "MIRROR_CLOSED", closed_event)\n        else:\n            orphan_wait += 1\n            _event(output_dir, state, "OPEN_DISAPPEARED_CLOSED_NOT_IN_TAIL", {"open_key": key, "identity": previous.get("identity")})\n    state["counters"]["orphan_close_wait"] = int(state["counters"].get("orphan_close_wait") or 0) + orphan_wait\n    state["shadow_open"] = shadow_open\n    state["shadow_closed"] = list(state.get("shadow_closed") or []) + newly_closed\n    state["last_live_open_keys"] = sorted(live_open_contracts)\n    state["last_live_closed_keys"] = sorted(closed_by_key)[-MAX_SEEN_KEYS:]\n\n    close_ready = [position for position in shadow_open.values() if _dict(position.get("shadow_exit_decision")).get("action") == "close"]\n    exit_reason_counts: Dict[str, int] = {}\n    for position in close_ready:\n        reason = _text(_dict(position.get("shadow_exit_decision")).get("reason")) or "unknown"\n        exit_reason_counts[reason] = exit_reason_counts.get(reason, 0) + 1\n\n    recent_closed_for_perf = closed_tail[-300:]\n    perf = _performance(recent_closed_for_perf)\n    shadow_closed_perf_rows = []\n    for event in state.get("shadow_closed", []):\n        if isinstance(event, dict):\n            row = dict(event.get("live_closed") or {})\n            if row:\n                shadow_closed_perf_rows.append(row)\n    shadow_perf = _performance(shadow_closed_perf_rows)\n\n    candidate_decision_keys = {c["identity"].get("decision_key") for c in candidate_contracts if c["identity"].get("decision_key")}\n    open_decision_keys = {_dict(position.get("identity")).get("decision_key") for position in live_open_contracts.values() if _dict(position.get("identity")).get("decision_key")}\n    open_linked_current_candidate = len(candidate_decision_keys & open_decision_keys)\n    live_open_missing_key = sum(1 for position in live_open_contracts.values() if not _dict(position.get("identity")).get("decision_key"))\n\n    stage_checks = {\n        "source_chain_ready": all(not item.get("error") and item.get("status_exists") for stage, item in sources.items() if stage != "performance"),\n        "strategy_contract_complete": candidate_key_missing == 0 and decision_key_missing == 0 and structure_missing == 0,\n        "risk_contract_ready": risk_contract.get("ready") is True and risk_contract.get("closed_signature_match") is True,\n        "open_mirror_exact_count": len(shadow_open) == len(live_open_rows),\n        "open_identity_complete": live_open_missing_key == 0,\n        "exit_engine_evaluated_all": len(shadow_open) == sum(1 for position in shadow_open.values() if isinstance(position.get("shadow_exit_decision"), dict)),\n        "shadow_output_outside_live": output_dir != base and base not in output_dir.parents,\n        "live_write_performed": False,\n    }\n    blockers = [name for name, ok in stage_checks.items() if ok is not True and name != "live_write_performed"]\n    if stage_checks["live_write_performed"] is not False:\n        blockers.append("live_write_detected")\n\n    report = {\n        "schema": SCHEMA,\n        "version": VERSION,\n        "generated_ts": now_ts,\n        "cycle_seq": state["cycle_seq"],\n        "mode": "FULL_LIFECYCLE_MIRROR_SHADOW",\n        "scope_note": "Full lifecycle plumbing is implemented. Strategy formulas are mirrored from canonical Strategy output first; independent formula replacement is verified stage by stage later.",\n        "live_write_performed": False,\n        "auto_buy_changed": False,\n        "sources": sources,\n        "risk_contract": risk_contract,\n        "candidate": {\n            "hold_rows": len(candidate_rows),\n            "strategy_pass": sum(1 for item in candidate_contracts if item.get("current_strategy_pass")),\n            "new_candidate_events": new_candidates,\n            "candidate_key_missing": candidate_key_missing,\n            "decision_key_missing": decision_key_missing,\n            "structure_missing": structure_missing,\n            "contracts": [{k: v for k, v in item.items() if k != "raw"} for item in candidate_contracts[:100]],\n        },\n        "position": {\n            "live_open_count": len(live_open_rows),\n            "shadow_open_count": len(shadow_open),\n            "new_mirror_open": new_open_count,\n            "new_mirror_closed": len(newly_closed),\n            "open_disappeared_without_closed_tail": orphan_wait,\n            "open_decision_key_missing": live_open_missing_key,\n            "current_s1_to_open_decision_match": open_linked_current_candidate,\n        },\n        "exit": {\n            "evaluated": len(shadow_open),\n            "close_ready_while_live_open": len(close_ready),\n            "close_ready_reasons": dict(sorted(exit_reason_counts.items(), key=lambda item: (-item[1], item[0]))),\n            "samples": [\n                {\n                    "ticker": _dict(position.get("identity")).get("ticker"),\n                    "pos_id": _dict(position.get("identity")).get("pos_id"),\n                    "decision": position.get("shadow_exit_decision"),\n                }\n                for position in close_ready[:20]\n            ],\n        },\n        "performance": {\n            "live_recent_closed_tail_300": perf,\n            "shadow_observed_closed_since_start": shadow_perf,\n        },\n        "parity": {\n            "checks": stage_checks,\n            "blockers": blockers,\n            "ready_for_segment_validation": not blockers,\n        },\n        "state": {\n            "created_ts": state.get("created_ts"),\n            "cycle_seq": state.get("cycle_seq"),\n            "counters": state.get("counters"),\n        },\n        "output_files": {\n            "state": str(state_path),\n            "status": str(output_dir / "core_v2_shadow_status_v1064.json"),\n            "open": str(output_dir / "core_v2_shadow_open_v1064.json"),\n            "closed": str(output_dir / "core_v2_shadow_closed_v1064.json"),\n            "events": str(output_dir / "core_v2_shadow_events_v1064.jsonl"),\n            "command_snapshot": str(output_dir / "core_v2_command_snapshot_v1064.json"),\n        },\n    }\n\n    _trim_state(state)\n    _atomic_write_json(state_path, state)\n    _atomic_write_json(output_dir / "core_v2_shadow_status_v1064.json", report)\n    _atomic_write_json(output_dir / "core_v2_shadow_open_v1064.json", shadow_open)\n    _atomic_write_json(output_dir / "core_v2_shadow_closed_v1064.json", state.get("shadow_closed", []))\n    command_snapshot = {\n        "schema": "coinbot_core_v2_command_snapshot_v1064",\n        "generated_ts": now_ts,\n        "cycle_seq": state["cycle_seq"],\n        "health": {\n            "source_ready": stage_checks["source_chain_ready"],\n            "risk_ready": stage_checks["risk_contract_ready"],\n            "live_open": len(live_open_rows),\n            "shadow_open": len(shadow_open),\n            "close_ready": len(close_ready),\n            "blockers": blockers,\n        },\n        "paper": {\n            "candidate_hold": len(candidate_rows),\n            "strategy_pass": report["candidate"]["strategy_pass"],\n            "new_candidate_events": new_candidates,\n            "new_mirror_open": new_open_count,\n            "new_mirror_closed": len(newly_closed),\n        },\n        "performance": report["performance"],\n        "ledger": {\n            "live_write_performed": False,\n            "shadow_state_outside_live": True,\n            "open_identity_missing": live_open_missing_key,\n            "candidate_key_missing": candidate_key_missing,\n            "decision_key_missing": decision_key_missing,\n        },\n    }\n    _atomic_write_json(output_dir / "core_v2_command_snapshot_v1064.json", command_snapshot)\n    return report\n\n\ndef render_report(report: Mapping[str, Any], ticker_filter: str = "") -> str:\n    candidate = _dict(report.get("candidate"))\n    position = _dict(report.get("position"))\n    exit_obj = _dict(report.get("exit"))\n    perf = _dict(report.get("performance"))\n    recent = _dict(perf.get("live_recent_closed_tail_300"))\n    parity = _dict(report.get("parity"))\n    risk = _dict(report.get("risk_contract"))\n    state = _dict(report.get("state"))\n    ready = parity.get("ready_for_segment_validation") is True\n    lines = [\n        f"🧬 CORE V2 전체 생명주기 Shadow · {VERSION}",\n        f"- 판정: {\'READY_SEGMENT_VERIFY\' if ready else \'CHECK\'} / cycle {report.get(\'cycle_seq\')}",\n        "- 모드: 현재 전략판정을 그대로 미러링한 전체 배관 검증",\n        "- 라이브 OPEN/CLOSED/decision 쓰기 0 / 자동매수 변경 0",\n        "",\n        "[전체 흐름]",\n        f"- 시장자료→Strategy S1 {candidate.get(\'hold_rows\', 0)} / 계약통과 {candidate.get(\'strategy_pass\', 0)} / 신규 사건 {candidate.get(\'new_candidate_events\', 0)}",\n        f"- Live OPEN {position.get(\'live_open_count\', 0)} ↔ Shadow OPEN {position.get(\'shadow_open_count\', 0)} / 신규 mirror {position.get(\'new_mirror_open\', 0)}",\n        f"- Shadow 종료 관찰 {position.get(\'new_mirror_closed\', 0)} / CLOSED tail 미확인 {position.get(\'open_disappeared_without_closed_tail\', 0)}",\n        f"- Exit 독립판정 {exit_obj.get(\'evaluated\', 0)} / 현재 close-ready {exit_obj.get(\'close_ready_while_live_open\', 0)}",\n        "",\n        "[계약·키]",\n        f"- Risk {\'READY\' if risk.get(\'ready\') is True else \'CHECK\'} / signature {risk.get(\'closed_signature_match\')} / latest {risk.get(\'latest_loss_selection\') or \'-\'}",\n        f"- candidate key 누락 {candidate.get(\'candidate_key_missing\', 0)} / decision key 누락 {candidate.get(\'decision_key_missing\', 0)} / 구조 누락 {candidate.get(\'structure_missing\', 0)}",\n        f"- OPEN decision key 누락 {position.get(\'open_decision_key_missing\', 0)} / 현재 S1↔OPEN exact 연결 {position.get(\'current_s1_to_open_decision_match\', 0)}",\n        "",\n        "[성과 미러]",\n        f"- 최근 CLOSED tail {recent.get(\'count\', 0)}건 / {recent.get(\'wins\', 0)}승 {recent.get(\'losses\', 0)}패 / 합산 {recent.get(\'sum_pct\', 0):+.2f}% / 평균 {recent.get(\'avg_pct\', 0):+.2f}%",\n        f"- Shadow 시작 이후 누적: candidate {(_dict(state.get(\'counters\'))).get(\'candidate_events\', 0)} / OPEN {(_dict(state.get(\'counters\'))).get(\'mirror_open_events\', 0)} / CLOSED {(_dict(state.get(\'counters\'))).get(\'mirror_close_events\', 0)}",\n    ]\n    reasons = _dict(exit_obj.get("close_ready_reasons"))\n    if reasons:\n        lines += ["", "[현재 Shadow 청산대상]"]\n        for key, value in list(reasons.items())[:8]:\n            lines.append(f"- {key}: {value}")\n    blockers = list(parity.get("blockers") or [])\n    lines += ["", "[구간 검증]"]\n    check_labels = {\n        "source_chain_ready": "재료 source 연결",\n        "strategy_contract_complete": "Strategy 계약·key",\n        "risk_contract_ready": "Risk→Paper 계약",\n        "open_mirror_exact_count": "OPEN mirror 개수",\n        "open_identity_complete": "OPEN exact identity",\n        "exit_engine_evaluated_all": "보유·청산 판정",\n        "shadow_output_outside_live": "Shadow 원장 격리",\n        "live_write_performed": "라이브 write",\n    }\n    for key, value in _dict(parity.get("checks")).items():\n        if key == "live_write_performed":\n            ok = value is False\n        else:\n            ok = value is True\n        lines.append(f"- {\'✅\' if ok else \'⚠️\'} {check_labels.get(key, key)}")\n    if blockers:\n        lines += ["", "[확인 필요]"] + [f"- {item}" for item in blockers]\n    if ticker_filter:\n        ticker = _ticker(ticker_filter)\n        samples = []\n        for contract in candidate.get("contracts", []):\n            if _ticker(_dict(contract.get("identity")).get("ticker")) == ticker:\n                samples.append(contract)\n        for sample in exit_obj.get("samples", []) or []:\n            if _ticker(sample.get("ticker")) == ticker:\n                samples.append({"exit": sample})\n        lines += ["", f"[{ticker} 상세]"]\n        if samples:\n            for sample in samples[:3]:\n                lines.append(json.dumps(sample, ensure_ascii=False, default=_json_default)[:1200])\n        else:\n            lines.append("- 현재 S1 또는 close-ready 표본 없음")\n    lines += [\n        "",\n        "[현재 단계]",\n        "- 전체 Shadow 배관은 완성. 지금은 기존 Strategy 계산을 미러링하며 구간별 동일성 검증 중.",\n        "- 조건 강화·RR/target/invalid/trailing 변경 없음.",\n        f"- 결과: {_dict(report.get(\'output_files\')).get(\'status\') or \'-\'}",\n    ]\n    return "\\n".join(lines)\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--base-dir", required=True)\n    parser.add_argument("--out-dir", required=True)\n    parser.add_argument("--ticker", default="")\n    args = parser.parse_args()\n    report = run_full_shadow_cycle(Path(args.base_dir), Path(args.out_dir))\n    print(render_report(report, args.ticker))\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'
_V1064_CORE_NS = {'__name__': 'coinbot_core_v2_full_shadow_v1064_embedded'}
exec(compile(_V1064_CORE_SOURCE, '<coinbot_core_v2_full_shadow_v1064>', 'exec'), _V1064_CORE_NS)
CORE_V2_FULL_SHADOW_OUTPUT_DIR_V1064 = BOT_DIR.parent / 'coinbot_core_v2_shadow_output'
