def _v1079_median(values: list[float]) -> float:
    vals=sorted(float(x) for x in values if float(x)>=0)
    if not vals: return 0.0
    n=len(vals); mid=n//2
    return vals[mid] if n%2 else (vals[mid-1]+vals[mid])/2.0


