def _ops_attach_stage_contracts_v1107(stages: list) -> None:
    for st in stages:
        if not isinstance(st,dict):
            continue
        step=int(st.get('step') or 0)
        contract=dict(_FLOW_STAGE_CONTRACT_V1107.get(step) or {})
        st['location_id']=f'FLOW-{step:02d}' if step else 'FLOW-UNKNOWN'
        st['contract']=contract
        st['owner_file_candidates']=list(contract.get('fix_files') or [])
        st['upstream_steps']=list(contract.get('upstream_steps') or [])
        st['downstream_steps']=list(contract.get('downstream_steps') or [])


def _ops_component_steps_v1107(component: str) -> list:
    low=str(component or '').strip().lower().replace('-','_')
    if low in _FLOW_COMPONENT_STAGE_V1107:
        return list(_FLOW_COMPONENT_STAGE_V1107[low])
    for key,steps in _FLOW_COMPONENT_STAGE_V1107.items():
        if key and key in low:
            return list(steps)
    return []


def _ops_problem_location_v1107(problem_row: dict, stages: list, edges: list, ledger_rows: list) -> dict:
    code=str(problem_row.get('code') or 'UNKNOWN')
    where=str(problem_row.get('where') or '정보없음')
    actual=problem_row.get('actual')
    root=problem_row.get('root_cause') if isinstance(problem_row.get('root_cause'),dict) else {}
    steps=[]; edge_pair=None; domain='stage'; component=''; artifact_names=[]; ledger_row=None

    m=re.match(r'^(\d{1,2})(?::|\b)',where)
    if m:
        steps=[int(m.group(1))]
    if '→' in where:
        left,right=[x.strip() for x in where.split('→',1)]
        edge_pair=(left,right); steps=list(_FLOW_EDGE_STAGE_V1107.get(edge_pair) or [])
        domain='edge'; component=f'{left}→{right}'
    elif where.startswith('ledger:'):
        domain='ledger'; artifact_names=[where.split(':',1)[1]]
    elif where in ('ledger','lineage','runtime','resource','performance','paper OPEN'):
        domain=where.replace(' ','_').lower()
    else:
        component=where
        if not steps:
            steps=_ops_component_steps_v1107(where)

    if isinstance(actual,dict):
        for key in ('artifact','name','file'):
            val=actual.get(key)
            if isinstance(val,str) and val:
                artifact_names.append(val)
        if not component:
            component=str(actual.get('component') or actual.get('owner') or '')
    if code in ('WORKER_DOWN','RUNTIME_CHECK','RUNTIME_SOURCE_MISMATCH','WORKER_MULTI_INSTANCE'):
        domain='runtime'; component=where
    if code in ('EXACT_LINK',): steps=[17]; domain='performance'; component='performance'
    if code in ('STRATEGY_CYCLE_SLOW',): steps=[8]; domain='stage'; component='strategy'
    if code in ('EVENT_DRIVEN_EDGE_CONTRACT_CHECK','CANDIDATE_SUMMARY_SCOPE_MISMATCH','STRATEGY_CACHE_SHADOW_VIOLATION') and edge_pair: domain='edge'
    if code in ('DISK_LOW','DISK_PROJECTED_LOW','FAST_FILE_GROWTH','FULL_REWRITE_PRESSURE'): domain='resource'; component='disk'; steps=[20]
    if code in ('MEMORY_LOW',): domain='resource'; component='memory'; steps=[20]
    if code.startswith('RSS_') or code=='CPU_SATURATION':
        domain='resource'; component=where; steps=_ops_component_steps_v1107(where) or [20]
    if code in ('FLOW_EDGE_INFORMATION_MISSING','DATA_SOURCE_INFORMATION_MISSING','DATA_STALE') and edge_pair:
        domain='edge'
    if code in ('LEDGER_OWNER_INFORMATION_MISSING','MULTI_WRITER','WRITER_OWNER_MISMATCH','FAST_FILE_GROWTH','FULL_REWRITE_PRESSURE'):
        domain='ledger'
        if where.startswith('ledger:') and not artifact_names:
            artifact_names=[where.split(':',1)[1]]

    for row in ledger_rows:
        if not isinstance(row,dict): continue
        if artifact_names and str(row.get('name') or '') in artifact_names:
            ledger_row=row; break
    if ledger_row:
        expected_owner=str(ledger_row.get('expected_owner') or '')
        owner_steps=_ops_component_steps_v1107(expected_owner)
        if owner_steps: steps=owner_steps
        component=expected_owner or component or 'ledger'

    if not steps and component:
        steps=_ops_component_steps_v1107(component)
    if not steps:
        if domain=='runtime': steps=[20]
        elif domain=='performance': steps=[17]
        elif domain=='paper_open': steps=[14,15]
        elif domain=='lineage': steps=[20]
        elif domain=='ledger': steps=[20]
        elif domain=='resource': steps=[20]
        else: steps=[20]
    # preserve order, remove duplicates, stay within 1..20
    dedup=[]
    for x in steps:
        try: x=int(x)
        except Exception: continue
        if 1<=x<=20 and x not in dedup: dedup.append(x)
    steps=dedup or [20]
    contracts=[_FLOW_STAGE_CONTRACT_V1107.get(x) or {} for x in steps]
    primary=contracts[-1] if domain=='edge' and contracts else (contracts[0] if contracts else {})
    if ledger_row and not ledger_row.get('expected_owner'):
        owner=root.get('owner') or '정보없음'
        observed_writers=ledger_row.get('observed_writers') or []
        observed_readers=ledger_row.get('observed_readers') or []
        writer=root.get('writer') or (str(observed_writers) if observed_writers else 'CHECK_CALLER_WRITER_SOURCE_REQUIRED')
        reader=root.get('reader') or (str(observed_readers) if observed_readers else 'CHECK_READER_SOURCE_REQUIRED')
        caller=root.get('caller') or 'CHECK_CALLER_SOURCE_REQUIRED'
    else:
        owner=root.get('owner') or (ledger_row or {}).get('expected_owner') or primary.get('owner') or component or '정보없음'
        writer=root.get('writer') or primary.get('writer') or 'CHECK_SOURCE_REQUIRED'
        reader=root.get('reader') or primary.get('reader') or 'CHECK_SOURCE_REQUIRED'
        caller=root.get('caller') or primary.get('caller') or 'CHECK_SOURCE_REQUIRED'
    artifacts=[]
    for name in artifact_names + list(primary.get('artifacts') or []):
        if name and name not in artifacts: artifacts.append(name)
    fix_files=[]
    primary_fix_files=[] if (ledger_row and not ledger_row.get('expected_owner')) else list(primary.get('fix_files') or [])
    for name in list(root.get('fix_files') or []) + primary_fix_files:
        if name and name not in fix_files: fix_files.append(name)
    if ledger_row and not ledger_row.get('expected_owner'):
        fix_files=['CALLER_WRITER_SOURCE_AUDIT_REQUIRED']
    stage_names=[str((_FLOW_STAGE_CONTRACT_V1107.get(x) or {}).get('name') or f'{x}단계') for x in steps]
    edge_text=f'{edge_pair[0]}→{edge_pair[1]}' if edge_pair else None
    if edge_text:
        location_id=f'EDGE:{edge_text}'
    elif domain=='ledger':
        location_id=f"LEDGER:{artifact_names[0] if artifact_names else component or 'UNKNOWN'}"
    elif domain=='runtime':
        location_id=f'RUNTIME:{component or where}'
    elif domain=='resource':
        location_id=f'RESOURCE:{component or where}'
    elif domain=='lineage':
        location_id='LINEAGE:UNKNOWN'
    else:
        location_id='+'.join(f'FLOW-{x:02d}' for x in steps)
    evidence={'where':where,'actual':actual,'artifacts':artifacts}
    if ledger_row:
        evidence['ledger']={k:ledger_row.get(k) for k in ('name','size_bytes','growth_bytes_sec','writer_status','observed_writers','observed_readers','expected_owner')}
    return {
        'location_id':location_id,'fault_domain':domain,'fault_steps':steps,'fault_stage_names':stage_names,
        'edge':edge_text,'component':component or primary.get('component') or '정보없음','detected_at_step':20,
        'owner':owner,'caller':caller,'writer':writer,'reader':reader,'artifacts':artifacts,
        'input_contract':('unknown/observed writer output' if ledger_row and not ledger_row.get('expected_owner') else primary.get('input_contract') or '정보없음'),
        'output_contract':(f"artifact {artifact_names[0]} ownership and reader chain" if ledger_row and not ledger_row.get('expected_owner') and artifact_names else primary.get('output_contract') or '정보없음'),
        'upstream_steps':list(primary.get('upstream_steps') or []),'downstream_steps':list(primary.get('downstream_steps') or []),
        'fix_files':fix_files,'verification':f"/flow_map에서 {location_id} 상태·입출력·artifact age·runtime을 재확인",
        'location_certainty':'PROVEN' if primary or edge_pair or ledger_row else 'CHECK','evidence':evidence,
    }


