def _ops_expected_owner_v1104(name: str) -> tuple[Optional[str], str]:
    low=str(name or '').lower()
    exact=_OPS_ARTIFACT_OWNER_EXACT_V1104.get(low)
    if exact:
        return exact,'EXPLICIT_CANONICAL_MAP_V1104'
    for prefix,owner in _OPS_ARTIFACT_OWNER_PREFIX_V1104:
        if low.startswith(prefix) or (prefix in ('structure_lab_','good_s2_') and prefix in low):
            return owner,'CANONICAL_NAMESPACE_MAP_V1104'
    # Preserve previously validated broad namespace rules so the accuracy patch
    # does not turn already-owned artifacts back into UNKNOWN.
    if low.startswith('paper_') or 'paper_bot_' in low or 'canonical_performance' in low:
        return 'paper','LEGACY_NAMESPACE_MAP_VALIDATED_V1104'
    if 'strategy' in low or 'candidate' in low:
        return 'strategy','LEGACY_NAMESPACE_MAP_VALIDATED_V1104'
    if 'review' in low or 'structure_lab' in low or 'good_s2' in low:
        return 'review','LEGACY_NAMESPACE_MAP_VALIDATED_V1104'
    if 'scanner' in low:
        return 'scanner','LEGACY_NAMESPACE_MAP_VALIDATED_V1104'
    if 'guard' in low or 'issue_ledger' in low or 'change_verify' in low:
        return 'guard','LEGACY_NAMESPACE_MAP_VALIDATED_V1104'
    return None,'INFORMATION_UNAVAILABLE'


