def _ops_artifact_kind_v1108(name: str) -> str:
    low=str(name or '').lower()
    if low.endswith('.zip'): return 'DEPLOY_PACKAGE'
    if low.endswith(('.log','.err','.out')) or 'runtime_error_log' in low or 'service.err' in low: return 'SERVICE_LOG'
    if low.endswith('.txt') and ('report' in low or 'verify' in low or 'error' in low): return 'REPORT_TEXT'
    if low in _OPS_RETIRED_ARTIFACTS_V1108: return 'LEGACY_STATE'
    if any(x in low for x in ('open.json','closed.jsonl','decision','change_verify_ledger','issue_ledger','trade_log')):
        return 'TRADING_LEDGER'
    if low.endswith(('.json','.jsonl')): return 'STATE_OR_LEDGER'
    return 'OTHER_ARTIFACT'

def _ops_retention_contract_v1108(name: str, artifact_kind: str, file_class: str, owner, growth_bps: float, writer_rows: list, mtime_age: float) -> dict:
    active=bool(float(growth_bps or 0)>0 or writer_rows)
    # Explicitly retired zero-growth state remains preserved but is not an active ledger error.
    if artifact_kind=='LEGACY_STATE' and not active:
        return {'grade':'LEGACY_STOPPED','cleanup':'PRESERVE_NO_AUTODELETE','action':'OBSERVE_ONLY'}
    if file_class=='PROTECTED_CORE' or artifact_kind=='TRADING_LEDGER':
        return {'grade':'PROTECTED_APPEND_ONLY','cleanup':'NEVER_DELETE_OR_REWRITE','action':'OBSERVE_ONLY'}
    if artifact_kind=='DEPLOY_PACKAGE':
        return {'grade':'DEPLOY_PACKAGE','cleanup':'PRUNE_KEEP_LATEST_BY_BUNDLE_POLICY','action':'ROTATE_BY_POLICY'}
    if artifact_kind=='SERVICE_LOG':
        return {'grade':'ROTATABLE_SERVICE_LOG','cleanup':'ROTATE_WITH_AUDIT_WINDOW','action':'ROTATE_BY_POLICY'}
    if artifact_kind=='REPORT_TEXT':
        return {'grade':'GENERATED_REPORT','cleanup':'PRUNE_AFTER_SUCCESS_PROOF','action':'ROTATE_BY_POLICY'}
    if owner and active:
        return {'grade':'ACTIVE_RUNTIME_ARTIFACT','cleanup':'OWNER_POLICY_ONLY','action':'OBSERVE_ONLY'}
    if owner and not active:
        return {'grade':'KNOWN_INACTIVE_ARTIFACT','cleanup':'PRESERVE_UNTIL_OWNER_REVIEW','action':'OBSERVE_ONLY'}
    if not owner and active:
        return {'grade':'ORPHAN_CHECK','cleanup':'BLOCK_DELETE_UNTIL_OWNER_PROVEN','action':'CALLER_WRITER_AUDIT'}
    return {'grade':'LEGACY_OR_UNCLASSIFIED_STOPPED','cleanup':'PRESERVE_NO_AUTODELETE','action':'OBSERVE_ONLY'}

def _ops_event_driven_freshness_v1108(name: str, artifact_row: dict, nowv: float) -> dict:
    contract=_OPS_EVENT_DRIVEN_CACHE_CONTRACTS_V1108.get(str(name or ''))
    if not contract:
        return {'applicable':False,'state':'NOT_EVENT_DRIVEN'}
    out=BOT_DIR/str(name)
    try: out_mtime=out.stat().st_mtime
    except Exception: out_mtime=0.0
    source_rows=[]
    source_changed=False
    for src in contract.get('sources') or []:
        p=BOT_DIR/src
        try:
            mt=p.stat().st_mtime; age=max(0.0,nowv-mt)
            if mt>out_mtime+0.001: source_changed=True
            source_rows.append({'name':src,'mtime':mt,'age_sec':round(age,2),'newer_than_output':mt>out_mtime+0.001})
        except Exception:
            source_rows.append({'name':src,'missing':True})
    status=_ops_read_json(BOT_DIR/str(contract.get('status') or ''))
    status_ts=_ops_float_v1102(status.get('updated_ts')) or _ops_float_v1102(status.get('ts')) or 0.0
    heartbeat_fresh=bool(status_ts and nowv-status_ts<=180)
    if not source_changed and heartbeat_fresh:
        state='PROVEN_EVENT_DRIVEN_IDLE'
    elif source_changed and heartbeat_fresh:
        state='CHECK_OUTPUT_NOT_REFRESHED_AFTER_SOURCE_CHANGE'
    elif not heartbeat_fresh:
        state='CHECK_OWNER_HEARTBEAT_STALE'
    else:
        state='CHECK_EVENT_DRIVEN_CONTRACT'
    return {'applicable':True,'state':state,'owner':contract.get('owner'),'writer':contract.get('writer'),
            'heartbeat_fresh':heartbeat_fresh,'status_ts':status_ts,'output_mtime':out_mtime,'sources':source_rows,
            'source_changed_after_output':source_changed}


def _ops_nested_value_v1104(row: dict, *paths):
    for path in paths:
        keys=path.split('.') if isinstance(path,str) else list(path)
        cur=row
        ok=True
        for key in keys:
            if not isinstance(cur,dict) or key not in cur:
                ok=False; break
            cur=cur.get(key)
        if ok and cur not in (None,'',[],{}):
            return cur
    return None


