def _ops_read_text(path: Path, limit: int = 32 * 1024 * 1024) -> str:
    try:
        if not path.exists() or not path.is_file(): return ''
        with path.open('rb') as handle:
            return handle.read(limit).decode('utf-8', errors='ignore')
    except Exception:
        return ''


def _ops_read_json(path: Path) -> dict:
    obj = read_json(path)
    return obj if isinstance(obj, dict) else {}


def _ops_atomic_json(path: Path, obj: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + f'.tmp.{os.getpid()}.{time.time_ns()}')
    with tmp.open('w', encoding='utf-8') as handle:
        json.dump(obj, handle, ensure_ascii=False, separators=(',', ':'), default=str)
        handle.flush(); os.fsync(handle.fileno())
    os.replace(tmp, path)


def _ops_sha256(path: Path) -> str:
    try:
        h=hashlib.sha256()
        with path.open('rb') as handle:
            while True:
                chunk=handle.read(1024*1024)
                if not chunk: break
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return ''


def _ops_tail_jsonl(path: Path, limit: int = 12, max_bytes: int = 2*1024*1024) -> list:
    if limit <= 0: return []
    try:
        size=path.stat().st_size
        with path.open('rb') as handle:
            handle.seek(max(0,size-max_bytes)); data=handle.read()
        rows=[]
        for raw in data.splitlines()[-limit*3:]:
            try:
                obj=json.loads(raw.decode('utf-8',errors='ignore'))
                if isinstance(obj,dict): rows.append(obj)
            except Exception: continue
        return rows[-limit:]
    except Exception:
        return []


def _ops_percentile(values: list, pct: float):
    nums=sorted(float(x) for x in values if isinstance(x,(int,float)))
    if not nums: return None
    idx=max(0,min(len(nums)-1,int(round((len(nums)-1)*pct))))
    return round(nums[idx],3)


def _ops_systemctl(service: str) -> dict:
    if not service: return {'active_state':'unknown','main_pid':0,'n_restarts':None,'exec_start':''}
    props='ActiveState,SubState,MainPID,NRestarts,ExecStart,FragmentPath,DropInPaths,EnvironmentFiles,ActiveEnterTimestamp'
    rc,out = run(['systemctl','show',service,f'--property={props}','--no-pager'], timeout=8)
    vals={}
    if rc == 0:
        for line in str(out).splitlines():
            if '=' in line:
                k,v=line.split('=',1); vals[k]=v
    return {
        'active_state':vals.get('ActiveState') or ('unknown' if rc else '-'),
        'sub_state':vals.get('SubState') or '-',
        'main_pid':int(vals.get('MainPID') or 0),
        'n_restarts':int(vals.get('NRestarts') or 0) if str(vals.get('NRestarts') or '').isdigit() else None,
        'exec_start':vals.get('ExecStart') or '', 'fragment_path':vals.get('FragmentPath') or '',
        'drop_in_paths':vals.get('DropInPaths') or '', 'environment_files':vals.get('EnvironmentFiles') or '',
        'active_enter_timestamp':vals.get('ActiveEnterTimestamp') or '', 'rc':rc,
    }


def _ops_proc(pid: int, previous: dict, interval: float, total_delta: int, cpu_count: int) -> dict:
    row={'pid':int(pid or 0),'alive':False,'cpu_pct':None,'rss_mb':None,'rss_hwm_mb':None,'vm_peak_mb':None,
         'read_mb_s':None,'write_mb_s':None,'fd_count':None,'thread_count':None,'cmdline':'','open_files':[],
         'deleted_open_files':[],'start_ts':None,'start_text':None}
    if pid <= 0: return row
    root=Path('/proc')/str(pid)
    try:
        stat=(root/'stat').read_text().split(); status=_ops_read_text(root/'status', 256*1024); io_txt=_ops_read_text(root/'io', 64*1024)
        utime=int(stat[13]); stime=int(stat[14]); ticks=utime+stime
        start_ts=None
        try:
            clk=max(1,int(os.sysconf(os.sysconf_names.get('SC_CLK_TCK','SC_CLK_TCK'))))
            btime=0
            for _line in Path('/proc/stat').read_text().splitlines():
                if _line.startswith('btime '):
                    btime=int(_line.split()[1]); break
            if btime>0: start_ts=float(btime)+(float(stat[21])/float(clk))
        except Exception:
            start_ts=None
        status_vals={}
        for line in status.splitlines():
            if ':' in line:
                k,v=line.split(':',1); status_vals[k.strip()]=v.strip()
        def kb_field(key):
            try: return round(int(str(status_vals.get(key) or '0').split()[0])/1024.0,2)
            except Exception: return None
        io_vals={}
        for line in io_txt.splitlines():
            if ':' in line:
                k,v=line.split(':',1)
                try: io_vals[k.strip()]=int(v.strip())
                except Exception: pass
        cmd=(root/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='ignore').strip()
        prev=previous if isinstance(previous,dict) else {}
        dproc=max(0,ticks-int(prev.get('ticks') or ticks))
        cpu_pct=(dproc/max(1,total_delta))*100.0*max(1,cpu_count) if total_delta>0 else None
        read_b=int(io_vals.get('read_bytes') or 0); write_b=int(io_vals.get('write_bytes') or 0)
        read_rate=max(0,read_b-int(prev.get('read_bytes') or read_b))/max(0.001,interval)/1024/1024
        write_rate=max(0,write_b-int(prev.get('write_bytes') or write_b))/max(0.001,interval)/1024/1024
        open_files=[]; deleted=[]; fdroot=root/'fd'
        try:
            for fd in list(fdroot.iterdir())[:1024]:
                try:
                    target=os.readlink(fd)
                    if not target.startswith('/'): continue
                    deleted_flag=target.endswith(' (deleted)')
                    clean_target=target[:-10] if deleted_flag else target
                    flags_txt=_ops_read_text(root/'fdinfo'/fd.name, 4096); flags_val=0
                    for item in flags_txt.splitlines():
                        if item.startswith('flags:'):
                            try: flags_val=int(item.split(':',1)[1].strip(),8)
                            except Exception: flags_val=0
                            break
                    mode=flags_val & 3
                    ev={'path':clean_target,'mode':'write' if mode in (1,2) else 'read','fd':fd.name,'deleted':deleted_flag}
                    try:
                        fst=os.stat(fd)
                        ev.update({'inode':int(fst.st_ino),'device':int(fst.st_dev),'size_bytes':int(fst.st_size),
                                   'allocated_bytes':int(getattr(fst,'st_blocks',0))*512})
                    except Exception:
                        pass
                    try:
                        for item in flags_txt.splitlines():
                            if item.startswith('pos:'):
                                ev['position']=int(item.split(':',1)[1].strip()); break
                    except Exception:
                        pass
                    open_files.append(ev)
                    if deleted_flag: deleted.append(ev)
                except Exception: continue
        except Exception: pass
        row.update({'alive':True,'ticks':ticks,'read_bytes':read_b,'write_bytes':write_b,
                    'cpu_pct':round(cpu_pct,2) if cpu_pct is not None else None,
                    'rss_mb':kb_field('VmRSS'),'rss_hwm_mb':kb_field('VmHWM'),'vm_peak_mb':kb_field('VmPeak'),
                    'read_mb_s':round(read_rate,3),'write_mb_s':round(write_rate,3),
                    'fd_count':len(list(fdroot.iterdir())) if fdroot.exists() else None,
                    'thread_count':int(status_vals.get('Threads') or 0) if str(status_vals.get('Threads') or '').isdigit() else None,
                    'cmdline':cmd,'open_files':open_files,'deleted_open_files':deleted,
                    'start_ts':start_ts,'start_text':datetime.fromtimestamp(start_ts).strftime('%Y-%m-%d %H:%M:%S') if start_ts else None})
    except Exception as exc:
        row['error']=f'{type(exc).__name__}: {exc}'
    return row


def _ops_cpu_total() -> int:
    try:
        line=Path('/proc/stat').read_text().splitlines()[0]
        return sum(int(x) for x in line.split()[1:] if x.isdigit())
    except Exception:
        return 0


def _ops_server_memory() -> dict:
    vals={}
    try:
        for line in Path('/proc/meminfo').read_text().splitlines():
            if ':' in line:
                k,v=line.split(':',1)
                try: vals[k]=int(v.strip().split()[0])*1024
                except Exception: pass
    except Exception: pass
    try: load=[float(x) for x in Path('/proc/loadavg').read_text().split()[:3]]
    except Exception: load=[]
    return {'total_bytes':vals.get('MemTotal'),'available_bytes':vals.get('MemAvailable'),
            'swap_total_bytes':vals.get('SwapTotal'),'swap_free_bytes':vals.get('SwapFree'),'load':load}


def _ops_final_assignment(path: Path, names: tuple[str, ...]) -> dict:
    text=_ops_read_text(path)
    out={name:None for name in names}
    if not text: return out
    try:
        tree=ast.parse(text)
        for node in tree.body:
            if not isinstance(node,(ast.Assign,ast.AnnAssign)): continue
            targets=node.targets if isinstance(node,ast.Assign) else [node.target]
            value=node.value
            if not isinstance(value,ast.Constant) or not isinstance(value.value,(str,int,float,bool)): continue
            for target in targets:
                if isinstance(target,ast.Name) and target.id in out: out[target.id]=value.value
    except Exception:
        for name in names:
            vals=re.findall(rf'^\s*{re.escape(name)}\s*=\s*[\'\"]([^\'\"]+)',text,flags=re.M)
            if vals: out[name]=vals[-1]
    return out


def _ops_target_from_evidence(name: str, spec: dict, active: Path, active_hash: str) -> tuple[Path|None,str,list[str],dict]:
    evidence=[]; marker_targets=[]
    for marker_name in spec.get('marker') or []:
        marker=BOT_DIR/str(marker_name)
        value=read_file(marker).strip() if marker.exists() else ''
        if value:
            candidate=BOT_DIR/Path(value).name
            marker_targets.append({'marker':marker.name,'target':candidate.name,'exists':candidate.exists(),
                                   'hash_match':bool(candidate.exists() and active_hash and _ops_sha256(candidate)==active_hash)})
            evidence.append(f"marker:{marker.name}={candidate.name}:hash={marker_targets[-1]['hash_match']}")
    matches=[]; prefix=str(spec.get('prefix') or '')
    if active_hash and prefix:
        for path in BOT_DIR.glob(prefix+'*.py'):
            if path.name == active.name: continue
            if _ops_sha256(path) == active_hash: matches.append(path)
    unique=[]; seen=set()
    for path in matches:
        rp=str(path.resolve())
        if rp not in seen: unique.append(path); seen.add(rp)
    matching_marker=next((BOT_DIR/x['target'] for x in marker_targets if x.get('exists') and x.get('hash_match')),None)
    meta={'marker_targets':marker_targets,'hash_matches':[x.name for x in unique],
          'marker_stale':bool(marker_targets and not matching_marker),'hash_match_count':len(unique)}
    if matching_marker is not None:
        evidence.append(f'marker_hash_exact:{matching_marker.name}')
        return matching_marker,'marker_hash_exact',evidence,meta
    if len(unique)==1:
        evidence.append(f'active_hash_exact:{unique[0].name}')
        return unique[0],'active_hash_exact',evidence,meta
    if len(unique)>1:
        evidence.append('hash_ambiguous:'+','.join(x.name for x in unique[:8]))
        return None,'ambiguous_hash',evidence,meta
    evidence.append('target_unresolved')
    return None,'unknown',evidence,meta


def _ops_call_name(node) -> str:
    if isinstance(node,ast.Name): return node.id
    if isinstance(node,ast.Attribute):
        base=_ops_call_name(node.value)
        return f'{base}.{node.attr}' if base else node.attr
    return ''


def _ops_static_code(path: Path) -> dict:
    out={'path':str(path),'exists':path.exists(),'line_count':0,'parse_ok':False,'top_duplicate_defs':[],
         'versioned_function_count':0,'simple_wrapper_count':0,'wrapper_candidates':[],
         'fallback_ref_count':0,'fallback_references':[],'legacy_ref_count':0,'broad_except_pass_count':0,
         'broad_except_pass':[],'alias_assignment_count':0,'aliases':[],'dead_candidate_count':0,
         'dead_candidates':[],'command_duplicate_keys':[],'commands':[],'function_count':0}
    text=_ops_read_text(path)
    if not text: return out
    lines=text.splitlines(); out['line_count']=len(lines)
    try:
        tree=ast.parse(text); out['parse_ok']=True
    except Exception as exc:
        out['parse_error']=f'{type(exc).__name__}: {exc}'; return out
    funcs=[]; top_names=[]; command_rows=[]
    for node in tree.body:
        if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)):
            top_names.append(node.name)
            calls=[]
            for child in ast.walk(node):
                if isinstance(child,ast.Call):
                    name=_ops_call_name(child.func)
                    if name: calls.append(name)
            wrapper_target=None
            if len(node.body)==1:
                stmt=node.body[0]; call=None
                if isinstance(stmt,ast.Return) and isinstance(stmt.value,ast.Call): call=stmt.value
                elif isinstance(stmt,ast.Expr) and isinstance(stmt.value,ast.Call): call=stmt.value
                if call is not None: wrapper_target=_ops_call_name(call.func) or None
            funcs.append({'name':node.name,'line':getattr(node,'lineno',None),'end_line':getattr(node,'end_lineno',None),
                          'calls':sorted(set(calls))[:80],'wrapper_target':wrapper_target,
                          'versioned':bool(re.search(r'(?:^|_)v\d+',node.name,re.I))})
        elif isinstance(node,ast.ClassDef): top_names.append(node.name)
        elif isinstance(node,ast.Assign) and isinstance(node.value,ast.Name):
            for target in node.targets:
                if isinstance(target,ast.Name): out['aliases'].append({'target':target.id,'source':node.value.id,'line':getattr(node,'lineno',None)})
    out['function_count']=len(funcs); out['alias_assignment_count']=len(out['aliases'])
    inbound={name:[] for name in top_names}
    for fn in funcs:
        for call in fn['calls']:
            leaf=call.split('.')[-1]
            if leaf in inbound and fn['name'] not in inbound[leaf]: inbound[leaf].append(fn['name'])
    # command contracts from literal BotCommand/CommandHandler and registry update dictionaries
    for node in ast.walk(tree):
        if isinstance(node,ast.Call):
            cname=_ops_call_name(node.func)
            if cname.endswith('BotCommand') and node.args and isinstance(node.args[0],ast.Constant) and isinstance(node.args[0].value,str):
                command_rows.append({'command':node.args[0].value,'evidence':'telegram_menu','handler':None,'line':getattr(node,'lineno',None)})
            elif cname.endswith('CommandHandler') and node.args and isinstance(node.args[0],ast.Constant) and isinstance(node.args[0].value,str):
                handler=_ops_call_name(node.args[1]) if len(node.args)>1 else None
                command_rows.append({'command':node.args[0].value,'evidence':'telegram_handler','handler':handler,'line':getattr(node,'lineno',None)})
            elif cname in ('table.update','COMMANDS.update') and node.args and isinstance(node.args[0],ast.Dict):
                for key,val in zip(node.args[0].keys,node.args[0].values):
                    if isinstance(key,ast.Constant) and isinstance(key.value,str):
                        command_rows.append({'command':key.value,'evidence':'registry_update','handler':_ops_call_name(val),'line':getattr(node,'lineno',None)})
        if isinstance(node,ast.ExceptHandler) and (node.type is None or (isinstance(node.type,ast.Name) and node.type.id in ('Exception','BaseException'))):
            if len(node.body)==1 and isinstance(node.body[0],ast.Pass):
                out['broad_except_pass'].append({'line':getattr(node,'lineno',None)})
    required_map={'flow_map','ops_map','code_map','system_map','resource_map','ledger_map','ops_diff','ops_history','ops_anomaly','ops_focus'}
    latest_by_key={}
    for row in command_rows:
        key=(str(row.get('command') or '').strip().lstrip('/').lower(),str(row.get('evidence') or ''))
        if key[0]: latest_by_key[key]=row
    latest_rows=sorted(latest_by_key.values(),key=lambda x:int(x.get('line') or 0))
    map_rows=[x for x in command_rows if str(x.get('command') or '').strip().lstrip('/').lower() in required_map]
    merged={(str(x.get('command')),str(x.get('evidence')),int(x.get('line') or 0)):x for x in latest_rows+map_rows}
    out['commands']=sorted(merged.values(),key=lambda x:int(x.get('line') or 0))[-1200:]
    ccounts={}
    for row in command_rows:
        key=(row.get('command'),row.get('evidence')); ccounts[key]=ccounts.get(key,0)+1
    out['command_duplicate_keys']=sorted({str(k[0]) for k,c in ccounts.items() if c>1})
    counts={n:top_names.count(n) for n in set(top_names)}; out['top_duplicate_defs']=sorted(n for n,c in counts.items() if c>1)
    wrappers=[]; dead=[]; versioned=0
    command_handlers={str(x.get('handler') or '').split('.')[-1] for x in command_rows if x.get('handler')}
    for fn in funcs:
        if fn['versioned']: versioned+=1
        if fn['wrapper_target']:
            wrappers.append({'name':fn['name'],'target':fn['wrapper_target'],'line':fn['line'],'callers':inbound.get(fn['name'],[])[:8]})
        if not inbound.get(fn['name']) and fn['name'] not in command_handlers and fn['name']!='main' and not fn['name'].startswith('__'):
            dead.append({'name':fn['name'],'line':fn['line'],'versioned':fn['versioned']})
    out['versioned_function_count']=versioned; out['wrapper_candidates']=wrappers[:80]; out['simple_wrapper_count']=len(wrappers)
    out['dead_candidates']=dead[:80]; out['dead_candidate_count']=len(dead)
    out['broad_except_pass_count']=len(out['broad_except_pass'])
    for idx,line in enumerate(lines,1):
        if re.search(r'fallback|legacy',line,re.I):
            out['fallback_references'].append({'line':idx,'text':line.strip()[:180]})
    out['fallback_ref_count']=sum(1 for x in out['fallback_references'] if 'fallback' in str(x.get('text')).lower())
    out['legacy_ref_count']=sum(1 for x in out['fallback_references'] if 'legacy' in str(x.get('text')).lower())
    out['fallback_references']=out['fallback_references'][:80]
    return out


def _ops_extract_phases(status: dict) -> dict:
    phase_map={}; active={}
    def add(name,wall=None,cpu=None,rows=None,source='status'):
        if name is None: return
        key=str(name).strip()
        if not key: return
        try: wall=float(wall) if wall is not None else None
        except Exception: wall=None
        try: cpu=float(cpu) if cpu is not None else None
        except Exception: cpu=None
        existing=phase_map.get(key)
        if existing is None:
            phase_map[key]={'phase':key[:100],'wall_sec':wall,'cpu_sec':cpu,'rows':rows,'sources':[source]}
        else:
            if wall is not None and (existing.get('wall_sec') is None or wall>existing.get('wall_sec')): existing['wall_sec']=wall
            if cpu is not None and (existing.get('cpu_sec') is None or cpu>existing.get('cpu_sec')): existing['cpu_sec']=cpu
            if existing.get('rows') is None and rows is not None: existing['rows']=rows
            if source not in existing['sources']: existing['sources'].append(source)
    def walk(obj,depth=0,path='root'):
        if depth>5: return
        if isinstance(obj,dict):
            for k,v in obj.items():
                low=str(k).lower(); p=f'{path}.{k}'
                if low in ('phase','runtime_phase','strategy_live_phase_v1028') and isinstance(v,(str,int,float)):
                    active['phase']=str(v); active['source']=p
                if 'phase_started' in low or low in ('phase_at','runtime_phase_at'): active['started']=v
                if 'phase_elapsed' in low: active['elapsed_sec']=v
                if low in ('top_phases','phases'):
                    if isinstance(v,list):
                        for row in v:
                            if isinstance(row,dict): add(row.get('phase') or row.get('name'),row.get('wall_sec') or row.get('elapsed_sec') or row.get('sec'),row.get('cpu_sec'),row.get('rows'),p)
                    elif isinstance(v,dict):
                        for name,row in v.items():
                            if isinstance(row,dict): add(name,row.get('wall_sec') or row.get('elapsed_sec') or row.get('sec'),row.get('cpu_sec'),row.get('rows'),p)
                if isinstance(v,(dict,list)): walk(v,depth+1,p)
        elif isinstance(obj,list):
            for i,v in enumerate(obj[:80]):
                if isinstance(v,(dict,list)): walk(v,depth+1,f'{path}[{i}]')
    walk(status)
    phases=list(phase_map.values())
    for row in phases: row['source']=' | '.join(row.pop('sources',[])[:3])
    phases.sort(key=lambda x:float(x.get('wall_sec') or 0),reverse=True)
    return {'active':active,'top':phases[:15]}


def _ops_extract_queue_network(status: dict) -> tuple[dict,dict]:
    queue={}; network={}
    queue_terms=('queue','backlog','pending','oldest','row_count','target_count','evaluated','selected','pool_count')
    network_terms=('reconnect','timeout','rate_limit','rest','ws','micro','latency','ping','clock','fresh_ws','fresh_micro','error_count')
    def walk(obj,depth=0,path='root'):
        if depth>4 or not isinstance(obj,dict): return
        for k,v in obj.items():
            low=str(k).lower(); p=f'{path}.{k}'
            if isinstance(v,(str,int,float,bool)) or v is None:
                if any(t in low for t in queue_terms) and len(queue)<30: queue[p]=v
                if any(t in low for t in network_terms) and len(network)<40: network[p]=v
            elif isinstance(v,dict): walk(v,depth+1,p)
    walk(status)
    return queue,network


def _ops_count_lines(path: Path, max_bytes: int = 16*1024*1024):
    try:
        size=path.stat().st_size
        if size>max_bytes: return None
        total=0
        with path.open('rb') as handle:
            while True:
                chunk=handle.read(1024*1024)
                if not chunk: break
                total += chunk.count(b'\n')
        return total
    except Exception:
        return None


def _ops_file_class(name: str) -> str:
    low=name.lower()
    if any(x.lower() in low for x in _OPS_PROTECTED_PATTERNS): return 'PROTECTED_CORE'
    if any(x.lower() in low for x in _OPS_NONCORE_PATTERNS): return 'NONCORE_REVIEW'
    return 'STATE_OR_STATUS'


