def _ops_history_samples(previous: dict, name: str, now_ts: float, proc: dict, phase: dict) -> list:
    all_samples=previous.get('resource_samples') if isinstance(previous.get('resource_samples'),dict) else {}
    current_pid=int(proc.get('pid') or 0)
    rows=[x for x in list(all_samples.get(name) or []) if isinstance(x,dict) and int(x.get('pid') or 0)==current_pid]
    rows=rows[-(OPS_MAP_RESOURCE_SAMPLE_LIMIT-1):]
    rows.append({'ts':now_ts,'pid':current_pid,'rss_mb':proc.get('rss_mb'),'rss_hwm_mb':proc.get('rss_hwm_mb'),'cpu_pct':proc.get('cpu_pct'),
                 'read_mb_s':proc.get('read_mb_s'),'write_mb_s':proc.get('write_mb_s'),
                 'phase':((phase.get('active') or {}).get('phase'))})
    return rows[-OPS_MAP_RESOURCE_SAMPLE_LIMIT:]


def _ops_resource_trend(samples: list, now_ts: float) -> dict:
    rows=[x for x in samples if isinstance(x,dict) and isinstance(x.get('rss_mb'),(int,float))]
    if not rows: return {'sample_count':0,'trend_state':'NO_SAMPLE'}
    vals=[float(x['rss_mb']) for x in rows]
    last_5=[x for x in rows if now_ts-float(x.get('ts') or 0)<=300]
    last_60=[x for x in rows if now_ts-float(x.get('ts') or 0)<=3600]
    span_sec=max(0.0,float(last_60[-1].get('ts') or now_ts)-float(last_60[0].get('ts') or now_ts)) if len(last_60)>=2 else 0.0
    trend=None
    trend_state='INSUFFICIENT_WINDOW'
    # v1108: do not label a short restart window as a measured hourly trend.
    # Require both sufficient density and at least 30 minutes on the same PID.
    if len(last_60)>=30 and span_sec>=1800:
        trend=(float(last_60[-1]['rss_mb'])-float(last_60[0]['rss_mb']))/span_sec*3600
        trend_state='MEASURED'
    peak_row=max(rows,key=lambda x:float(x.get('rss_mb') or 0))
    return {'sample_count':len(rows),'sample_span_sec':round(span_sec,1),'trend_state':trend_state,
            'rss_min_mb':round(min(vals),2),'rss_max_mb':round(max(vals),2),'rss_p95_mb':_ops_percentile(vals,0.95),
            'rss_5m_peak_mb':round(max(float(x['rss_mb']) for x in last_5),2) if last_5 else None,
            'rss_60m_peak_mb':round(max(float(x['rss_mb']) for x in last_60),2) if last_60 else None,
            'rss_trend_mb_h':round(trend,2) if trend is not None else None,
            'peak_ts':peak_row.get('ts'),'nearest_sampled_phase':peak_row.get('phase'),
            'phase_relation':'nearest_sample_only_not_causal'}


def _ops_artifact_row(name: str, fresh_limit: float) -> dict:
    path=BOT_DIR/name
    try:
        st=path.stat(); age=max(0.0,time.time()-st.st_mtime)
        exists_only=bool(fresh_limit is None or float(fresh_limit)<=0)
        return {'name':name,'exists':True,'size_bytes':st.st_size,'age_sec':round(age,2),'fresh_limit_sec':None if exists_only else fresh_limit,
                'freshness_policy':'EXISTS_ONLY' if exists_only else 'MAX_AGE',
                'status':'NORMAL' if exists_only or age<=float(fresh_limit) else 'CHECK'}
    except Exception:
        return {'name':name,'exists':False,'size_bytes':None,'age_sec':None,'fresh_limit_sec':fresh_limit,'status':'UNKNOWN'}



def _ops_int_v1102(value: Any, default: int = 0) -> int:
    try:
        if value in (None, '', [], {}): return int(default)
        return int(float(value))
    except Exception:
        return int(default)


def _ops_float_v1102(value: Any):
    try:
        if value in (None, '', [], {}): return None
        out=float(value)
        return out if math.isfinite(out) else None
    except Exception:
        return None


def _ops_count_rows_v1102(path: Path):
    try:
        obj=read_json(path)
    except Exception:
        obj=None
    if isinstance(obj,list): return len([x for x in obj if isinstance(x,dict)])
    if isinstance(obj,dict):
        for key in ('rows','items','positions','open_positions','candidates','data'):
            value=obj.get(key)
            if isinstance(value,list): return len([x for x in value if isinstance(x,dict)])
            if isinstance(value,dict): return len([x for x in value.values() if isinstance(x,dict)])
        if obj and all(isinstance(v,dict) for v in obj.values()): return len(obj)
        if not obj: return 0
    return None


def _ops_stage_v1102(step: int, name: str, owner: str, runtime: str='NORMAL', input_count=None, output_count=None,
                     blocked_count: int=0, pending_count: int=0, error_count: int=0, reason_counts=None,
                     source: str='정보없음', age_sec=None, cycle_sec=None, critical: bool=True, note: str='',
                     accounting_mode: str='TERMINAL_FLOW') -> dict:
    runtime=str(runtime or 'UNKNOWN').upper()
    if runtime=='DOWN': state='FAIL'
    elif runtime not in ('NORMAL','IDLE'): state='CHECK'
    elif error_count>0: state='CHECK'
    elif critical and input_count is None and output_count is None: state='UNKNOWN'
    else: state='IDLE' if runtime=='IDLE' else 'NORMAL'
    blocked_i=int(blocked_count or 0); pending_i=int(pending_count or 0); error_i=int(error_count or 0)
    balance_ok=None; unaccounted=None; overaccounted=None; inventory_extra=0
    mode=str(accounting_mode or 'TERMINAL_FLOW').upper()
    if input_count is not None and output_count is not None:
        expected=_ops_int_v1102(input_count,0); output_i=_ops_int_v1102(output_count,0)
        if mode=='CACHE_INVENTORY_COVERAGE':
            # Current-cycle target universe and persistent cache inventory are not
            # terminal branches of one funnel.  Extra cache rows are retained
            # coverage, not over-accounting.  Missing current targets are still
            # visible through pending/unaccounted.
            inventory_extra=max(0,output_i-expected)
            comparable_output=min(expected,output_i)
            accounted=comparable_output+blocked_i+pending_i+error_i
            unaccounted=max(0,expected-accounted); overaccounted=0; balance_ok=(unaccounted==0)
        else:
            accounted=output_i+blocked_i+pending_i+error_i
            unaccounted=max(0,expected-accounted); overaccounted=max(0,accounted-expected); balance_ok=(unaccounted==0 and overaccounted==0)
        if critical and not balance_ok and state in ('NORMAL','IDLE'): state='CHECK'
    return {
        'step':step,'name':name,'owner':owner,'state':state,'runtime_state':runtime,
        'input_count':input_count,'output_count':output_count,'blocked_count':blocked_i,
        'pending_count':pending_i,'error_count':error_i,'balance_ok':balance_ok,'unaccounted_count':unaccounted,'overaccounted_count':overaccounted,
        'accounting_mode_v1120':mode,'inventory_extra_count_v1120':inventory_extra,
        'reason_counts':reason_counts if isinstance(reason_counts,dict) else {},
        'source':source or '정보없음','source_age_sec':age_sec,'cycle_sec':cycle_sec,
        'information_state':'KNOWN' if any(x is not None for x in (input_count,output_count,age_sec,cycle_sec)) else '정보없음',
        'note':note or None,
    }




