def _ops_path_v1106(obj: Any, *paths: str):
    for path in paths:
        cur=obj
        ok=True
        for key in str(path).split('.'):
            if not isinstance(cur,dict) or key not in cur:
                ok=False; break
            cur=cur.get(key)
        if ok and cur not in (None,'',[],{}):
            return cur
    return None


def _ops_phase_writer_v1106(phase: str) -> str:
    low=str(phase or '').lower()
    if 'status_write' in low: return 'paper_bot.write_status -> _atomic_write_status_payload'
    if 'candidate' in low or 'select' in low: return 'paper_bot.select_candidates'
    if 'performance' in low or 'score' in low or 'canonical' in low: return 'paper_bot.write_score_cache'
    if 'exit' in low or 'monitor' in low: return 'paper_bot.run_exact_exit_monitor'
    if 'open' in low and ('write' in low or 'flush' in low): return 'paper_bot._v1054_stream_write_open_verified / _v1055_flush_open_state'
    if 'closed' in low or 'commit' in low: return 'paper_bot canonical CLOSED/decision commit owner'
    return f'paper_bot runtime phase:{phase or "unknown"}'


def _ops_risk_root_cause_v1106(risk_status: dict, nowv: float) -> dict:
    status=risk_status if isinstance(risk_status,dict) else {}
    updated=_ops_float_v1102(status.get('updated_ts')) or 0.0
