# =============================================================================
# guard v2.5.2000: full-worker hash-aware fast bundle continuation
# - Preserves the v1708 fast-upgrade idea without its strategy-only worker alias scope.
# - Compile exact manifest files, atomically swap changed aliases, restart changed services only.
# - No deep verify or long freshness wait inside apply; /grelease_verify owns server proof.
# =============================================================================
def _v2000_manifest_aliases(manifest: dict) -> dict:
    out = {}
    aliases = manifest.get('aliases') if isinstance(manifest.get('aliases'), dict) else {}
    for alias, src in aliases.items():
        if isinstance(alias, str) and isinstance(src, str) and alias and src:
            out[alias] = src
    defaults = {
        'bot.py': manifest.get('main'),
        'paper_bot.py': manifest.get('paper'),
        'backga_guard_bot.py': manifest.get('guard'),
        'ws_sidecar.py': manifest.get('ws') or manifest.get('ws_sidecar'),
        'bithumb_micro_sidecar.py': manifest.get('micro') or manifest.get('micro_sidecar'),
    }
    workers = manifest.get('workers') if isinstance(manifest.get('workers'), dict) else {}
    for key, spec in WORKER_SPECS.items():
        src = workers.get(key)
        if isinstance(src, str) and src:
            defaults[str(spec.get('active') or f'{key}_worker.py')] = src
    if not workers.get('strategy') and isinstance(manifest.get('strategy'), str):
        defaults['strategy_worker.py'] = manifest.get('strategy')
    for alias, src in defaults.items():
        if isinstance(src, str) and src:
            out.setdefault(alias, src)
    return out


def _v2000_copy_alias(src_name: str, alias_name: str) -> dict:
    src = BOT_DIR / str(src_name)
    dst = BOT_DIR / str(alias_name)
    if not src.exists():
        raise RuntimeError(f'missing source for {alias_name}: {src_name}')
    if src.suffix == '.py':
        okc, out = py_compile(src)
        if not okc:
            raise RuntimeError(f'py_compile failed {src_name}: {tail(out,900)}')
    src_hash = sha256_file(src)
    dst_hash = sha256_file(dst) if dst.exists() else ''
    if dst_hash and dst_hash == src_hash:
        return {'alias':alias_name,'source':src_name,'changed':False,'note':f'same hash · restart skip {alias_name}'}
    tmp = BOT_DIR / f'.{alias_name}.v2000tmp.{os.getpid()}.{time.time_ns()}'
    shutil.copy2(src, tmp)
    if sha256_file(tmp) != src_hash:
        try: tmp.unlink(missing_ok=True)
        except Exception: pass
        raise RuntimeError(f'hash mismatch alias {alias_name}')
    os.replace(tmp, dst)
    return {'alias':alias_name,'source':src_name,'changed':True,'note':f'changed {alias_name} <- {src_name}'}


def _v2000_fast_restart(service: str, label: str, timeout: int = 10) -> str:
    try:
        if not service or not service_exists(service):
            return f'{label}: no_service'
        rc, out = run(['systemctl','restart',service], timeout=timeout)
        if rc == 124:
            return f'{label}: restart timeout {timeout}s · service may still be restarting'
        return f'{label}: restart rc={rc} active={is_service_active(service)}'
    except Exception as exc:
        return f'{label}: restart error {exc.__class__.__name__}: {exc}'


def _v2000_apply_release_bundle_once_fast(req: dict) -> tuple[bool, str]:
    t0 = perf_now()
    bundle = _release_bundle_path(str(req.get('explicit') or ''))
    if not bundle:
        return False, f"bundle missing: {req.get('explicit') or '-'}"
    actual_digest = sha256_file(bundle)
    expected_digest = str(req.get('bundle_digest') or '')
    if expected_digest and expected_digest != actual_digest:
        return False, f'bundle digest mismatch {expected_digest[:12]}->{actual_digest[:12]}'
    work = BOT_DIR / f'.bundle_continue_fast_v2000_{os.getpid()}_{time.time_ns()}'
    notes=[]; restarts=[]; manifest={}
    try:
        work.mkdir(parents=True, exist_ok=False)
        with zipfile.ZipFile(bundle,'r') as z:
            bad=z.testzip()
            if bad:
                return False, f'zip damage: {bad}'
            z.extractall(work)
        manifest_path = work/'DEPLOY_BUNDLE.json'
        manifest = read_json(manifest_path) if manifest_path.exists() else _bundle_manifest_defaults(work)
        if not isinstance(manifest, dict):
            return False, 'DEPLOY_BUNDLE.json invalid'
        manifest = _normalize_bundle_manifest(manifest, work)
        notes += _copy_bundle_files_to_repo(work, manifest)
        manifest_py=[]
        for key in ('main','paper','guard','ws','micro','ws_sidecar','micro_sidecar'):
            value=manifest.get(key)
            if isinstance(value,str) and value: manifest_py.append(value)
        workers = manifest.get('workers') if isinstance(manifest.get('workers'),dict) else {}
        for value in workers.values():
            if isinstance(value,str) and value: manifest_py.append(value)
        for rel in manifest.get('support_files') if isinstance(manifest.get('support_files'),list) else []:
            if isinstance(rel,str) and rel.endswith('.py'): manifest_py.append(rel)
        compile_notes=[]
        for rel in sorted(set(manifest_py)):
            path=BOT_DIR/rel
            if not path.exists():
                return False, f'manifest python missing after copy: {rel}'
            okc,out=py_compile(path)
            if not okc:
                return False, f'py_compile failed {rel}: {tail(out,1200)}'
            compile_notes.append(f'compile ok {rel}')
        alias_results=[]
        for alias, src in _v2000_manifest_aliases(manifest).items():
            alias_results.append(_v2000_copy_alias(src, alias))
        changed_aliases={str(x.get('alias')) for x in alias_results if x.get('changed')}
        if manifest.get('main'):
            try:
                (BOT_DIR/'DEPLOY_TARGET.txt').write_text(str(manifest.get('main')).strip()+'\n', encoding='utf-8')
                write_deploy_markers(str(manifest.get('main')))
            except Exception as exc:
                notes.append(f'deploy marker warning: {exc.__class__.__name__}: {exc}')
        try:
            if manifest.get('paper'): (BOT_DIR/DEPLOYED_PAPER_FILE).write_text(str(manifest.get('paper'))+'\n', encoding='utf-8')
            if workers.get('strategy'): (BOT_DIR/'.deployed_strategy_worker_target').write_text(str(workers.get('strategy'))+'\n', encoding='utf-8')
            if manifest.get('guard'): (BOT_DIR/DEPLOYED_GUARD_FILE).write_text(str(manifest.get('guard'))+'\n', encoding='utf-8')
        except Exception:
            pass
        # Restart only aliases whose source hash changed.
        for key, spec in WORKER_SPECS.items():
            alias=str(spec.get('active') or '')
            if alias and alias in changed_aliases:
                restarts.append(_v2000_fast_restart(str(spec.get('service') or ''), key, timeout=10))
        if 'paper_bot.py' in changed_aliases:
            paper_src=str(manifest.get('paper') or '')
            paper_expected=_v399_expected_paper_version(BOT_DIR/paper_src) if paper_src else extract_paper_version(BOT_DIR/PAPER_ACTIVE_FILE)
            paper_build=extract_assignment(BOT_DIR/paper_src,'BUILD_LABEL') if paper_src else extract_assignment(BOT_DIR/PAPER_ACTIVE_FILE,'BUILD_LABEL')
            paper_hash=short_hash(BOT_DIR/paper_src) if paper_src else short_hash(BOT_DIR/PAPER_ACTIVE_FILE)
            paper_state,paper_notes=restart_paper_bot(paper_expected,'' if paper_build=='?' else paper_build,paper_hash)
            restarts.append('paper owner-safe: state='+str(paper_state)+' / '+ ' / '.join(paper_notes[-8:]))
        if 'bot.py' in changed_aliases: restarts.append(_v2000_fast_restart(MAIN_SERVICE,'main',timeout=10))
        if 'ws_sidecar.py' in changed_aliases: restarts.append(_v2000_fast_restart(WS_SERVICE,'ws',timeout=10))
        if 'bithumb_micro_sidecar.py' in changed_aliases: restarts.append(_v2000_fast_restart(MICRO_SERVICE,'micro',timeout=10))
        write_json(BOT_DIR / UPGRADE_STATUS_FILE, {
            'time':now(),'ok':True,'stage':'v2000_fast_hash_apply','bundle':bundle.name,'manifest':manifest,
            'guard_version':VERSION,'total_sec':perf_now()-t0,'changed_aliases':sorted(changed_aliases),
            'restart_count':len(restarts),'auto_buy':False,
        })
        body='\n'.join([
            '✅ 자동 배포 빠른적용 완료 · v2000',
            f'- bundle: {bundle.name}',f'- total: {fmt_sec(perf_now()-t0)}',
            f'- changed alias: {len(changed_aliases)} / restart: {len(restarts)}',
            '- 방식: exact manifest compile → hash 비교 → 바뀐 alias만 원자교체 → 바뀐 서비스만 재시작',
            '- 긴 fresh wait/deep verify 생략 · 서버 증명은 /grelease_verify',
            '- 자동매수 OFF', '', '[compile]', *compile_notes[:20], '', '[alias]',
            *[str(x.get('note')) for x in alias_results[:20]], '', '[restart]', *restarts, '', '[notes]', *notes[:10]
        ])
        return True, body
    except Exception as exc:
        return False, f'⚠️ v2000 fast continuation 예외: {exc.__class__.__name__}: {exc}\n{tail(traceback.format_exc(),5000)}'
    finally:
        shutil.rmtree(work, ignore_errors=True)

_apply_release_bundle_once = _v2000_apply_release_bundle_once_fast
_v2000_original_gupgrade_bundle_text = gupgrade_bundle_text

def gupgrade_bundle_text(force: bool = False, explicit: Optional[str] = None, skip_git: bool = False, post_commands=None) -> str:
    active_job = _load_release_job(max_age_sec=7200.0)
    if active_job:
        try: age = time.time() - float(active_job.get('created_ts') or 0)
        except Exception: age = 999999.0
        queued = _normalize_post_upgrade_commands_v1030(active_job.get('post_commands') or [])
        explicit_req = Path(str(explicit or '')).name
        active_bundle = Path(str(active_job.get('explicit') or '')).name
        same_bundle = (not explicit_req) or (active_bundle and explicit_req == active_bundle)
        if same_bundle:
            try:
                resumed = resume_guard_release_job()
                if resumed:
                    return grelease_last_text()
            except Exception as resume_exc:
                return f'📦 ⚠️ 자동 이어가기 직접 재개 실패 · v2000\n- {resume_exc.__class__.__name__}: {resume_exc}'
        if (not queued and age > 60.0) or (explicit_req and active_bundle and explicit_req != active_bundle and not queued):
            _clear_release_continuation_state_v1435('v2000_auto_clear_stale_fast')
        else:
            return '\n'.join([
                '📦 ⚠️ 자동 이어가기 1건 처리 중 · v2000',
                f"- request: {active_job.get('request_id') or '-'}",f"- bundle: {active_job.get('explicit') or '-'}",
                f'- age: {age:.1f}s',f'- 이어실행 예약: {len(queued)}개','- 중복 실행하지 않음',
                '- 새 가드가 이어가지 않으면 같은 /gupgrade_bundle 1회로 재개',
            ])
    return _v2000_original_gupgrade_bundle_text(force=force, explicit=explicit, skip_git=skip_git, post_commands=post_commands)


