# =============================================================================
# guard v2.5.2005 / v2005: command-first intake + 7-day disk owner board/cleanup
# - Polling foreground accepts and ACKs immediately; one serial command worker executes heavy commands.
# - Restores fixed /gbigfiles /gdisk /gdisk_full /gclean_disk commands before main().
# - Ordinary non-core logs/traces/caches/shadows/tmp/old ZIP/archive older than 7 days are removable.
# - Active core ledgers are protected. Only already cold/rotated core segments are gzip-compressed.
# - No trading/candidate/exit rule mutation. Auto-buy OFF.
# =============================================================================
V2005_DISK_RETENTION_DAYS=7
V2005_DISK_RETENTION_SEC=float(V2005_DISK_RETENTION_DAYS*86400)
V2005_DISK_STATUS=BOT_DIR/'guard_disk_v2005_status.json'
V2005_COMMAND_LATENCY_STATUS=BOT_DIR/'guard_command_latency_v2005.json'

_V2005_PREV_GUARD_COMMAND_MENU_ITEMS=guard_command_menu_items
def guard_command_menu_items() -> list[dict]:
    items=[x for x in _V2005_PREV_GUARD_COMMAND_MENU_ITEMS() if isinstance(x,dict) and str(x.get('command') or '') not in {'gcleanup','gdisk_full','gdisk','gclean_disk','gbigfiles'}]
    disk=[
        {'command':'gdisk_full','description':'디스크 큰파일·20초 증가 전체판'},
        {'command':'gdisk','description':'디스크 빠른 상태'},
        {'command':'gclean_disk','description':'7일 초과 안전정리'},
        {'command':'gbigfiles','description':'큰 파일 TOP'},
    ]
    # 업그레이드 메뉴 다음에 디스크 고정명령을 노출한다.
    return items[:7]+disk+items[7:]

_V2005_CORE_WORDS=('paper_bot_open','paper_bot_closed','trade_log','decision','exact','change_verify','issue','performance','canonical_performance','score')
_V2005_COLD_WORDS=('archive','cold','segment','rotated','history')
_V2005_NONCORE_WORDS=('log','trace','cache','shadow','tmp','temp','export','report','archive','backup','bundle_unpack','__pycache__','apply_bundle')
_V2005_DELETE_SUFFIXES=('.pyc','.pyo','.tmp','.bak','.old')
_V2005_DELETE_DIR_NAMES=('__pycache__','.pytest_cache','apply_bundle','tmp','temp')


def _v2005_fmt_bytes(value: Any) -> str:
    try: n=float(value or 0)
    except Exception: return '-'
    for unit in ('B','KB','MB','GB','TB','PB','EB'):
        if n<1024.0 or unit=='EB': return f'{int(n)}B' if unit=='B' else f'{n:.1f}{unit}'
        n/=1024.0
    return f'{n:.1f}TB'


def _v2005_rel(path: Path) -> str:
    try: return path.relative_to(BOT_DIR).as_posix()
    except Exception: return str(path)


def _v2005_is_active_core(path: Path) -> bool:
    rel=_v2005_rel(path).lower(); name=path.name.lower()
    core=any(word in rel for word in _V2005_CORE_WORDS)
    cold=any(word in rel for word in _V2005_COLD_WORDS)
    # cache/trace derivatives are not core even if their names mention performance/decision.
    derivative=any(word in rel for word in ('cache','trace','debug','tmp','shadow'))
    return bool(core and not cold and not derivative and not name.endswith('.gz'))


def _v2005_is_cold_core_segment(path: Path) -> bool:
    rel=_v2005_rel(path).lower()
    return bool(path.is_file() and any(word in rel for word in _V2005_CORE_WORDS) and any(word in rel for word in _V2005_COLD_WORDS) and not rel.endswith('.gz'))


def _v2005_is_active_source(path: Path) -> bool:
    name=path.name
    if name in {'bot.py','paper_bot.py','strategy_worker.py','backga_guard_bot.py','ws_sidecar.py','bithumb_micro_sidecar.py','candle_worker.py','feature_worker.py','scanner_worker.py','orderflow_worker.py','target_router_worker.py','risk_worker.py','review_worker.py','market_regime_worker.py'}:
        return True
    try:
        if path.suffix=='.py' and path.parent==BOT_DIR:
            return True
    except Exception: pass
    return False


def _v2005_file_age(path: Path, nowv: Optional[float]=None) -> float:
    try: return max(0.0,float(nowv or time.time())-float(path.stat().st_mtime))
    except Exception: return 0.0


def _v2005_walk_files() -> list[Path]:
    out=[]
    for root, dirs, files in os.walk(BOT_DIR):
        # proc-like and git internals are not expected here; skip nested venv if present.
        dirs[:]=[d for d in dirs if d not in {'.git','.venv','venv'}]
        for name in files:
            p=Path(root)/name
            try:
                if p.is_file() or p.is_symlink(): out.append(p)
            except OSError: continue
    return out


def _v2005_scan_sizes() -> dict[str,int]:
    rows={}
    for path in _v2005_walk_files():
        try: rows[_v2005_rel(path)]=int(path.stat().st_size)
        except OSError: continue
    return rows


def _v2005_big_tag(path: Path) -> str:
    rel=_v2005_rel(path).lower()
    if _v2005_is_active_core(path): return 'PROTECT_ACTIVE'
    if _v2005_is_cold_core_segment(path): return 'CORE_GZIP'
    if _v2005_cleanup_candidate(path): return 'CLEAN_7D' if _v2005_file_age(path)>=V2005_DISK_RETENTION_SEC else 'KEEP_RECENT'
    if any(w in rel for w in _V2005_NONCORE_WORDS): return 'CHECK'
    return 'CHECK'


def _v2005_cleanup_candidate(path: Path) -> bool:
    if not path.exists() or not path.is_file(): return False
    if _v2005_is_active_core(path) or _v2005_is_active_source(path): return False
    rel=_v2005_rel(path).lower(); name=path.name.lower()
    if _v2005_is_cold_core_segment(path): return False
    if name.startswith('coinbot_update_v') and name.endswith('.zip'): return True
    if name.startswith('코인봇_최신전체코드_') and name.endswith('.zip'): return True
    if path.suffix.lower()=='.zip': return True
    if any(w in rel for w in _V2005_NONCORE_WORDS): return True
    if path.suffix.lower() in _V2005_DELETE_SUFFIXES: return True
    return False


def _v2005_open_deleted_files(limit: int=20) -> list[dict]:
    rows=[]; bot_prefix=str(BOT_DIR)
    proc=Path('/proc')
    try:
        pids=[p for p in proc.iterdir() if p.name.isdigit()]
    except Exception: return rows
    for pid in pids:
        fd_dir=pid/'fd'
        try:
            for fd in fd_dir.iterdir():
                try: target=os.readlink(fd)
                except OSError: continue
                if '(deleted)' in target and bot_prefix in target:
                    rows.append({'pid':int(pid.name),'fd':fd.name,'target':target[:300]})
                    if len(rows)>=limit: return rows
        except (OSError,PermissionError): continue
    return rows


def _v2005_growth_sample(sample_sec: float=20.0, limit: int=15) -> list[dict]:
    before=_v2005_scan_sizes(); started=time.monotonic()
    time.sleep(max(0.0,float(sample_sec)))
    after=_v2005_scan_sizes(); elapsed=max(0.001,time.monotonic()-started)
    rows=[]
    for rel,size2 in after.items():
        delta=int(size2)-int(before.get(rel,0))
        if delta>0:
            rows.append({'path':rel,'delta_bytes':delta,'size_bytes':size2,'elapsed_sec':round(elapsed,3),'projected_mb_h':round((delta/1024/1024)*(3600/elapsed),3)})
    rows.sort(key=lambda x:x['delta_bytes'],reverse=True)
    return rows[:max(1,int(limit))]


def gbigfiles_text(limit=40) -> str:
    try: limit=max(10,min(100,int(limit or 40)))
    except Exception: limit=40
    sizes=_v2005_scan_sizes(); rows=sorted(sizes.items(),key=lambda kv:kv[1],reverse=True)[:limit]
    du=shutil.disk_usage(str(BOT_DIR))
    lines=['📦 큰 파일 TOP /gbigfiles · v2006',f'- 디스크 남음 {_v2005_fmt_bytes(du.free)} / 사용 {_v2005_fmt_bytes(du.used)}','- PROTECT_ACTIVE=활성 핵심장부 · CORE_GZIP=오래된 분할장부 압축대상 · CLEAN_7D=7일 초과 정리대상','','[큰 파일 TOP]']
    for rel,size in rows:
        path=BOT_DIR/rel
        lines.append(f'- {_v2005_big_tag(path)} · {_v2005_fmt_bytes(size)} · {rel}')
    lines += ['','[잠금]','- 활성 OPEN/CLOSED/trade_log/decision/exact/change/issue/performance 원장 직접 삭제·축소 안 함','- 자동매수 OFF']
    return '\n'.join(lines)


def gdisk_text_v2005() -> str:
    du=shutil.disk_usage(str(BOT_DIR)); sizes=_v2005_scan_sizes(); rows=sorted(sizes.items(),key=lambda kv:kv[1],reverse=True)[:10]
    lines=['💽 디스크 빠른판 /gdisk · v2006',f'- 남음 {_v2005_fmt_bytes(du.free)} / 사용 {_v2005_fmt_bytes(du.used)} / 전체 {_v2005_fmt_bytes(du.total)}','- 일반 운영자료 보관 7일 · 활성 핵심장부 보호 · cold segment gzip','','[큰 파일 TOP 10]']
    for rel,size in rows: lines.append(f'- {_v2005_big_tag(BOT_DIR/rel)} · {_v2005_fmt_bytes(size)} · {rel}')
    lines += ['','- 증가속도는 /gdisk_full에서 20초 실측','- 실제 정리는 /gclean_disk','- 자동매수 OFF']
    return '\n'.join(lines)


def gdisk_full_text_v2005(sample_sec: float=20.0) -> str:
    du0=shutil.disk_usage(str(BOT_DIR)); sizes=_v2005_scan_sizes(); top=sorted(sizes.items(),key=lambda kv:kv[1],reverse=True)[:20]
    growth=_v2005_growth_sample(sample_sec=sample_sec,limit=15); du1=shutil.disk_usage(str(BOT_DIR)); deleted=_v2005_open_deleted_files()
    payload={'schema':'guard_disk_v2005_status','version':VERSION,'build':BUILD_LABEL,'updated_ts':time.time(),'updated_text':now(),'sample_sec':sample_sec,'free_bytes':du1.free,'top_files':top,'growth_top':growth,'open_deleted':deleted,'retention_days':7,'auto_buy':False}
    try: write_json(V2005_DISK_STATUS,payload)
    except Exception: pass
    lines=['💽 디스크 전체판 /gdisk_full · v2005',f'- 남음 {_v2005_fmt_bytes(du1.free)} / 20초 전 대비 {du1.free-du0.free:+,}B',f'- 일반자료 7일 보관 / 활성 핵심장부 보호 / cold segment gzip', '', '[큰 파일 TOP 20]']
    for rel,size in top: lines.append(f'- {_v2005_big_tag(BOT_DIR/rel)} · {_v2005_fmt_bytes(size)} · {rel}')
    lines += ['','[빠른 증가 TOP]']
    if not growth: lines.append('- 증가 파일 없음')
    for row in growth: lines.append(f"- +{_v2005_fmt_bytes(row['delta_bytes'])} / {row['projected_mb_h']:.1f}MB/h · {row['path']}")
    lines += ['','[삭제 후 열린 파일]']
    if not deleted: lines.append('- 없음')
    for row in deleted[:20]: lines.append(f"- pid {row['pid']} fd {row['fd']} · {row['target']}")
    lines += ['','- 정리 명령: /gclean_disk','- 자동매수 OFF']
    return '\n'.join(lines)


def _v2005_gzip_cold_core(path: Path) -> tuple[bool,int,str]:
    before=int(path.stat().st_size); gz=path.with_suffix(path.suffix+'.gz')
    try:
        tmp=gz.with_name(gz.name+f'.tmp.{os.getpid()}')
        with path.open('rb') as src, gzip.open(tmp,'wb',compresslevel=6) as dst:
            shutil.copyfileobj(src,dst,1024*1024)
        with gzip.open(tmp,'rb') as chk:
            while chk.read(1024*1024): pass
        os.replace(tmp,gz); path.unlink()
        after=int(gz.stat().st_size)
        return True,max(0,before-after),_v2005_rel(gz)
    except Exception as exc:
        try:
            if 'tmp' in locals() and tmp.exists(): tmp.unlink()
        except Exception: pass
        return False,0,f'{type(exc).__name__}: {exc}'


def _v2005_collect_old_cleanup(nowv: Optional[float]=None) -> tuple[list[Path],list[Path]]:
    nowv=float(nowv or time.time()); delete=[]; gzip_rows=[]
    for path in _v2005_walk_files():
        try:
            if _v2005_file_age(path,nowv)<V2005_DISK_RETENTION_SEC: continue
            if _v2005_is_cold_core_segment(path): gzip_rows.append(path); continue
            if _v2005_cleanup_candidate(path): delete.append(path)
        except OSError: continue
    return delete,gzip_rows


def gclean_disk_text_v2005(dry_run: bool=False, sample_sec: float=20.0) -> str:
    before=shutil.disk_usage(str(BOT_DIR)); delete,gzip_rows=_v2005_collect_old_cleanup()
    deleted=[]; compressed=[]; errors=[]; freed=0
    for path in sorted(delete,key=lambda p:p.stat().st_size if p.exists() else 0,reverse=True):
        try:
            size=int(path.stat().st_size); rel=_v2005_rel(path)
            if dry_run: deleted.append((rel,size,'DRY')) ; freed+=size; continue
            path.unlink(missing_ok=True); deleted.append((rel,size,'OK')); freed+=size
        except Exception as exc: errors.append((_v2005_rel(path),f'{type(exc).__name__}: {exc}'))
    for path in sorted(gzip_rows,key=lambda p:p.stat().st_size if p.exists() else 0,reverse=True):
        rel=_v2005_rel(path)
        if dry_run:
            compressed.append((rel,0,'DRY')); continue
        ok,saved,note=_v2005_gzip_cold_core(path)
        if ok: compressed.append((note,saved,'OK')); freed+=saved
        else: errors.append((rel,note))
    # remove empty old junk directories only; never recursive-delete an active directory blindly.
    if not dry_run:
        for root,dirs,files in os.walk(BOT_DIR,topdown=False):
            for name in dirs:
                p=Path(root)/name
                try:
                    if name in _V2005_DELETE_DIR_NAMES and _v2005_file_age(p)>=V2005_DISK_RETENTION_SEC and not any(p.iterdir()): p.rmdir()
                except Exception: pass
    mid=shutil.disk_usage(str(BOT_DIR)); deleted_fds=_v2005_open_deleted_files(); growth=_v2005_growth_sample(sample_sec=sample_sec,limit=10); after=shutil.disk_usage(str(BOT_DIR))
    payload={'schema':'guard_disk_cleanup_v2005','version':VERSION,'build':BUILD_LABEL,'updated_ts':time.time(),'updated_text':now(),'dry_run':dry_run,'retention_days':7,'before_free':before.free,'after_free':after.free,'deleted_count':len(deleted),'compressed_count':len(compressed),'freed_estimate':freed,'errors':errors[:20],'open_deleted':deleted_fds,'growth_top':growth,'auto_buy':False}
    try: write_json(V2005_DISK_STATUS,payload)
    except Exception: pass
    title='🧹 디스크 안전정리 /gclean_disk · v2005' + (' DRY-RUN' if dry_run else '')
    lines=[title,f'- 전 남음 {_v2005_fmt_bytes(before.free)} → 정리직후 {_v2005_fmt_bytes(mid.free)} → 표본후 {_v2005_fmt_bytes(after.free)}',f'- 일반자료 7일 초과 삭제 {len(deleted)}개 / cold 핵심분할 gzip {len(compressed)}개 / 오류 {len(errors)}개',f'- 확보 추정 {_v2005_fmt_bytes(freed)}','- 활성 핵심장부 직접 삭제·축소 없음','','[삭제 TOP 15]']
    if not deleted: lines.append('- 없음')
    for rel,size,st in deleted[:15]: lines.append(f'- {st} · {_v2005_fmt_bytes(size)} · {rel}')
    lines += ['','[핵심 cold gzip TOP 10]']
    if not compressed: lines.append('- 없음')
    for rel,saved,st in compressed[:10]: lines.append(f'- {st} · 절감 {_v2005_fmt_bytes(saved)} · {rel}')
    lines += ['','[20초 증가 TOP]']
    if not growth: lines.append('- 증가 파일 없음')
    for row in growth: lines.append(f"- +{_v2005_fmt_bytes(row['delta_bytes'])} / {row['projected_mb_h']:.1f}MB/h · {row['path']}")
    lines += ['','[삭제 후 열린 파일]',f'- {len(deleted_fds)}건']
    for row in deleted_fds[:10]: lines.append(f"- pid {row['pid']} · {row['target']}")
    if errors:
        lines += ['','[오류 TOP 10]']
        for rel,msg in errors[:10]: lines.append(f'- {rel} · {msg}')
    lines += ['','- 자동매수 OFF']
    return '\n'.join(lines)


# command-first intake: one serial worker owns handle_command; polling never waits for it.
_V2005_COMMAND_QUEUE: 'queue.Queue[tuple]' = queue.Queue(maxsize=64)
_V2005_COMMAND_THREAD=None
_V2005_COMMAND_THREAD_LOCK=threading.Lock()


def _v2005_quick_ack_text(text: str) -> str:
    first=text.strip().split()[0].lower() if text.strip().split() else '/command'
    if first in ('/gupgrade_bundle','/gbundle','/gapply_bundle'):
        return '📦 /gupgrade_bundle 즉시 접수\n- 명령 수신 완료\n- 업그레이드 전용 빠른 길에서 처리\n- 무거운 지도·감사와 분리'
    if first in ('/gdisk_full',):
        return '💽 /gdisk_full 즉시 접수\n- 큰 파일 TOP + 20초 실제 증가량 측정\n- 측정은 뒤 작업, 명령 접수는 계속 가능'
    if first in ('/gclean_disk','/gcleanup','/cleanup','/gdisk_cleanup'):
        return '🧹 디스크 정리 즉시 접수\n- 일반자료 7일 초과 정리\n- 활성 핵심장부 보호 · cold 분할 gzip\n- 정리 후 20초 증가량 확인'
    return f'📥 {first} 즉시 접수\n- 명령 수신 완료\n- 무거운 처리는 단일 작업자에서 순서대로 실행'


def _v2005_guard_command_worker() -> None:
    while True:
        chat_id,text,accepted_mono,accepted_ts=_V2005_COMMAND_QUEUE.get()
        started=time.monotonic(); first=text.strip().split()[0].lower() if text.strip().split() else ''
        try:
            reply=handle_command(text)
            if first in ('/gupgrade_bundle','/gbundle','/gapply_bundle','/gupgrade','/gupgrade_all','/apply_latest','/upgradebot') and not _load_release_job():
                pseudo={'request_id':f'direct-{int(time.time()*1000)}','explicit':_last_success_bundle_name(),'bundle_digest':''}
                _queue_release_final(pseudo,('❌' not in str(reply) and '예외' not in str(reply)),str(reply))
                _deliver_pending_release_result_once()
            else:
                send(chat_id,reply)
        except Exception as exc:
            try: send(chat_id,f'❌ 명령 처리 오류 · {first}\n- {type(exc).__name__}: {exc}')
            except Exception: pass
        finally:
            try:
                write_json(V2005_COMMAND_LATENCY_STATUS,{
                    'schema':'guard_command_latency_v2005','version':VERSION,'build':BUILD_LABEL,
                    'updated_ts':time.time(),'updated_text':now(),'command':first,
                    'accept_to_worker_start_sec':round(max(0.0,started-accepted_mono),3),
                    'worker_elapsed_sec':round(max(0.0,time.monotonic()-started),3),
                    'queue_size_after':_V2005_COMMAND_QUEUE.qsize(),'polling_foreground_blocked':False,'auto_buy':False,
                })
            except Exception: pass
            _V2005_COMMAND_QUEUE.task_done()


def _v2005_guard_command_start() -> None:
    global _V2005_COMMAND_THREAD
    if _V2005_COMMAND_THREAD is not None and _V2005_COMMAND_THREAD.is_alive(): return
    with _V2005_COMMAND_THREAD_LOCK:
        if _V2005_COMMAND_THREAD is not None and _V2005_COMMAND_THREAD.is_alive(): return
        _V2005_COMMAND_THREAD=threading.Thread(target=_v2005_guard_command_worker,name='guard-v2005-command-serial',daemon=True)
        _V2005_COMMAND_THREAD.start()


def _v2005_guard_command_enqueue(chat_id: str, text: str) -> bool:
    _v2005_guard_command_start()
    accepted_mono=time.monotonic(); accepted_ts=time.time()
    try: send(chat_id,_v2005_quick_ack_text(text))
    except Exception: pass
    try:
        _V2005_COMMAND_QUEUE.put_nowait((chat_id,text,accepted_mono,accepted_ts))
        return True
    except queue.Full:
        try: send(chat_id,'⚠️ 가드 명령 대기열 가득 참\n- 새 명령은 실행하지 않음\n- 잠시 뒤 다시 실행')
        except Exception: pass
        return True


