def gdisk_full_text_v2007(sample_sec: float=20.0) -> str:
    sizes=_v2005_scan_sizes(); top=sorted(sizes.items(),key=lambda kv:kv[1],reverse=True)[:20]
    truth=_v2007_disk_truth_sample(sample_sec=sample_sec,interval_sec=1.0,limit=20)
    lines=['💽 디스크 전체판 /gdisk_full · v2007',f"- 남음 {_v2005_fmt_bytes(truth.get('free_after',0))} / {int(float(truth.get('sample_sec') or sample_sec))}초 free 변화 {int(truth.get('free_delta') or 0):+,}B",f"- 실제 사용량 변화 {int(truth.get('used_delta_bytes') or 0):+,}B / BOT_DIR {int(truth.get('bot_dir_net_delta_bytes') or 0):+,}B / /var/log {int(truth.get('var_log_delta_bytes') or 0):+,}B / journal {int(truth.get('journal_delta_bytes') or 0):+,}B",f"- 미추적 증가 {int(truth.get('untracked_delta_bytes') or 0):+,}B · {truth.get('untracked_state')}",'- 일반자료 7일 / 활성 핵심장부 보호 / sampler 자체 삭제 0','','[큰 파일 TOP 20]']
    for rel,size in top: lines.append(f'- {_v2005_big_tag(BOT_DIR/rel)} · {_v2005_fmt_bytes(size)} · {rel}')
    lines += ['','[같은 20초 파일 생명주기 TOP]']
    events=truth.get('top_events') if isinstance(truth.get('top_events'),list) else []
    if not events: lines.append('- 변화 파일 없음')
    for row in events:
        lines.append(f"- {_v2007_disk_event_label(row.get('class'))} · net {int(row.get('net_delta_bytes') or 0):+,}B · peak {_v2005_fmt_bytes(row.get('peak_seen_bytes') or 0)} · transient {_v2005_fmt_bytes(row.get('transient_peak_bytes') or 0)} · replace {row.get('replace_count',0)} · {row.get('path')}")
    lines += ['','[표본 요약]',f"- 신규 {truth.get('created_count',0)} / 사라짐 {truth.get('disappeared_count',0)} / atomic replace {truth.get('atomic_replace_count',0)} / tmp·rollback {truth.get('tmp_rollback_peak_count',0)} / WAL·SHM {truth.get('wal_shm_count',0)}",'','[삭제 후 열린 파일]']
    deleted=truth.get('open_deleted') if isinstance(truth.get('open_deleted'),list) else []
    if not deleted: lines.append('- 없음')
    for row in deleted[:20]: lines.append(f"- pid {row.get('pid')} fd {row.get('fd')} · {row.get('target')}")
    lines += ['','- 정리 명령: /gclean_disk','- 자동매수 OFF']
    return '\\n'.join(lines)

