VERSION = 'guard_v2.5.1709_disk_commands_premain_fix_2026-07-13'
BUILD_LABEL = 'v1709_GUARD_DISK_FUNCTION_PREMAIN_AND_VERSION_SCORE_PREMAIN_FIX_AUTOBUY_OFF_2026-07-13'
MAIN_DEPLOY_VERSION = BUILD_LABEL

_GDISK_PROTECTED_PATTERNS_V1709 = (
    'paper_bot_open.json','paper_bot_closed.jsonl','paper_bot_trade_log.jsonl','paper_trade_log.json',
    '*decision*','*exact*','*change_verify*','*issue*','*performance*','*score*','*good_s2*','trade_log*',
)
_GDISK_DELETE_FILE_PATTERNS_V1709 = (
    'coinbot_update_v*.zip','코인봇_최신전체코드_*.zip','*.backup_guard_apply_*','*.backup_guard_worker_apply_*',
    '*.backup_*','*.bak_*','*.tmp','*.pyc','*.pyo','*export*.txt','*trace*.tmp','*cache*.tmp',
)
_GDISK_DELETE_DIR_PATTERNS_V1709 = (
    'bundle_unpack_*','__pycache__','apply_bundle','.pytest_cache','tmp',
    'legacy_candidate_flow_archive_v*','trace_archive_v*','hot_watch_archive','cold_archive_v*',
    'v1413_legacy_path_state_archive','runtime/v1413_legacy_path_state_archive',
)

def _gclean_fmt_v1709(n):
    try: n=float(n)
    except Exception: return '-'
    for unit in ('B','KB','MB','GB','TB'):
        if n < 1024 or unit == 'TB':
            return f'{n:.1f}{unit}' if unit!='B' else f'{int(n)}B'
        n/=1024
    return f'{n:.1f}TB'

def _gclean_is_protected_v1709(path):
    try:
        rel = path.relative_to(BOT_DIR).as_posix().lower()
    except Exception:
        rel = str(path).lower()
    name = getattr(path, 'name', str(path))
    try:
        for pat in _GDISK_PROTECTED_PATTERNS_V1709:
            if path.match(pat) or Path(name).match(pat):
                return True
    except Exception:
        pass
    protected_words = ('open','closed','trade_log','decision','exact','change','issue','performance','score','good_s2')
    if any(w in rel for w in protected_words) and not any(x in rel for x in ('cache','trace_archive','hot_watch_archive','cold_archive','bundle_unpack','__pycache__')):
        return True
    return False

def _gclean_size_v1709(path):
    try:
        if path.is_file() or path.is_symlink():
            return int(path.stat().st_size)
        total=0
        for r,ds,fs in os.walk(path):
            for f in fs:
                try: total += int((Path(r)/f).stat().st_size)
                except OSError: pass
        return total
    except Exception:
        return 0

def gbigfiles_text(limit=40):
    try: limit=max(10,min(100,int(limit or 40)))
    except Exception: limit=40
    rows=[]
    try:
        for p in BOT_DIR.rglob('*'):
            try:
                if p.is_file():
                    rows.append((_gclean_size_v1709(p), p))
                elif p.is_dir() and (p.name.startswith('legacy_candidate_flow_archive') or p.name.startswith('bundle_unpack') or p.name in ('hot_watch_archive',) or 'archive' in p.name.lower()):
                    rows.append((_gclean_size_v1709(p), p))
            except OSError:
                continue
    except Exception as exc:
        return f'❌ 큰 파일 확인 실패 /gbigfiles · v1709\n- {type(exc).__name__}: {exc}\n- 자동매수 OFF · 원장 변경 없음'
    rows.sort(key=lambda x:x[0], reverse=True)
    du=shutil.disk_usage(str(BOT_DIR))
    lines=['📦 큰 파일 확인 /gbigfiles · v1709', f"- 디스크: 사용 {_gclean_fmt_v1709(du.used)} / 남음 {_gclean_fmt_v1709(du.free)} / 전체 {_gclean_fmt_v1709(du.total)}", '- 원장 보호 표시: PROTECT / 삭제후보: CLEAN_CANDIDATE', '', '[TOP]']
    if not rows: lines.append('- 파일 없음')
    for size,p in rows[:limit]:
        try: rel=p.relative_to(BOT_DIR).as_posix()
        except Exception: rel=str(p)
        prot=_gclean_is_protected_v1709(p)
        clean=(not prot) and (p.name.startswith('bundle_unpack') or p.name.startswith('legacy_candidate_flow_archive') or p.name.startswith('coinbot_update_v') or p.name.startswith('코인봇_최신전체코드_') or 'archive' in rel.lower() or p.suffix in ('.pyc','.pyo'))
        tag='PROTECT' if prot else ('CLEAN_CANDIDATE' if clean else 'CHECK')
        lines.append(f'- {tag} · {_gclean_fmt_v1709(size)} · {rel}')
    lines += ['', '[잠금]', '- OPEN/CLOSED/trade_log/decision/exact/change/issue/performance 원장 삭제 안 함', '- 자동매수 OFF']
    return '\n'.join(lines)

def _gclean_collect_targets_v1709(deep=False):
    targets=[]
    for pat in _GDISK_DELETE_FILE_PATTERNS_V1709:
        try: targets += [p for p in BOT_DIR.glob(pat) if p.exists()]
        except Exception: pass
    for pat in _GDISK_DELETE_DIR_PATTERNS_V1709:
        try: targets += [p for p in BOT_DIR.glob(pat) if p.exists()]
        except Exception: pass
        try: targets += [p for p in (BOT_DIR/'runtime').glob(Path(pat).name) if p.exists()]
        except Exception: pass
    if deep:
        for pat in ('*archive*','*trace*','*export*'):
            for base in (BOT_DIR, BOT_DIR/'runtime'):
                try: targets += [p for p in base.glob(pat) if p.exists()]
                except Exception: pass
    out=[]; seen=set()
    for p in targets:
        key=str(p)
        if key in seen: continue
        seen.add(key)
        if _gclean_is_protected_v1709(p): continue
        if p.name in ('bot.py','paper_bot.py','strategy_worker.py','backga_guard_bot.py'): continue
        out.append(p)
    return out

def gclean_disk_text(deep=False, dry_run=False):
    before=shutil.disk_usage(str(BOT_DIR))
    targets=_gclean_collect_targets_v1709(deep=deep)
    removed=[]; errors=[]; freed=0; protected_skipped=0
    for p in sorted(targets, key=lambda x:_gclean_size_v1709(x), reverse=True):
        if _gclean_is_protected_v1709(p):
            protected_skipped += 1; continue
        size=_gclean_size_v1709(p)
        try: rel=p.relative_to(BOT_DIR).as_posix()
        except Exception: rel=str(p)
        if dry_run:
            removed.append((rel,size,'DRY')); freed += size; continue
        try:
            if p.is_dir() and not p.is_symlink(): shutil.rmtree(p)
            else: p.unlink(missing_ok=True)
            removed.append((rel,size,'OK')); freed += size
        except Exception as exc:
            errors.append((rel,type(exc).__name__,str(exc)[:160]))
    after=shutil.disk_usage(str(BOT_DIR))
    title='🧹 디스크 강제정리 /gclean_disk deep · v1709' if deep else '🧹 디스크 정리 /gclean_disk · v1709'
    if dry_run: title += ' DRY-RUN'
    lines=[title, f"- 전: 남음 {_gclean_fmt_v1709(before.free)} / 사용 {_gclean_fmt_v1709(before.used)}", f"- 후: 남음 {_gclean_fmt_v1709(after.free)} / 사용 {_gclean_fmt_v1709(after.used)}", f"- 확보 추정 {_gclean_fmt_v1709(freed)} / 삭제 {len(removed)}개 / 오류 {len(errors)}개 / 보호 skip {protected_skipped}", '- 범위: ZIP/backup/bundle_unpack/cache/trace/archive 비핵심', '- core 원장 보호 · 자동매수 OFF', '', '[삭제 TOP 20]']
    if not removed: lines.append('- 삭제 대상 없음')
    for rel,size,st in removed[:20]: lines.append(f'- {st} · {_gclean_fmt_v1709(size)} · {rel}')
    if errors:
        lines += ['', '[오류 TOP 10]']
        for rel,typ,msg in errors[:10]: lines.append(f'- {rel} · {typ}: {msg}')
        lines += ['', '- Permission denied는 root 소유 찌꺼기 가능성이 큼. 필요 시 sudo 터미널 정리 필요.']
    lines += ['', '[삭제 금지 확인]', '- OPEN/CLOSED/trade_log/decision/exact/change/issue/performance 원장 직접 삭제 없음']
    return '\n'.join(lines)


