def _ops_build_flow_map_v1103(*args,**kwargs):  # type: ignore[override]
    flow=_V2036_PREV_FLOW_MAP(*args,**kwargs)
    if not isinstance(flow,dict): return flow
    root=Path(__file__).resolve().parent
    paper=_v2036_guard_load(root/'paper_bot_status.json')
    pre=_v2036_guard_load(root/'paper_v2036_preflight_status.json')
    fresh=_v2036_guard_load(root/'paper_v2036_fresh_start_status.json')
    open_obj=_v2036_guard_load(root/'paper_bot_open.json')
    effective=paper.get('effective_control_contract_v1142') if isinstance(paper.get('effective_control_contract_v1142'),dict) else {}
    unlimited=(effective.get('candidate_count_limit_mode')=='UNLIMITED_USER_APPROVED' or (effective.get('max_open_strict') is None and effective.get('max_new_per_cycle') is None))
    removed=0
    if unlimited:
        blocked=flow.get('blocked') if isinstance(flow.get('blocked'),dict) else {}
        for name in ('paper_reason_counts','paper_terminal_counts','paper_stage_terminal_counts'):
            section=blocked.get(name)
            if isinstance(section,dict):
                for key in list(section):
                    if str(key).upper() in {'OPEN_LIMIT','CYCLE_LIMIT','WAIT_CAPACITY'}:
                        try: removed+=int(section.get(key) or 0)
                        except Exception: pass
                        section.pop(key,None)
        trade=flow.get('trade_summary') if isinstance(flow.get('trade_summary'),dict) else {}
        trade['current_open']=len(open_obj); trade['canonical_open_owner_v2036']='paper_bot_open.json'
        for stage in flow.get('stages') or []:
            if isinstance(stage,dict) and int(stage.get('step') or 0)==15: stage['input_count']=len(open_obj)
        flow['blocked']=blocked; flow['trade_summary']=trade
    flow['v2036_mainline_preflight']={'state':pre.get('state') or 'WAITING','failed_checks':pre.get('failed_checks') or [],'canonical_open_count':len(open_obj),'fresh_start_state':fresh.get('state') or 'NOT_STARTED','fresh_epoch_id':fresh.get('epoch_id'),'new_open_maintenance_pause':fresh.get('state')!='ACTIVE','stale_capacity_reference_removed':removed,'unlimited_contract':unlimited,'shadow_histories_preserved':True,'auto_buy':False}
    return flow

