# =============================================================================
# Guard v2.6.2 / release v2041: resolved final runtime identity parser
# - The old regex saw only the last literal assignment. It missed aliases such as
#   BUILD_LABEL=PAPER_V2038_BUILD and BOT_VERSION=MAIN_VERSION, so healthy v2038
#   Paper and v2040 Main were falsely compared against stale v2035 labels.
# - Resolve simple top-level constant aliases in Python execution order.
# - Deployment/runtime verification only. Trading, ledgers, OPEN and exits unchanged.
# =============================================================================

def _v2041_static_value(node, env):
    if isinstance(node, ast.Constant) and isinstance(node.value, (str, int, float, bool)):
        return True, node.value
    if isinstance(node, ast.Name) and node.id in env:
        return True, env[node.id]
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        ok_l, left = _v2041_static_value(node.left, env)
        ok_r, right = _v2041_static_value(node.right, env)
        if ok_l and ok_r and isinstance(left, (str, int, float)) and isinstance(right, type(left)):
            try:
                return True, left + right
            except Exception:
                return False, None
    if isinstance(node, ast.JoinedStr):
        parts=[]
        for item in node.values:
            if isinstance(item, ast.Constant) and isinstance(item.value, str):
                parts.append(item.value); continue
            if isinstance(item, ast.FormattedValue):
                ok, value = _v2041_static_value(item.value, env)
                if ok:
                    parts.append(str(value)); continue
            return False, None
        return True, ''.join(parts)
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id=='str' and len(node.args)==1 and not node.keywords:
        ok, value = _v2041_static_value(node.args[0], env)
        return (True, str(value)) if ok else (False, None)
    return False, None

def _v2041_resolved_top_level_assignments(path: Path) -> dict:
    source = read_file(path)
    if not source:
        return {}
    env={}
    try:
        tree=ast.parse(source)
    except Exception:
        return {}
    for node in tree.body:
        if isinstance(node, ast.Assign):
            targets=node.targets; value=node.value
        elif isinstance(node, ast.AnnAssign):
            targets=[node.target]; value=node.value
        else:
            continue
        names=[target.id for target in targets if isinstance(target, ast.Name)]
        if not names:
            continue
        ok, resolved = _v2041_static_value(value, env)
        for name in names:
            if ok:
                env[name]=resolved
            else:
                # Do not retain an older literal after a later unresolved assignment.
                env.pop(name, None)
    return env

def extract_assignment(path: Path, key: str) -> str:  # type: ignore[override]
    resolved=_v2041_resolved_top_level_assignments(path)
    if key in resolved:
        return str(resolved[key])
    return '?'

def _ops_final_assignment(path: Path, names: tuple[str, ...]) -> dict:  # type: ignore[override]
    resolved=_v2041_resolved_top_level_assignments(path)
    return {name: resolved.get(name) for name in names}

