def _v2044_runtime_owner_loop() -> None:
    while True:
        started=time.monotonic()
        try:
            snap=write_guard_runtime_snapshot_v1010('periodic_v2044_30s')
            _v2044_periodic_status(runtime_ok=True,runtime_last_ts=time.time(),runtime_sequence=snap.get('write_sequence_v1033'),runtime_error=None)
        except Exception as exc:
            _v2044_periodic_status(runtime_ok=False,runtime_error=f'{type(exc).__name__}: {exc}')
        time.sleep(max(3.0,30.0-(time.monotonic()-started)))


def _v2044_ops_owner_loop() -> None:
    # Give runtime snapshot the first write after boot.
    time.sleep(5.0)
    while True:
        started=time.monotonic()
        try:
            result=refresh_ops_map_snapshot('periodic_v2044_180s')
            _v2044_periodic_status(ops_ok=True,ops_last_ts=time.time(),ops_schema=(result or {}).get('schema') if isinstance(result,dict) else None,ops_error=None)
        except Exception as exc:
            _v2044_periodic_status(ops_ok=False,ops_error=f'{type(exc).__name__}: {exc}')
        time.sleep(max(10.0,180.0-(time.monotonic()-started)))


def _v2044_start_periodic_owners() -> None:
    global _V2044_PERIODIC_STARTED,_V2044_RUNTIME_THREAD,_V2044_OPS_THREAD
    if _V2044_PERIODIC_STARTED:return
    with _V2044_PERIODIC_START_LOCK:
        if _V2044_PERIODIC_STARTED:return
        _V2044_PERIODIC_STARTED=True
        _V2044_RUNTIME_THREAD=threading.Thread(target=_v2044_runtime_owner_loop,name='guard-runtime-owner-v2044',daemon=True)
        _V2044_OPS_THREAD=threading.Thread(target=_v2044_ops_owner_loop,name='guard-ops-owner-v2044',daemon=True)
        _V2044_RUNTIME_THREAD.start();_V2044_OPS_THREAD.start()
        _v2044_periodic_status(started=True,runtime_interval_sec=30,ops_interval_sec=180)


