def _v2047_is_protected(path: Path) -> bool:
    if _v2046_disk_protected(path): return True
    try: rel=path.relative_to(BOT_DIR).as_posix().lower()
    except Exception: rel=str(path).lower()
    if 'shadow' in rel: return True
    if any(x in rel for x in _V2047_CORE_HINTS) and not any(x in rel for x in ('cache','trace','debug','tmp','archive')):
        return True
    return False

def _v2047_tail_keep(path: Path, keep_bytes: int=16*1024*1024) -> tuple[bool,int,str]:
    """Keep only the newest tail of a non-core growing text/JSONL file."""
    try:
        old=int(path.stat().st_size)
        if old <= keep_bytes: return True,0,'below_cap'
        with path.open('rb') as f:
            f.seek(max(0,old-keep_bytes)); data=f.read()
        # Avoid starting in the middle of a JSONL/text line.
        cut=data.find(b'\n')
        if cut>=0 and cut+1<len(data): data=data[cut+1:]
        tmp=path.with_name('.'+path.name+'.v2047_tail.tmp')
        with tmp.open('wb') as w: w.write(data)
        os.replace(tmp,path)
        return True,max(0,old-len(data)),'tail_keep_16MB'
    except Exception as exc:
        try: tmp.unlink(missing_ok=True)
        except Exception: pass
        return False,0,f'{type(exc).__name__}: {exc}'

def _v2047_collect_bot_targets() -> tuple[list,list]:
    """Return delete targets and tail-truncate targets. No core/shadow path is included."""
    nowv=time.time(); delete=[]; truncate=[]; seen=set()
    def add(path: Path, reason: str):
        key=str(path)
        if key in seen or not path.exists() or _v2047_is_protected(path): return
        if path.name in _V2046_ALIAS_NAMES: return
        seen.add(key); delete.append((path,reason))
    # Deploy ZIPs: newest current + one rollback only.
    for pattern in ('coinbot_update_v*.zip','코인봇_최신전체코드_v*.zip','코인봇_최신전체코드_*.zip'):
        try: rows=sorted([x for x in BOT_DIR.glob(pattern) if x.is_file()],key=_v2046_version_key,reverse=True)
        except Exception: rows=[]
        for x in rows[2:]: add(x,'old deploy ZIP keep2')
    # Versioned sources: active alias + newest two rollback sources per family.
    for family,pattern in _V2046_SOURCE_PATTERNS.items():
        try: rows=sorted([x for x in BOT_DIR.glob(pattern) if x.is_file() and x.name not in _V2046_ALIAS_NAMES],key=_v2046_version_key,reverse=True)
        except Exception: rows=[]
        for x in rows[2:]: add(x,f'old {family} source keep2')
    # Batch summaries: newest three are enough for immediate diagnosis.
    try: rows=sorted([x for x in BOT_DIR.glob('coinbot_batch_summary_*.txt') if x.is_file()],key=lambda x:x.stat().st_mtime,reverse=True)
    except Exception: rows=[]
    for x in rows[3:]: add(x,'old batch summary keep3')
    # Deployment/temp directories are fully disposable.
    for base in (BOT_DIR,BOT_DIR/'runtime'):
        for pat in ('bundle_unpack_*','__pycache__','.pytest_cache','tmp','temp','.mypy_cache','.ruff_cache'):
            try:
                for x in base.glob(pat): add(x,'deploy/compiler/temp residue')
            except Exception: pass
    # Recursive non-core cleanup. Keep recent 6h diagnostics; remove old caches/traces/archives.
    try: iterator=BOT_DIR.rglob('*')
    except Exception: iterator=[]
    for x in iterator:
        try:
            if _v2047_is_protected(x): continue
            rel=x.relative_to(BOT_DIR).as_posix().lower(); age=nowv-x.stat().st_mtime; name=x.name.lower()
        except Exception: continue
        if x.is_dir():
            if age>6*3600 and any(h in rel for h in ('bundle_unpack','__pycache__','.pytest_cache')): add(x,'old disposable directory >6h')
            continue
        if not x.is_file(): continue
        if name.endswith(('.pyc','.pyo','.tmp','.part','.swp')): add(x,'compiler/temp file'); continue
        if any(h in rel for h in ('backup_guard_apply_','backup_guard_worker_apply_','.backup_')) or name.endswith(('.bak','.old')):
            if age>6*3600: add(x,'old deploy/backup >6h')
            continue
        noncore=any(h in rel for h in _V2047_NONCORE_HINTS)
        if noncore and age>6*3600 and (name.endswith(('.gz','.zip','.tar','.tgz','.log','.txt','.json','.jsonl')) or any(h in rel for h in ('archive','cache','trace','export','report'))):
            add(x,'old noncore cache/trace/archive/report >6h'); continue
        # Active non-core logs/traces can still consume GBs. Preserve newest 16MB.
        try: size=int(x.stat().st_size)
        except Exception: size=0
        if noncore and size>128*1024*1024 and name.endswith(('.log','.txt','.jsonl','.json')):
            truncate.append((x,'large active noncore tail keep16MB'))
    return delete,truncate

