_V2048_PREV_PROTECTED=_v2047_is_protected
def _v2047_is_protected(path: Path) -> bool:  # type: ignore[override]
    name=path.name.lower()
    if name.startswith('entry_truth_state_v2048.sqlite3') or name=='clean_entry_truth_storage_status_v2048.json' or name=='clean_candidate_storage_status_v2048.json':return True
    return _V2048_PREV_PROTECTED(path)


def _v2048_temp_pid(path: Path) -> int:
    name=path.name
    for pat in (r'entry_truth_state_v2034\.json\.tmp\.(\d+)\.',r'paper_candidates_latest\.jsonl\.tmp\.v1119\.(\d+)\.',r'\.paper_candidates_latest\.jsonl\.strategy\.(\d+)\.'):
        m=re.search(pat,name)
        if m:
            try:return int(m.group(1))
            except Exception:return 0
    return 0


def _v2048_pid_alive(pid: int) -> bool:
    try:return int(pid)>0 and Path(f'/proc/{int(pid)}').exists()
    except Exception:return False


_V2048_PREV_COLLECT=_v2047_collect_bot_targets
def _v2047_collect_bot_targets() -> tuple[list,list]:  # type: ignore[override]
    delete,truncate=_V2048_PREV_COLLECT();seen={str(x[0]) for x in delete};nowv=time.time()
    patterns=('entry_truth_state_v2034.json.tmp.*','paper_candidates_latest.jsonl.tmp.v1119.*','.paper_candidates_latest.jsonl.strategy.*.tmp')
    for pat in patterns:
        try:rows=list(BOT_DIR.glob(pat))
        except Exception:rows=[]
        for path in rows:
            try:
                if str(path) in seen or not path.is_file():continue
                age=max(0.0,nowv-path.stat().st_mtime);pid=_v2048_temp_pid(path)
                if age<120.0 or _v2048_pid_alive(pid):continue
                delete.append((path,f'dead stale large temp pid={pid} age={age:.0f}s'));seen.add(str(path))
            except Exception:continue
    return delete,truncate


