_V2111_BASE_MANIFEST_ALIASES=_v2000_manifest_aliases
_V2111_BASE_RELEASE_VERIFY=grelease_verify_text


def _read_last_release_manifest() -> dict:
    """Read the manifest sealed by the last completed bundle apply.

    /grelease_verify is a standalone command, so it cannot rely on the local
    variable that existed inside /gupgrade_bundle. The canonical source is the
    persisted upgrade status written at the end of bundle application.
    """
    try:
        status=read_json(BOT_DIR / UPGRADE_STATUS_FILE) or {}
        manifest=status.get('manifest') if isinstance(status,dict) else {}
        if isinstance(manifest,dict) and manifest:
            return manifest
    except Exception:
        pass
    return {}


def _v2000_manifest_aliases(manifest: dict) -> dict:  # type: ignore[override]
    out=_V2111_BASE_MANIFEST_ALIASES(manifest)
    workers=manifest.get('workers') if isinstance(manifest.get('workers'),dict) else {}
    fallback={'strategy_worker.py':manifest.get('strategy'),'review_worker.py':manifest.get('review')}
    for alias,src in fallback.items():
        if isinstance(src,str) and src and alias not in out: out[alias]=src
    return out


def grelease_verify_text(manifest: Optional[dict]=None) -> str:  # type: ignore[override]
    manifest=manifest if isinstance(manifest,dict) else (_read_last_release_manifest() or {})
    if isinstance(manifest,dict):
        workers=dict(manifest.get('workers') or {}) if isinstance(manifest.get('workers'),dict) else {}
        if not workers.get('strategy') and isinstance(manifest.get('strategy'),str): workers['strategy']=manifest.get('strategy')
        if not workers.get('review') and isinstance(manifest.get('review'),str): workers['review']=manifest.get('review')
        manifest=dict(manifest,workers=workers)
    text=_V2111_BASE_RELEASE_VERIFY(manifest)
    workers=manifest.get('workers') if isinstance(manifest,dict) and isinstance(manifest.get('workers'),dict) else {}
    return text+(f"\n- v2121 worker scope: strategy={workers.get('strategy') or '-'} / review={workers.get('review') or '-'} / top-level 누락 검수 우회 없음")

