VERSION='guard_v2.6.17';GUARD_VERSION=VERSION
BUILD_LABEL='v2131_paper_handoff_timestamp_age_fix_2026-07-21';MAIN_DEPLOY_VERSION=BUILD_LABEL;GUARD_BUILD_LABEL=BUILD_LABEL

def _v2130_file_obj(name: str) -> dict:
    try:
        obj=read_json(BOT_DIR/name)
        return obj if isinstance(obj,dict) else {}
    except Exception:return {}

def _v2130_file_age(obj: dict) -> float:
    """Return artifact age without treating a valid updated_at as Unix epoch zero.

    Writers in this project use updated_ts, updated_at, ts, and occasionally
    ISO-8601 text. Millisecond epochs are normalized. Missing/invalid evidence
    remains fail-closed instead of being reported as fresh.
    """
    if not isinstance(obj, dict):
        return 999999.0
    raw = None
    for key in ('updated_ts', 'updated_at', 'ts', 'heartbeat_ts', 'created_ts'):
        value = obj.get(key)
        if value not in (None, ''):
            raw = value
            break
    if raw in (None, ''):
        return 999999.0
    try:
        stamp = float(raw)
    except (TypeError, ValueError):
        try:
            from datetime import datetime
            stamp = datetime.fromisoformat(str(raw).strip().replace('Z', '+00:00')).timestamp()
        except Exception:
            return 999999.0
    if stamp > 100000000000.0:
        stamp /= 1000.0
    if stamp <= 0.0:
        return 999999.0
    return max(0.0, time.time() - stamp)

def _v2130_jsonl_rows(name: str, limit: int=3000) -> list[dict]:
    path=BOT_DIR/name
    try:lines=path.read_text(encoding='utf-8',errors='ignore').splitlines()[-limit:]
    except Exception:return []
    out=[]
    for line in lines:
        try:
            obj=json.loads(line)
            if isinstance(obj,dict):out.append(obj)
        except Exception:pass
    return out

def _v2130_runtime_service(service: str, expected_alias: str) -> tuple[bool,str]:
    try:
        data=_systemctl_show_map(service,timeout=5)
        active=str(data.get('ActiveState') or '')
        pid=int(str(data.get('MainPID') or '0') or '0')
        cmd=proc_cmdline(pid) if pid>0 and pid_alive(pid) else ''
        ok=active in {'active','activating'} and pid>0 and pid_alive(pid) and expected_alias in cmd
        return ok,f"service={service} active={active or '-'} MainPID={pid or '-'} cmd={cmd[:120] or '-'}"
    except Exception as exc:return False,f"service={service} error={type(exc).__name__}: {exc}"

def _v2130_source_identity(alias: str, expected_token: str) -> tuple[bool,str]:
    path=BOT_DIR/alias
    if not path.exists():return False,'file missing'
    try:text=path.read_text(encoding='utf-8',errors='ignore')
    except Exception as exc:return False,f'read {type(exc).__name__}'
    ok=expected_token in text
    return ok,(expected_token if ok else 'expected version token missing')

