def _v2144_count_lines(path: Path) -> int:
    count=0; last=b''
    with path.open('rb') as handle:
        while True:
            chunk=handle.read(1024*1024)
            if not chunk: break
            count += chunk.count(b'\n'); last=chunk[-1:]
    if path.stat().st_size>0 and last!=b'\n': count += 1
    return int(count)


def _v2144_cleanup_old_prediction_exports(max_age_sec: int=6*3600) -> list[str]:
    removed=[]; cutoff=time.time()-max_age_sec
    try:
        for path in BOT_DIR.glob(V2144_PREDICTION_EXPORT_TMP_PREFIX+'*'):
            try:
                if path.is_dir() and path.stat().st_mtime<cutoff:
                    shutil.rmtree(path); removed.append(path.name)
            except Exception: pass
    except Exception: pass
    return removed


def _v2144_snapshot_prediction_file(name: str, snapshot_dir: Path) -> dict:
    src=BOT_DIR/name
    row={'name':name,'source':str(src),'exists':False,'fixed_filename':True,'fallback_used':False,'original_modified_by_export':False}
    try: st0=src.lstat()
    except FileNotFoundError:
        row['status']='MISSING'; return row
    except Exception as exc:
        row.update(status='STAT_FAILED',error=f'{type(exc).__name__}: {exc}'); return row
    try:
        if src.is_symlink() or not src.is_file() or src.resolve().parent!=BOT_DIR.resolve():
            row.update(status='REJECTED_PATH_OR_TYPE',is_symlink=src.is_symlink()); return row
    except Exception as exc:
        row.update(status='REJECTED_PATH_OR_TYPE',error=f'{type(exc).__name__}: {exc}'); return row
    size0=int(st0.st_size); inode0=int(st0.st_ino); mtime0=int(st0.st_mtime_ns)
    row.update(exists=True,source_size_start=size0,source_inode_start=inode0,source_mtime_ns_start=mtime0,
               source_modified_time=datetime.fromtimestamp(st0.st_mtime).isoformat(timespec='seconds'))
    dst=snapshot_dir/name; copied=0
    try:
        with src.open('rb',buffering=0) as reader, dst.open('wb',buffering=0) as writer:
            remaining=size0
            while remaining>0:
                chunk=reader.read(min(1024*1024,remaining))
                if not chunk: break
                writer.write(chunk); copied+=len(chunk); remaining-=len(chunk)
            writer.flush(); os.fsync(writer.fileno())
        os.chmod(dst,0o600)
        trim=0; tail_state='NOT_JSONL'
        if name.endswith('.jsonl'):
            trim,tail_state=_trim_jsonl_snapshot_tail_v1129(dst)
        try:
            st1=src.lstat(); size1=int(st1.st_size); inode1=int(st1.st_ino); mtime1=int(st1.st_mtime_ns)
        except Exception:
            size1=-1; inode1=-1; mtime1=-1
        if copied<size0: status='SHORT_READ_FAIL'
        elif inode1!=inode0: status='SNAPSHOT_OLD_ATOMIC_GENERATION'
        elif size1>size0: status='PREFIX_SNAPSHOT_SOURCE_GREW'
        elif size1==size0 and mtime1==mtime0: status='STABLE_POINT_IN_TIME_COPY'
        else: status='POINT_IN_TIME_COPY_SOURCE_CHANGED'
        row.update(status=status,snapshot_path=str(dst),snapshot_size=int(dst.stat().st_size),copied_bytes=copied,
                   tail_trimmed_bytes=int(trim),tail_state=tail_state,line_count=_v2144_count_lines(dst),
                   sha256=_sha256_file_v1129(dst),source_size_end=size1,source_inode_end=inode1,
                   source_mtime_ns_end=mtime1,source_changed_during_copy=bool(inode1!=inode0 or size1!=size0 or mtime1!=mtime0))
    except Exception as exc:
        row.update(status='COPY_FAILED',error=f'{type(exc).__name__}: {exc}')
        try: dst.unlink(missing_ok=True)
        except Exception: pass
    return row


