def gprediction_export_text_v2144() -> str:
    started=time.time(); export_id=datetime.now().strftime('%Y%m%d_%H%M%S')
    lock_handle=None; root=None; zip_path=None; preserve=False
    result={'schema':'guard_prediction_export_result_v2144','version':'v2144','guard_version':VERSION,'export_id':export_id,
            'command':'/gprediction_export','fixed_files':list(V2144_PREDICTION_EXPORT_FILES),'status':'CHECK',
            'fallback_used':False,'original_files_modified':False,'auto_buy_changed':False,'started_ts':started,'started_time':now()}
    try:
        lock_handle=(BOT_DIR/V2144_PREDICTION_EXPORT_LOCK).open('a+')
        try: fcntl.flock(lock_handle.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError: return '📦 상승예측 원본 ZIP 생성 중\n- 앞선 export가 끝난 뒤 다시 실행해줘.'
        _v2144_cleanup_old_prediction_exports()
        missing=[]; invalid=[]; total=0
        for name in V2144_PREDICTION_EXPORT_FILES:
            path=BOT_DIR/name
            try:
                if not path.exists(): missing.append(name)
                elif path.is_symlink() or not path.is_file() or path.resolve().parent!=BOT_DIR.resolve(): invalid.append(name)
                else: total += int(path.stat().st_size)
            except Exception: invalid.append(name)
        if missing or invalid:
            detail=[]
            if missing: detail.append('누락 '+', '.join(missing))
            if invalid: detail.append('경로/형식오류 '+', '.join(invalid))
            raise RuntimeError(' / '.join(detail))
        free=int(shutil.disk_usage(BOT_DIR).free); required=total*2+64*1024*1024
        result.update(total_source_bytes=total,disk_free_before=free,required_free=required)
        if free<required: raise RuntimeError(f'임시공간 부족 free={free} required={required}')
        root=Path(tempfile.mkdtemp(prefix=V2144_PREDICTION_EXPORT_TMP_PREFIX,dir=str(BOT_DIR))); os.chmod(root,0o700)
        snapshot=root/'snapshot'; snapshot.mkdir(mode=0o700)
        progress_notify('📦 상승예측 원본 ZIP 생성 시작\n- 기존 원본 3개만 읽기 전용 복사\n- 누락 시 FAIL · fallback/cache 사용 없음')
        rows=[_v2144_snapshot_prediction_file(name,snapshot) for name in V2144_PREDICTION_EXPORT_FILES]
        bad=[r for r in rows if not r.get('snapshot_path') or r.get('status') in {'MISSING','STAT_FAILED','REJECTED_PATH_OR_TYPE','SHORT_READ_FAIL','COPY_FAILED'}]
        if bad:
            raise RuntimeError('snapshot 실패: '+', '.join(f"{r.get('name')}={r.get('status')}" for r in bad))
        manifest_rows=[]
        for row in rows:
            manifest_rows.append({k:v for k,v in row.items() if k!='snapshot_path'})
        manifest={'schema':'coinbot_prediction_raw_export_v2144','export_id':export_id,'generated_ts':time.time(),'generated_time':now(),
                  'guard_version':VERSION,'command':'/gprediction_export','files':manifest_rows,'fixed_filename_only':True,
                  'fallback_or_cache_used':False,'history_recalculated':False,'original_files_modified':False,'auto_buy':False,
                  'archive_contract':'single Android-compatible ZIP_DEFLATED method 8; CRC checked before send'}
        digest=hashlib.sha256(json.dumps(manifest,ensure_ascii=False,sort_keys=True).encode('utf-8')).hexdigest(); manifest['manifest_sha256']=digest
        zip_path=root/f'coinbot_prediction_raw_{export_id}.zip'
        readme=('Coinbot prediction raw export v2144\n'
                '- Fixed existing files only; no fallback/cache substitution.\n'
                '- Read-only point-in-time copies; originals and history were not rewritten.\n'
                '- EXPORT_MANIFEST.json contains size, modified time, line count and SHA256.\n')
        with zipfile.ZipFile(zip_path,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=9,allowZip64=True) as archive:
            archive.writestr('EXPORT_MANIFEST.json',json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
            archive.writestr('README_EXPORT.txt',readme)
            for row in rows: archive.write(Path(str(row['snapshot_path'])),arcname=str(row['name']))
        os.chmod(zip_path,0o600)
        with zipfile.ZipFile(zip_path,'r') as check:
            infos=check.infolist(); methods=sorted({int(x.compress_type) for x in infos}); encrypted=any(bool(x.flag_bits&0x1) for x in infos); bad_crc=check.testzip()
        if methods and any(x not in (zipfile.ZIP_STORED,zipfile.ZIP_DEFLATED) for x in methods): raise RuntimeError(f'지원하지 않는 ZIP method {methods}')
        if encrypted: raise RuntimeError('암호화 ZIP 생성 오류')
        if bad_crc: raise RuntimeError(f'ZIP CRC 오류 {bad_crc}')
        zip_size=int(zip_path.stat().st_size)
        if zip_size>V2144_PREDICTION_EXPORT_MAX_BYTES:
            preserve=True; raise RuntimeError(f'Telegram 첨부한도 초과 {zip_size}>{V2144_PREDICTION_EXPORT_MAX_BYTES}')
        ok,detail=telegram_send_document_v1129(ALLOWED_CHAT_ID,zip_path,caption=f'코인봇 상승예측 원본 3파일\nexport {export_id}\nmanifest {digest[:12]}')
        if not ok:
            preserve=True; result['retained_temp_path']=str(zip_path); raise RuntimeError(f'Telegram 전송 실패: {detail}')
        result.update(status='DONE',files=manifest_rows,manifest_sha256=digest,zip_name=zip_path.name,zip_size=zip_size,
                      zip_sha256=_sha256_file_v1129(zip_path),zip_methods=methods,crc_pass=True,sent=True,completed_ts=time.time(),completed_time=now())
        proof=hashlib.sha256(f'{digest}:{result["zip_sha256"]}:DONE'.encode()).hexdigest()[:16]
        _v2144_append_prediction_export_ledger('DONE',export_id,'고정 원본 3/3 snapshot·manifest·CRC·Telegram 전송 PASS. 원본 변경 0.','없음',proof)
        file_lines=[]
        for row in rows:
            file_lines.append(f"- {row['name']} · {row['snapshot_size']/1024:.1f}KB · {row['line_count']}줄 · {row['source_modified_time']} · sha {row['sha256'][:12]}")
        return '\n'.join(['📦 상승예측 원본 ZIP export DONE','- 파일 3/3 · ZIP 전송 1/1 · fallback/cache 0',
                          f'- ZIP {zip_size/1024/1024:.2f}MB · DEFLATE(method 8) · CRC PASS',*file_lines,
                          f'- manifest {digest[:16]}','- 원본 변경 0 · 임시파일 정리 완료 · 자동매수 OFF'])
    except Exception as exc:
        error=f'{type(exc).__name__}: {exc}'; result.update(status='FAIL',error=error,completed_ts=time.time(),completed_time=now())
        proof=hashlib.sha256(error.encode()).hexdigest()[:16]
        _v2144_append_prediction_export_ledger('FAIL',export_id,f'상승예측 원본 export 실패: {error}','누락·경로·복사·용량·Telegram 전송 원인만 수리 후 재실행.',proof)
        keep=f'\n- 전송 실패 ZIP 유지: {zip_path}' if preserve and zip_path is not None else ''
        return '📦 ❌ 상승예측 원본 ZIP export FAIL\n'+f'- {error}\n- fallback/cache 사용 0 · 원본 변경 0 · 자동매수 OFF'+keep
    finally:
        result['duration_sec']=round(time.time()-started,3)
        try: write_json(BOT_DIR/V2144_PREDICTION_EXPORT_LAST,result)
        except Exception: pass
        if root is not None and not preserve:
            try: shutil.rmtree(root)
            except Exception: pass
        if lock_handle is not None:
            try: fcntl.flock(lock_handle.fileno(),fcntl.LOCK_UN)
            except Exception: pass
            try: lock_handle.close()
            except Exception: pass


_V2144_BASE_HANDLE_SINGLE=handle_single_command
def handle_single_command(text: str,post_commands=None) -> str:  # type: ignore[override]
    raw=str(text or '').strip(); parts=raw.split(); cmd=parts[0].lower() if parts else ''
    if '@' in cmd: cmd=cmd.split('@',1)[0]
    if cmd in ('/gprediction_export','/gprediction_raw','/gpred_export'):
        return gprediction_export_text_v2144()
    return _V2144_BASE_HANDLE_SINGLE(text,post_commands=post_commands)


