def _v2167_candidate_runtime_counts(expected_model:str,expected_core:str)->dict:
    counts=Counter();cores=Counter();rows=0
    path=BOT_DIR/'paper_candidates_latest.jsonl'
    try:
        data=path.read_text(encoding='utf-8',errors='ignore').splitlines()[-700:]
    except Exception:data=[]
    for line in data:
        try:row=json.loads(line)
        except Exception:continue
        if not isinstance(row,dict):continue
        if str(row.get('strategy_generation_v2149') or '')!='ALT_SWING_V2_COMBINED_V2149_RESET_20260722':continue
        c=row.get('trade_path_contract_v2149') if isinstance(row.get('trade_path_contract_v2149'),dict) else {}
        m=str(c.get('prediction_model_generation') or ((c.get('prediction') or {}).get('prediction_model_generation') if isinstance(c.get('prediction'),dict) else '') or '')
        rid=c.get('runtime_identity_v2168') if isinstance(c.get('runtime_identity_v2168'),dict) else {}
        cv=str(rid.get('core_version') or c.get('version') or '')
        if m:counts[m]+=1
        if cv:cores[cv]+=1
        rows+=1
    return {'rows':rows,'models':dict(counts),'cores':dict(cores),'model_exact':bool(rows and set(counts)=={expected_model}),'core_exact':bool(rows and set(cores)=={expected_core})}


def _v2167_exact_release_verify(manifest:dict)->tuple[bool,list[str]]:
    workers=manifest.get('workers') if isinstance(manifest.get('workers'),dict) else {}
    strategy_name=str(workers.get('strategy') or '')
    core_name=next((str(x) for x in (manifest.get('support_files') or []) if str(x).startswith('strategy_v2_core_v2168') and str(x).endswith('.py')),'')
    expected_model=str(manifest.get('prediction_model_generation') or 'FULL_INPUT_V2168')
