# A reboot can leave an O_EXCL apply lock whose PID no longer exists.  Previous
# guards deleted it only after reporting CHECK, requiring another manual apply.
# Reclaim one proven-stale lock immediately and continue the same request once.
_V2178_BASE_CLAIM_RELEASE_APPLY=_claim_release_apply
def _claim_release_apply(req):  # type: ignore[override]
    claimed,lock,state=_V2178_BASE_CLAIM_RELEASE_APPLY(req)
    if claimed or state!='stale':
        return claimed,lock,state
    try:
        _release_apply_lock_path().unlink(missing_ok=True)
    except Exception:
        return claimed,lock,state
    claimed2,lock2,state2=_V2178_BASE_CLAIM_RELEASE_APPLY(req)
    return claimed2,lock2,('reclaimed_stale' if claimed2 else state2)


def _v2178_cleanup_stale_deploy_temp(base=BOT_DIR, min_age_sec=1800.0):
    removed=[]
    now_ts=time.time()
    for pattern in ('.bundle_unpack_*','.bundle_continue_once_*'):
        for path in base.glob(pattern):
            try:
                age=now_ts-path.stat().st_mtime
                if age < min_age_sec:
                    continue
                if path.is_dir(): shutil.rmtree(path,ignore_errors=True)
                else: path.unlink(missing_ok=True)
                removed.append(path.name)
            except Exception:
                pass
    lock=_release_apply_lock_path()
    if lock.exists():
        obj=_read_release_apply_lock()
        try: pid=int(obj.get('pid') or 0)
        except Exception: pid=0
        if not pid or not pid_alive(pid):
            try: lock.unlink(missing_ok=True);removed.append(lock.name)
            except Exception: pass
    return removed

_V2178_BASE_GUPGRADE_BUNDLE_TEXT=gupgrade_bundle_text
def gupgrade_bundle_text(force: bool=False, explicit=None, skip_git: bool=False, post_commands=None):  # type: ignore[override]
    _v2178_cleanup_stale_deploy_temp(BOT_DIR)
    return _V2178_BASE_GUPGRADE_BUNDLE_TEXT(force=force,explicit=explicit,skip_git=skip_git,post_commands=post_commands)

