def _v2178_source_identity(base=BOT_DIR):
    missing=[];mismatch=[];compile_fail=[]
    for alias,source in V2178_ALIAS_TARGETS.items():
        a=base/alias;s=base/source
        if not a.exists() or not s.exists():
            missing.append(f'{alias}->{source}')
        elif sha256_file(a)!=sha256_file(s):
            mismatch.append(f'{alias}->{source}')
    for name in V2178_SOURCE_KEEP:
        path=base/name
        if not path.exists():
            missing.append(name);continue
        if name.endswith('.py'):
            okc,out=py_compile(path)
            if not okc: compile_fail.append(f'{name}:{tail(out,160)}')
    markers={
        '.deployed_target':'coinbot_main_v2_13_2152.py',
        DEPLOYED_PAPER_FILE:'paper_bot_v2.102.py',
        DEPLOYED_GUARD_FILE:'backga_guard_bot_v2_6_38.py',
        DEPLOYED_MICRO_FILE:'bithumb_micro_sidecar_v2.003.py',
        DEPLOYED_WS_FILE:'ws_sidecar_v2.000.py',
    }
    marker_bad=[]
    for marker,expected in markers.items():
        actual=(read_file(base/marker) or '').strip()
        if actual!=expected: marker_bad.append(f'{marker}:{actual or "-"}->{expected}')
    return {'ok':not(missing or mismatch or compile_fail or marker_bad),'missing':missing,'mismatch':mismatch,'compile_fail':compile_fail,'marker_bad':marker_bad}


