# v2179 true guard-first deployment: no extractall, no pre-copy of all files.
# Existing /gupgrade_bundle only. No new command, board, shadow or strategy change.
# =============================================================================
VERSION='guard_v2.6.39_true_guard_first_no_extractall_2026-07-23';GUARD_VERSION=VERSION
BUILD_LABEL='v2179_true_guard_first_no_extractall_2026-07-23';GUARD_BUILD_LABEL=BUILD_LABEL;MAIN_DEPLOY_VERSION=BUILD_LABEL

V2179_MAX_FILES=64
V2179_MAX_MEMBER_BYTES=24*1024*1024
V2179_MAX_TOTAL_BYTES=128*1024*1024


def _v2179_safe_zip_index(bundle):
    with zipfile.ZipFile(bundle,'r') as z:
        infos=z.infolist()
        if len(infos)>V2179_MAX_FILES:
            raise RuntimeError(f'too many bundle files: {len(infos)}')
        total=0;names={}
        for info in infos:
            rel=Path(info.filename)
            if rel.is_absolute() or '..' in rel.parts or info.is_dir():
                if info.is_dir():
                    continue
                raise RuntimeError(f'unsafe bundle path: {info.filename}')
            if info.file_size<0 or info.file_size>V2179_MAX_MEMBER_BYTES:
                raise RuntimeError(f'bundle member too large: {info.filename}:{info.file_size}')
            total+=int(info.file_size or 0)
            if total>V2179_MAX_TOTAL_BYTES:
                raise RuntimeError(f'bundle total too large: {total}')
            names[info.filename]=info
        if 'DEPLOY_BUNDLE.json' not in names:
            raise RuntimeError('DEPLOY_BUNDLE.json missing')
        raw=z.read('DEPLOY_BUNDLE.json')
        manifest=json.loads(raw.decode('utf-8'))
        if not isinstance(manifest,dict):
            raise RuntimeError('DEPLOY_BUNDLE.json invalid')
        return manifest,names


def _v2179_declared_files(manifest):
    names=[]
    for key in ('main','paper','guard','ws','micro','ws_sidecar','micro_sidecar'):
        value=manifest.get(key)
        if isinstance(value,str) and value.strip(): names.append(value.strip())
    workers=manifest.get('workers') if isinstance(manifest.get('workers'),dict) else {}
    for value in workers.values():
        if isinstance(value,str) and value.strip(): names.append(value.strip())
    support=manifest.get('support_files') if isinstance(manifest.get('support_files'),list) else []
    for value in support:
        if isinstance(value,str) and value.strip(): names.append(value.strip())
    return sorted(set(names))


def _v2179_read_member(bundle,name):
    rel=Path(str(name or ''))
    if not name or rel.is_absolute() or '..' in rel.parts:
        raise RuntimeError(f'unsafe member: {name}')
    with zipfile.ZipFile(bundle,'r') as z:
        info=z.getinfo(str(name))
        if info.file_size>V2179_MAX_MEMBER_BYTES:
            raise RuntimeError(f'member too large: {name}')
        return z.read(str(name))


def _v2179_atomic_write_bytes(target,data):
    target=Path(target);target.parent.mkdir(parents=True,exist_ok=True)
    tmp=target.with_name(f'.{target.name}.v2179tmp.{os.getpid()}.{time.time_ns()}')
    try:
        with tmp.open('wb') as f:
            view=memoryview(data)
            for pos in range(0,len(view),1024*1024):
                f.write(view[pos:pos+1024*1024])
            f.flush()
        os.replace(tmp,target)
    finally:
        try: tmp.unlink(missing_ok=True)
        except Exception: pass


def _v2179_stage_declared(bundle,manifest):
    _,index=_v2179_safe_zip_index(bundle)
    declared=_v2179_declared_files(manifest)
    missing=[name for name in declared if name not in index]
    if missing:
        raise RuntimeError('bundle missing declared: '+','.join(missing[:8]))
    staged=[]
    for name in declared:
        data=_v2179_read_member(bundle,name)
        if name.endswith('.py'):
            try: compile(data.decode('utf-8'),name,'exec')
            except UnicodeDecodeError: compile(data.decode('utf-8-sig'),name,'exec')
        _v2179_atomic_write_bytes(BOT_DIR/name,data)
        staged.append(name)
        progress_notify(f'[2/5] 정본 파일 준비\n- {name} ({len(data)}B)')
    main=manifest.get('main')
    if main:
        _v2179_atomic_write_bytes(BOT_DIR/'DEPLOY_TARGET.txt',(str(main).strip()+'\n').encode('utf-8'))
    return staged


def _v2179_apply_components(req,manifest,bundle):
    full_identity_force=bool(manifest.get('force_full_identity_apply') or manifest.get('force_service_restart'))
    staged=_v2179_stage_declared(bundle,manifest)
    progress_notify(f'[3/5] 정본 준비 완료\n- {len(staged)}개 파일 원자교체\n- 전체 extractall 사용 안 함')
    results=[]
    workers=manifest.get('workers') if isinstance(manifest.get('workers'),dict) else {}
    progress_notify('[4/5] 컴포넌트 적용 중\n- 정본 경로만 연결·재시작')
    for name,fname in workers.items():
        if name not in WORKER_SPECS or not fname: continue
        raw=apply_worker_latest(name,force=bool(req.get('force') or full_identity_force),explicit=fname,restart=True)
        rendered=format_worker_apply_result(raw);results.append(f'worker:{name}\n{tail(rendered,1000)}')
        if isinstance(raw,dict) and not bool(raw.get('ok',True)):
            return False,'\n\n'.join(results)
    if manifest.get('main'):
        rendered=apply_main_latest_auto(force=bool(req.get('force') or full_identity_force),explicit=str(manifest.get('main')),skip_git=True)
        results.append(f'main\n{tail(rendered,1200)}')
        if str(rendered).startswith(('❌','🚀 ❌')): return False,'\n\n'.join(results)
    if manifest.get('paper'):
        raw=apply_paper_latest(force=bool(req.get('force') or full_identity_force),explicit=str(manifest.get('paper')))
        rendered=format_paper_apply_result(raw);results.append(f'paper\n{tail(rendered,1200)}')
        if isinstance(raw,dict) and not bool(raw.get('ok',True)): return False,'\n\n'.join(results)
    ws_manifest=manifest.get('ws') or manifest.get('ws_sidecar')
    if ws_manifest:
        raw=apply_ws_sidecar_latest(force=bool(req.get('force') or full_identity_force),explicit=str(ws_manifest),restart=True)
        rendered=format_ws_apply_result(raw);results.append(f'ws\n{tail(rendered,900)}')
        if isinstance(raw,dict) and not bool(raw.get('ok',True)): return False,'\n\n'.join(results)
    micro_manifest=manifest.get('micro') or manifest.get('micro_sidecar')
    if micro_manifest:
        raw=apply_micro_sidecar_latest(force=bool(req.get('force') or full_identity_force),explicit=str(micro_manifest),restart=True)
        rendered=format_micro_apply_result(raw);results.append(f'micro\n{tail(rendered,900)}')
        if isinstance(raw,dict) and not bool(raw.get('ok',True)): return False,'\n\n'.join(results)
    verify=grelease_verify_text(manifest);verify_ok=str(verify).startswith('✅')
    progress_notify(f"[5/5] 최종 검수 {'PASS' if verify_ok else 'CHECK'}")
    body='\n'.join([
        f"{'✅' if verify_ok else '⚠️'} bundle 최종결과 {'PASS' if verify_ok else 'CHECK'}",
        f'- bundle: {bundle.name}',
        '- 방식: guard 파일 우선·선택파일 원자교체·extractall 없음',
        verify,
    ])
    if results: body+='\n\n[적용]\n'+'\n\n'.join(results)
    return verify_ok,body


_V2179_PREV_APPLY_RELEASE_BUNDLE_ONCE=_apply_release_bundle_once

def _apply_release_bundle_once(req):  # type: ignore[override]
    bundle=_release_bundle_path(str(req.get('explicit') or ''))
    if not bundle: return False,f"bundle missing: {req.get('explicit') or '-'}"
    expected=str(req.get('bundle_digest') or '')
    actual=sha256_file(bundle)
    if expected and expected!=actual: return False,f'bundle digest mismatch {expected[:12]}->{actual[:12]}'
    try:
        manifest,_=_v2179_safe_zip_index(bundle)
        if str(manifest.get('version') or '')!='v2179':
            return _V2179_PREV_APPLY_RELEASE_BUNDLE_ONCE(req)
        ok,body=_v2179_apply_components(req,manifest,bundle)
        if not ok: return ok,body
        ident=_v2179_source_identity(BOT_DIR)
        if not ident['ok']:
            detail=[]
            for key in ('missing','mismatch','compile_fail','marker_bad'):
                if ident[key]: detail.append(f'{key}='+','.join(ident[key][:8]))
            return False,body+'\n- 실행경로 단일화 CHECK: '+' / '.join(detail)
        cleanup=_v2179_remove_obsolete_sources(BOT_DIR)
        if cleanup['errors'] or cleanup['remaining']:
            return False,body+f"\n- 구 source 삭제 CHECK: 삭제 {len(cleanup['removed'])} · 남음 {len(cleanup['remaining'])} · 오류 {len(cleanup['errors'])}"
        return True,body+f"\n- 정본·alias·marker 단일화 PASS · 구 versioned source 삭제 {len(cleanup['removed'])}개 · 보호원장 삭제 0"
    except Exception as exc:
        return False,f'v2179 bundle apply exception: {exc.__class__.__name__}: {exc}\n{tail(traceback.format_exc(),3000)}'


def gupgrade_bundle_text(force: bool=False,explicit=None,skip_git: bool=False,post_commands=None):  # type: ignore[override]
    active_job=_load_release_job()
    if active_job:
        return '\n'.join(['📦 ⚠️ 자동 이어가기 1건 처리 중',f"- request: {active_job.get('request_id') or '-'}",f"- bundle: {active_job.get('explicit') or '-'}",'- 중복 실행하지 않음'])
    progress_notify('📦 bundle 처리 시작\n- guard 우선·선택파일만 처리\n- extractall 사용 안 함')
    if not skip_git:
        progress_notify('[1/5] GitHub 최신 zip 확인 중')
        ok_dl,steps=_github_direct_download_latest_bundle(explicit=explicit)
        if not ok_dl:
            return '📦 ❌ bundle 업그레이드 실패\n- GitHub 최신 zip 직접 확인 실패\n'+'\n'.join(steps[-10:])
    else:
        progress_notify('[1/5] 서버 로컬 zip 사용')
    bundle=find_latest_bundle_file(explicit)
    if not bundle: return '📦 ❌ bundle 업그레이드 실패\n- coinbot_update_v*.zip 파일 없음'
    progress_notify(f'[2/5] bundle 발견\n- {bundle.name}\n- manifest와 guard만 먼저 확인')
    try:
        manifest,_=_v2179_safe_zip_index(bundle)
        if str(manifest.get('version') or '')!='v2179':
            return _V2178_BASE_GUPGRADE_BUNDLE_TEXT(force=force,explicit=explicit,skip_git=True,post_commands=post_commands)
        guard_name=str(manifest.get('guard') or '').strip()
        if guard_name:
            guard_data=_v2179_read_member(bundle,guard_name)
            try: compile(guard_data.decode('utf-8'),guard_name,'exec')
            except UnicodeDecodeError: compile(guard_data.decode('utf-8-sig'),guard_name,'exec')
            _v2179_atomic_write_bytes(BOT_DIR/guard_name,guard_data)
            deployed=(read_file(BOT_DIR/DEPLOYED_GUARD_FILE) or '').strip()
            if deployed!=guard_name or str(VERSION)!=str(extract_assignment(BOT_DIR/guard_name,'VERSION') or VERSION):
                progress_notify('[3/5] guard 파일만 우선 적용\n- 다른 파일은 아직 건드리지 않음')
                guard_res=format_guard_apply_result(apply_guard_first_for_smart_upgrade(force=force,continuation_bundle=bundle.name,post_commands=post_commands))
                return '\n'.join(['📦 ✅ 가드봇 우선 적용 완료',f'- guard: {guard_name}',f'- bundle: {bundle.name}','- 새 가드가 동일 bundle 나머지를 1회만 이어서 적용','',guard_res])
        req={'action':'continue_gupgrade','request_id':f'manual-{time.time_ns()}','explicit':bundle.name,'bundle_digest':sha256_file(bundle),'force':force,'post_commands':post_commands or []}
        ok,body=_apply_release_bundle_once(req)
        return body
    except Exception as exc:
        return f'📦 ❌ v2179 bundle 검수/준비 실패\n- {exc.__class__.__name__}: {exc}\n{tail(traceback.format_exc(),2500)}'


