def _v2179_source_identity(base=BOT_DIR):
    missing=[];mismatch=[];compile_fail=[]
    for alias,source in V2179_ALIAS_TARGETS.items():
        a=base/alias;s=base/source
        if not a.exists() or not s.exists(): missing.append(f'{alias}->{source}')
        elif sha256_file(a)!=sha256_file(s): mismatch.append(f'{alias}->{source}')
    for name in V2179_SOURCE_KEEP:
        path=base/name
        if not path.exists(): missing.append(name);continue
        if name.endswith('.py'):
            try: compile(path.read_text(encoding='utf-8'),name,'exec')
            except Exception as exc: compile_fail.append(f'{name}:{type(exc).__name__}')
    markers={'.deployed_target':'coinbot_main_v2_13_2152.py',DEPLOYED_PAPER_FILE:'paper_bot_v2.102.py',DEPLOYED_GUARD_FILE:'backga_guard_bot_v2_6_39.py',DEPLOYED_MICRO_FILE:'bithumb_micro_sidecar_v2.003.py',DEPLOYED_WS_FILE:'ws_sidecar_v2.000.py'}
    marker_bad=[]
    for marker,expected in markers.items():
        actual=(read_file(base/marker) or '').strip()
        if actual!=expected: marker_bad.append(f'{marker}:{actual or "-"}->{expected}')
    return {'ok':not(missing or mismatch or compile_fail or marker_bad),'missing':missing,'mismatch':mismatch,'compile_fail':compile_fail,'marker_bad':marker_bad}


def _v2179_remove_obsolete_sources(base=BOT_DIR):
    removed=[];errors=[];seen=set()
    for pattern in V2178_SOURCE_PATTERNS:
        for path in base.glob(pattern):
            try: resolved=path.resolve()
            except Exception: resolved=path
            if resolved in seen or not path.is_file() or path.name in V2179_SOURCE_KEEP: continue
            seen.add(resolved)
            try: size=path.stat().st_size;path.unlink();removed.append((path.name,size))
            except Exception as exc: errors.append(f'{path.name}:{type(exc).__name__}')
    try:
        for pyc in base.glob('*.pyc'): pyc.unlink(missing_ok=True)
        cache=base/'__pycache__'
        if cache.exists(): shutil.rmtree(cache,ignore_errors=True)
    except Exception as exc: errors.append(f'bytecode:{type(exc).__name__}')
    remaining=[]
    for pattern in V2178_SOURCE_PATTERNS:
        for path in base.glob(pattern):
            if path.is_file() and path.name not in V2179_SOURCE_KEEP: remaining.append(path.name)
    return {'removed':removed,'errors':errors,'remaining':sorted(set(remaining))}


# v2181: main entry moved to the physical end of file so all release overrides load first.

# =============================================================================
# v2180 quiet bundle deployment + existing runtime-path single-source closeout.
# - /gupgrade_bundle: one receipt + one final result only.
# - no per-file/stage Telegram progress messages.
# - retain v2179 guard-first, selective atomic writes and obsolete-source cleanup.
# - no strategy/candidate/entry/exit/ledger changes. Auto-buy remains OFF.
# =============================================================================
VERSION='guard_v2.6.40_quiet_bundle_single_final_2026-07-23';GUARD_VERSION=VERSION
BUILD_LABEL='v2180_quiet_bundle_single_final_runtime_path_closeout_2026-07-23';GUARD_BUILD_LABEL=BUILD_LABEL;MAIN_DEPLOY_VERSION=BUILD_LABEL

_V2180_BASE_PROGRESS_NOTIFY=progress_notify
_V2180_BUNDLE_QUIET_DEPTH=0


def progress_notify(text):  # type: ignore[override]
    """Suppress only bundle-internal progress chatter; other commands keep legacy behavior."""
    if int(globals().get('_V2180_BUNDLE_QUIET_DEPTH',0) or 0)>0:
        return None
    return _V2180_BASE_PROGRESS_NOTIFY(text)


class _V2180QuietBundle:
    def __enter__(self):
        global _V2180_BUNDLE_QUIET_DEPTH
        _V2180_BUNDLE_QUIET_DEPTH=int(_V2180_BUNDLE_QUIET_DEPTH or 0)+1
        return self
    def __exit__(self,exc_type,exc,tb):
        global _V2180_BUNDLE_QUIET_DEPTH
        _V2180_BUNDLE_QUIET_DEPTH=max(0,int(_V2180_BUNDLE_QUIET_DEPTH or 0)-1)
        return False


def _v2180_manifest_is_current(manifest):
    if not isinstance(manifest,dict):
        return False
    return bool(
        str(manifest.get('bundle_version') or '')=='v2180'
        or str(manifest.get('schema') or '')=='coinbot_deploy_bundle_v2180'
        or str(manifest.get('version') or '')=='v2180'
    )


def _v2180_stage_declared(bundle,manifest):
    _,index=_v2179_safe_zip_index(bundle)
    declared=_v2179_declared_files(manifest)
    missing=[name for name in declared if name not in index]
    if missing:
        raise RuntimeError('bundle missing declared: '+','.join(missing[:8]))
    staged=[]
    for name in declared:
        data=_v2179_read_member(bundle,name)
        if name.endswith('.py'):
            try: compile(data.decode('utf-8'),name,'exec')
            except UnicodeDecodeError: compile(data.decode('utf-8-sig'),name,'exec')
        _v2179_atomic_write_bytes(BOT_DIR/name,data)
        staged.append(name)
    main=manifest.get('main')
    if main:
        _v2179_atomic_write_bytes(BOT_DIR/'DEPLOY_TARGET.txt',(str(main).strip()+'\n').encode('utf-8'))
    return staged


def _v2180_result_ok(raw,rendered=''):
    if isinstance(raw,dict):
        return bool(raw.get('ok',True))
    value=str(rendered or raw or '')
    return not value.startswith(('❌','🚀 ❌')) and '업그레이드 예외' not in value and '적용 실패' not in value


def _v2180_apply_components(req,manifest,bundle):
    full_identity_force=bool(manifest.get('force_full_identity_apply') or manifest.get('force_service_restart'))
    results=[];status_rows=[]
    with _V2180QuietBundle():
        staged=_v2180_stage_declared(bundle,manifest)
        workers=manifest.get('workers') if isinstance(manifest.get('workers'),dict) else {}
        for name,fname in workers.items():
            if name not in WORKER_SPECS or not fname:
                continue
            raw=apply_worker_latest(name,force=bool(req.get('force') or full_identity_force),explicit=fname,restart=True)
            rendered=format_worker_apply_result(raw)
            ok=_v2180_result_ok(raw,rendered)
            status_rows.append(f"{name}={'PASS' if ok else 'FAIL'}")
            if not ok:
                results.append(f'worker:{name}\n{tail(rendered,1800)}')
                return False,'\n\n'.join(results),status_rows,staged
        if manifest.get('main'):
            rendered=apply_main_latest_auto(force=bool(req.get('force') or full_identity_force),explicit=str(manifest.get('main')),skip_git=True)
            ok=_v2180_result_ok(rendered,rendered);status_rows.append(f"main={'PASS' if ok else 'FAIL'}")
            if not ok: return False,'main\n'+tail(rendered,2200),status_rows,staged
        if manifest.get('paper'):
            raw=apply_paper_latest(force=bool(req.get('force') or full_identity_force),explicit=str(manifest.get('paper')))
            rendered=format_paper_apply_result(raw);ok=_v2180_result_ok(raw,rendered);status_rows.append(f"paper={'PASS' if ok else 'FAIL'}")
            if not ok: return False,'paper\n'+tail(rendered,2200),status_rows,staged
        ws_manifest=manifest.get('ws') or manifest.get('ws_sidecar')
        if ws_manifest:
            raw=apply_ws_sidecar_latest(force=bool(req.get('force') or full_identity_force),explicit=str(ws_manifest),restart=True)
            rendered=format_ws_apply_result(raw);ok=_v2180_result_ok(raw,rendered);status_rows.append(f"ws={'PASS' if ok else 'FAIL'}")
            if not ok: return False,'ws\n'+tail(rendered,1800),status_rows,staged
        micro_manifest=manifest.get('micro') or manifest.get('micro_sidecar')
        if micro_manifest:
            raw=apply_micro_sidecar_latest(force=bool(req.get('force') or full_identity_force),explicit=str(micro_manifest),restart=True)
            rendered=format_micro_apply_result(raw);ok=_v2180_result_ok(raw,rendered);status_rows.append(f"micro={'PASS' if ok else 'FAIL'}")
            if not ok: return False,'micro\n'+tail(rendered,1800),status_rows,staged
        verify=grelease_verify_text(manifest)
    verify_ok=str(verify).startswith('✅')
    if not verify_ok:
        return False,'최종 검수 CHECK\n'+tail(verify,3500),status_rows,staged
    return True,'',status_rows,staged


