def format_worker_apply_result(res: dict) -> str:  # type: ignore[override]
    ok='✅' if res.get('ok') else '❌'
    mode='교체+재시작' if res.get('changed') and res.get('restarted') else ('교체' if res.get('changed') else ('재시작' if res.get('restarted') else '변경없음/유지'))
    lines=[f"{ok} {res.get('label',res.get('name','worker'))} worker {mode}",f"- total: {fmt_sec(res.get('total_sec',0))}"]
    for k in ['target','target_version','active','hash','service','compile_mode','compile_result','error']:
        if res.get(k) not in (None,''):lines.append(f'- {k}: {res.get(k)}')
    if res.get('compile'):lines.append('- compile detail: '+str(res.get('compile'))[:1600])
    st=res.get('state') or {}
    if st:lines.append(f"- state: {st.get('verdict','-')} / svc {st.get('service_active','-')} / age {st.get('age_text','-')} / metrics {st.get('metrics','-')}")
    if res.get('notes'):
        lines.append('- notes:');lines.extend(f"  · {str(x)[:300]}" for x in res.get('notes',[])[:18])
    return '\n'.join(lines)


