    while time.time()<deadline:
        last=load_json(BOT_DIR/'clean_brain_status.json',{}) or {};last=last if isinstance(last,dict) else {}
        pid=_service_main_pid(MAIN_SERVICE)
        version_ok=bool(expected_version and same_version_label(str(last.get('version') or ''),expected_version))
        build_ok=bool(not expected_build or str(last.get('build') or '')==expected_build)
        pid_ok=bool(pid and int(last.get('pid') or 0)==int(pid))
        polling_ok=bool(last.get('telegram_polling_ready_v2217') is True and str(last.get('telegram_state') or '')=='polling')
        if version_ok and build_ok and pid_ok and polling_ok:
            notes.append(f"Main polling-ready PASS pid={pid} version={last.get('version')} build={last.get('build')}")
            return True,notes
        time.sleep(0.25)
    notes.append(f"Main polling-ready timeout pid={_service_main_pid(MAIN_SERVICE)} statusPID={last.get('pid')} version={last.get('version')} build={last.get('build')} telegram={last.get('telegram_state')}")
    return False,notes


