def run(cmd,cwd=None,timeout=20):  # type: ignore[override]
    """Never clip a started OS/service transaction to the global release clock.

    Each caller still supplies a bounded timeout. The release clock is checked
    at phase boundaries and in the final verdict, not by shortening systemctl
    stop/start to one second and leaving a component half-restarted.
    """
    return _V2221_BASE_RUN(cmd,cwd=cwd,timeout=timeout)


def _v2221_wait_zero_review(max_wait: float=4.0):
    deadline=time.monotonic()+max(0.5,float(max_wait));remaining=[]
    while time.monotonic()<deadline:
        remaining=find_worker_pids('review',include_helpers=True)
        sqlite=[p for p in _review_sqlite_writer_pids_v1123() if p!=os.getpid()]
