def _v2222_bundle_number(value):
    name=Path(str(value or '')).name
    m=re.fullmatch(r'coinbot_update_v(\d+)\.zip',name)
    return int(m.group(1)) if m else -1


def _v2222_highest_local_bundle():
    rows=[]
    for path in BOT_DIR.glob('coinbot_update_v*.zip'):
        n=_v2222_bundle_number(path.name)
        if n>=0 and path.is_file():rows.append((n,path.name,path))
    return max(rows,key=lambda row:(row[0],row[1]))[2] if rows else None


