def _v2222_clear_stale_release_request_for_newer(selected):
    """A newer local bundle may replace an abandoned older pending request.

    A live apply lock is never interrupted. Only stale/non-live pending state is
    cleared, preventing a failed v2220 request from being resumed after v2222 is
    uploaded and requested.
    """
    job=_load_release_job()
    if not job:return True,''
    live,lock=_v2222_apply_lock_live()
    old_n=_v2222_bundle_number(job.get('explicit'))
    new_n=_v2222_bundle_number(selected.name if selected else '')
    if live:
        return False,f"live request {job.get('explicit') or '-'} pid={lock.get('pid') or '-'}"
    if new_n<=old_n:
        return False,f"pending request {job.get('explicit') or '-'}"
    for path in (guard_post_upgrade_path(),_release_apply_lock_path(),_release_inflight_path(),_release_final_pending_path()):
        try:path.unlink(missing_ok=True)
        except Exception:pass
    return True,f"stale pending {job.get('explicit') or '-'} superseded by {selected.name}"


