    expected_version=extract_bot_version(target) if target.exists() else ''
    expected_build=str(extract_assignment(target,'BUILD') or extract_assignment(target,'BUILD_LABEL') or '') if target.exists() else ''
    deadline=time.monotonic()+max(2.0,float(timeout_sec))
    while time.monotonic()<deadline:
        obj=read_json(BOT_DIR/'clean_brain_status.json') or {}
        last=obj if isinstance(obj,dict) else {}
        pid=_service_main_pid(MAIN_SERVICE)
        version_ok=bool(expected_version and same_version_label(str(last.get('version') or ''),expected_version))
        build_ok=bool(not expected_build or str(last.get('build') or '')==expected_build)
        pid_ok=bool(pid and int(last.get('pid') or 0)==int(pid))
        polling_ok=bool(last.get('telegram_polling_ready_v2217') is True and str(last.get('telegram_state') or '')=='polling')
        if version_ok and build_ok and pid_ok and polling_ok:
            return True,[f"main PASS pid={pid} version={last.get('version')} polling=ready"]
        time.sleep(0.2)
