    if isinstance(snap,dict) and snap.get('ok'):
        return True,[f"paper PASS pid={snap.get('main_pid')} version={snap.get('status_version')} writer={snap.get('writer_pid')}"]
    if not allow_restart:
        return False,['paper runtime mismatch and restart not allowed']
    state,notes=restart_paper_bot(version,build,digest)
    snap=paper_runtime_snapshot(version,build,digest,max_age_sec=45.0)
