def _v2224_guard_only_apply(req):
    """Apply the v2224 guard-only bundle without touching trading services."""
    bundle=_release_bundle_path(str((req or {}).get('explicit') or ''))
    if not bundle:return False,f"bundle missing: {(req or {}).get('explicit') or '-'}"
    expected=str((req or {}).get('bundle_digest') or '')
    if expected and sha256_file(bundle)!=expected:return False,'bundle digest mismatch'
    started=time.monotonic()
    work=BOT_DIR/f'.bundle_guard_v2224_{os.getpid()}_{time.time_ns()}'
    try:
        work.mkdir(parents=True,exist_ok=False)
        with zipfile.ZipFile(bundle,'r') as z:
            bad=z.testzip()
            if bad:return False,f'zip damage: {bad}'
            z.extractall(work)
        manifest=read_json(work/'DEPLOY_BUNDLE.json') or {}
        if str(manifest.get('version') or '')!='v2224':
            return _V2224_PREV_APPLY(req)
        guard_name=str(manifest.get('guard') or '').strip()
        if not guard_name:return False,'v2224 guard target missing'
        source=work/guard_name
        if not source.exists():return False,f'v2224 source missing: {guard_name}'
        okc,out=py_compile(source)
        if not okc:return False,f'compile failed: {tail(out,1000)}'
        target=BOT_DIR/guard_name
        _v2179_atomic_write_bytes(target,source.read_bytes())
        active=BOT_DIR/GUARD_ACTIVE_FILE
        changed=(not active.exists()) or sha256_file(active)!=sha256_file(target)
        if changed:_v2179_atomic_write_bytes(active,target.read_bytes())
        try:(BOT_DIR/DEPLOYED_GUARD_FILE).write_text(guard_name+'\n',encoding='utf-8')
        except Exception:pass
        pid=_service_main_pid(GUARD_SERVICE)
        target_version=worker_version(target);active_version=worker_version(active)
        hash_ok=target.exists() and active.exists() and sha256_file(target)==sha256_file(active)
        version_ok=bool(target_version and target_version==active_version)
        pid_ok=bool(pid and pid_alive(pid))
        elapsed=time.monotonic()-started
        ok=bool(hash_ok and version_ok and pid_ok and elapsed<=V2224_HARD_SEC)
        lines=[
            f"📦 {'✅' if ok else '⚠️'} v2224 빠른 복구 {'PASS' if ok else 'CHECK'}",
            f'- bundle: {bundle.name}',
            f'- total: {elapsed:.1f}s / 목표 40s / 상한 60s',
            f'- guard: pid={pid} / version={active_version} / hash={"PASS" if hash_ok else "CHECK"}',
            f'- alias 교체: {1 if changed else 0} / trading service 재시작: 0',
            '- Main·Paper·Review·Strategy·Core 미변경·재시작 없음',
            '- 다음 정상 업데이트부터 기본 /gupgrade_bundle은 최신 로컬 ZIP 자동선택',
            '- 지정 ZIP은 복구 때만 사용 · 자동매수 OFF',
        ]
        return ok,'\n'.join(lines)
    except Exception as exc:
        return False,f'📦 ❌ v2224 가드 복구 예외\n- {type(exc).__name__}: {exc}\n- 자동매수 OFF\n{tail(traceback.format_exc(),2500)}'
    finally:
        shutil.rmtree(work,ignore_errors=True)


