def _v2225_find_paper_family_pids():
    rows=[]
    try:
        for p in Path('/proc').iterdir():
            if not p.name.isdigit():continue
            pid=int(p.name)
            low=proc_cmdline(pid).lower()
            if 'python' not in low:continue
            if re.search(r'(?:^|[/\s])paper_bot(?:_v[^/\s]+)?\.py(?:\x00|\s|$)',low) or 'paper_bot.py' in low or re.search(r'paper_bot_v[^/\s]+\.py',low):
                rows.append(pid)
    except Exception:pass
    return sorted(set(rows))


def _v2225_wait_no_paper_family(timeout_sec=4.0):
    deadline=time.monotonic()+max(0.5,float(timeout_sec));rows=[]
    while time.monotonic()<deadline:
        rows=[p for p in _v2225_find_paper_family_pids() if p!=os.getpid() and pid_alive(p)]
        if not rows:return True,[]
        time.sleep(0.15)
    rows=[p for p in _v2225_find_paper_family_pids() if p!=os.getpid() and pid_alive(p)]
    return not rows,rows


