def _v2223_main_identity(manifest,timeout_sec=18.0):  # type: ignore[override]
    main_name=str((manifest or {}).get('main') or '').strip();notes=[];last={}
    if not main_name:return True,notes
    target=BOT_DIR/main_name
    expected_version=extract_bot_version(target) if target.exists() else ''
    expected_build=str(extract_assignment(target,'BUILD') or extract_assignment(target,'BUILD_LABEL') or '') if target.exists() else ''
    deadline=time.monotonic()+max(2.0,float(timeout_sec))
    while time.monotonic()<deadline:
        obj=read_json(BOT_DIR/'clean_brain_status.json') or {};last=obj if isinstance(obj,dict) else {}
        pid=_service_main_pid(MAIN_SERVICE)
        version_ok=bool(expected_version and same_version_label(str(last.get('version') or ''),expected_version))
        build_ok=bool(not expected_build or str(last.get('build') or '')==expected_build)
        pid_ok=bool(pid and int(last.get('pid') or 0)==int(pid))
        polling_ok=bool(last.get('telegram_polling_ready_v2217') is True and str(last.get('telegram_state') or '')=='polling')
        if version_ok and build_ok and pid_ok and polling_ok:
            return True,[f"main PASS pid={pid} version={last.get('version')} polling=ready"]
        time.sleep(0.25)
    return False,[f"main CHECK pid={_service_main_pid(MAIN_SERVICE)} statusPID={last.get('pid')} version={last.get('version')} polling={last.get('telegram_state')}"]


def _v2225_restart_paper(expected_version='',expected_build='',expected_hash=''):  # type: ignore[override]
    notes=[]
    if not service_exists(PAPER_SERVICE):
        ok_unit,unit_notes=_v399_install_paper_service(force=True);notes+=unit_notes
        if not ok_unit:return False,notes
    active=BOT_DIR/PAPER_ACTIVE_FILE
    expected_version=expected_version or extract_paper_version(active)
    b=expected_build or extract_assignment(active,'BUILD_LABEL');expected_build='' if b=='?' else b
    expected_hash=expected_hash or (short_hash(active) if active.exists() else '')
    rc,out=run(['systemctl','--no-block','stop',PAPER_SERVICE],timeout=4)
    notes.append(f'stop --no-block rc={rc} {tail(out,120)}'.strip())
    zero,remaining=_v2225_wait_no_paper_family(3.0)
    if not zero:
        for pid in remaining:
            try:os.kill(pid,signal.SIGTERM);notes.append(f'paper family TERM {pid}')
            except Exception:pass
        zero,remaining=_v2225_wait_no_paper_family(1.5)
    if not zero:
        for pid in remaining:
            try:os.kill(pid,signal.SIGKILL);notes.append(f'paper family KILL {pid}')
            except Exception:pass
        zero,remaining=_v2225_wait_no_paper_family(1.0)
    _v2225_backup_stale_paper_runtime(notes)
    permission_ok,permission_notes=repair_paper_canonical_writer_ownership();notes+=permission_notes
    src,sout=run(['systemctl','--no-block','start',PAPER_SERVICE],timeout=4)
    notes.append(f'start --no-block rc={src} {tail(sout,120)}'.strip())
    deadline=time.monotonic()+20.0;last={}
    while time.monotonic()<deadline:
        pid=_service_main_pid(PAPER_SERVICE)
        if pid and pid_alive(pid):repair_paper_pid_file(pid)
        last=paper_runtime_snapshot(expected_version,expected_build,expected_hash,max_age_sec=90.0)
        if zero and permission_ok and isinstance(last,dict) and last.get('ok'):
            notes.append(f"paper PASS MainPID={last.get('main_pid')} statusPID={last.get('status_pid')} writerPID={last.get('writer_pid')} version={last.get('status_version')}")
            return True,notes
        time.sleep(0.25)
    notes.append('paper CHECK '+' / '.join((last.get('reasons') or ['fresh status 없음'])[:10]))
    return False,notes


