    if not zero:
        for pid in sorted(set(remaining+sqlite)):
            if pid==os.getpid():continue
            try:os.kill(pid,signal.SIGTERM);notes.append(f'review TERM {pid}')
            except Exception as exc:notes.append(f'review TERM failed {pid}: {type(exc).__name__}')
        zero,remaining,sqlite=_v2221_wait_zero_review(2.0)

    if not zero:
        for pid in sorted(set(remaining+sqlite)):
            if pid==os.getpid():continue
            try:os.kill(pid,signal.SIGKILL);notes.append(f'review KILL {pid}')
            except Exception as exc:notes.append(f'review KILL failed {pid}: {type(exc).__name__}')
        zero,remaining,sqlite=_v2221_wait_zero_review(1.5)

    if not zero:
        src,sout=run(['systemctl','--no-block','start',service],timeout=6)
        notes.append(f'recovery start rc={src} {tail(sout,160)}'.strip())
        notes.append(f'review drain FAIL family={remaining} sqlite={sqlite}')
        return False,notes

    notes.append('review zero process + zero SQLite writer proven')
    _v2244_review_cache_cleanup_guard(notes)

    # These are mutable runtime identity files, not ledgers. Remove stale
    # payloads only after zero-process proof, so the new boot cannot be judged
    # against the previous PID/version.
    for path in (worker_status_path('review'), BOT_DIR/'runtime'/'review_worker_singleton_v1121.lock'):
        try:
            path.unlink(missing_ok=True)
            notes.append(f'stale runtime identity removed {path.name}')
        except Exception as exc:
            notes.append(f'stale runtime identity warning {path.name}: {type(exc).__name__}: {exc}')

    start_requested_ts=time.time()
    rc,out=run(['systemctl','--no-block','start',service],timeout=6)
    notes.append(f'review start --no-block rc={rc} {tail(out,160)}'.strip())

    deadline=time.monotonic()+20.0
    last={}
    while time.monotonic()<deadline:
        last=_worker_singleton_evidence_v1111(
            'review',target_version=target_version,started_after_ts=start_requested_ts)
        if last.get('deploy_ok'):
            notes.append(
                f"review PASS MainPID={last.get('main_pid')} "
                f"statusPID={last.get('status_pid')} lockPID={last.get('lock_pid')} "
                f"version={last.get('status_version')}")
            return True,notes
        time.sleep(0.25)

    notes.append(
        f"review CHECK MainPID={last.get('main_pid')} "
        f"statusPID={last.get('status_pid')} statusVer={last.get('status_version')} "
        f"lockPID={last.get('lock_pid')} lockVer={last.get('lock_version')} "
        f"reasons={last.get('reasons')}")
    _rc,journal=run(['journalctl','-u',service,'-n','20','--no-pager'],timeout=6)
    if journal:notes.append('review journal: '+tail(journal,900).replace('\n',' | '))
    return False,notes


