    b=expected_build or extract_assignment(active,'BUILD_LABEL');expected_build='' if b=='?' else b
    expected_hash=expected_hash or (short_hash(active) if active.exists() else '')
    rc,out=run(['systemctl','--no-block','stop',PAPER_SERVICE],timeout=5)
    notes.append(f'paper stop --no-block rc={rc} {tail(out,120)}'.strip())
    zero,remaining=_v2225_wait_no_paper_family(6.0)
    if not zero:
        for pid in remaining:
            try:os.kill(pid,signal.SIGTERM);notes.append(f'paper TERM {pid}')
            except Exception as exc:notes.append(f'paper TERM failed {pid}:{type(exc).__name__}')
        zero,remaining=_v2225_wait_no_paper_family(3.0)
    if not zero:
        for pid in remaining:
            try:os.kill(pid,signal.SIGKILL);notes.append(f'paper KILL {pid}')
            except Exception as exc:notes.append(f'paper KILL failed {pid}:{type(exc).__name__}')
        zero,remaining=_v2225_wait_no_paper_family(2.0)
    # Mandatory final recomputation after all signals.
    zero,remaining=_v2225_wait_no_paper_family(0.8)
    if not zero:
        detail=[]
        for pid in remaining[:8]:
            try:
                stat=(Path(f'/proc/{pid}/stat').read_text(errors='ignore').split()[2])
                wchan=(Path(f'/proc/{pid}/wchan').read_text(errors='ignore').strip())
            except Exception:stat='?';wchan='?'
            detail.append(f'{pid}:{stat}:{wchan}')
        notes.append(f'paper drain FAIL remaining={detail or remaining}')
        notes.append('paper start blocked: previous owner not zero')
        return False,notes
    notes.append('paper zero family proven before start')
    _v2225_backup_stale_paper_runtime(notes)
    permission_ok,permission_raw=repair_paper_canonical_writer_ownership();notes+=_v2248_compact_permission_notes(permission_raw)
    if not permission_ok:
        notes.append('paper canonical owner CHECK; start blocked')
        return False,notes
    start_requested_ts=time.time()
    src,sout=run(['systemctl','--no-block','start',PAPER_SERVICE],timeout=5)
    notes.append(f'paper start --no-block rc={src} {tail(sout,120)}'.strip())
    if src!=0:return False,notes
    deadline=time.monotonic()+30.0;last={}
    while time.monotonic()<deadline:
        pid=_service_main_pid(PAPER_SERVICE)
        if pid and pid_alive(pid):repair_paper_pid_file(pid)
        last=paper_runtime_snapshot(expected_version,expected_build,expected_hash,max_age_sec=45.0)
        if isinstance(last,dict) and last.get('ok'):
            notes.append(f"paper PASS MainPID={last.get('main_pid')} statusPID={last.get('status_pid')} writerPID={last.get('writer_pid')} version={last.get('status_version')}")
            return True,notes
        time.sleep(0.25)
    status_path=BOT_DIR/'paper_bot_status.json'
    reasons=list(last.get('reasons') or []) if isinstance(last,dict) else []
    if not status_path.exists():reasons.insert(0,'status_file_missing')
    if not reasons:reasons=['runtime_proof_incomplete']
    notes.append(f"paper CHECK MainPID={_service_main_pid(PAPER_SERVICE)} statusPID={last.get('status_pid') if isinstance(last,dict) else 0} writerPID={last.get('writer_pid') if isinstance(last,dict) else 0} version={last.get('status_version') if isinstance(last,dict) else ''} reasons={reasons[:10]}")
    return False,notes


