def _v2249_selection_worker():
    job = read_json(V2249_SELECTION_JOB) or {}
    start = float(job.get('accepted_ts') or time.time())
    requested = str(job.get('explicit') or '')
    try:
        if job.get('skip_git'):
            selected = BOT_DIR / Path(requested).name
            notes = []
            if not selected.is_file():
                raise RuntimeError(f'내부 적용 ZIP 없음: {selected.name}')
        else:
            ok, notes = _github_direct_download_latest_bundle(explicit=requested or None)
            if not ok:
                raise RuntimeError('GitHub ZIP 확인 실패 · ' + ' / '.join(str(x) for x in (notes or [])[-6:]))
            selected = _v2226_bundle_from_download_notes(notes, requested)
            if not selected or not selected.is_file():
                raise RuntimeError('선택 ZIP 파일 확인 실패')

        selected_ts = time.time()
        selection_sec = max(0.0, selected_ts - start)
        number = _v2225_bundle_number(selected.name)

        # Claim before send. A process crash can therefore never duplicate the
        # visible start notice after Guard restart.
        if not job.get('start_notice_claimed'):
            job.update({
                'start_notice_claimed': True,
                'selected': selected.name,
                'selection_done_ts': selected_ts,
                'selection_sec': selection_sec,
                'updated_ts': time.time(),
            })
            write_json(V2249_SELECTION_JOB, job)
            delivered = bool(send(ALLOWED_CHAT_ID, '\n'.join([
                '📦 업그레이드 시작',
                f'- 선택 ZIP: {selected.name}',
                f'- 버전: v{number}',
                '- 단일 고정 적용 진행 중 · 자동매수 OFF',
            ])))
            if not delivered:
                raise RuntimeError('업그레이드 시작판 전송 실패')
            job['start_notice_sent'] = True
            job['updated_ts'] = time.time()
            write_json(V2249_SELECTION_JOB, job)

        guard_ok, guard_note, guard_changed = _v2242_exact_guard_from_bundle(selected)
        if not guard_ok:
            raise RuntimeError('가드 우선 준비 실패 · ' + str(guard_note))
        req = _v2242_submit_release(selected, force=bool(job.get('force')), post_commands=job.get('post_commands') or [])
        req.update({
            'accepted_ts': start,
            'selection_done_ts': selected_ts,
            'accepted_ts_v2249': start,
            'selection_done_ts_v2249': selected_ts,
            'start_notice_claimed': True,
            'start_notice_sent': True,
        })
        write_json(guard_post_upgrade_path(), req)
        write_json(V2249_SELECTION_JOB, dict(job, stage='HANDOFF', selected=selected.name,
                                              selection_done_ts=selected_ts, selection_sec=selection_sec,
                                              updated_ts=time.time()))
        if guard_changed:
            rc, out = run(['systemctl', 'restart', GUARD_SERVICE], timeout=30)
            if rc != 0:
                raise RuntimeError(f'가드 자동 재시작 실패 rc={rc} {tail(out,300)}')
            return
        try:
            V2249_SELECTION_JOB.unlink(missing_ok=True)
        except Exception:
            pass
        if not _v2004_start_release_resume_priority():
            # Another canonical release owner may already have claimed the same
            # pending request. Treat that as handoff success, not a second failure.
            live=_load_release_job(max_age_sec=86400.0) or {}
            if str(live.get('request_id') or '')!=str(req.get('request_id') or ''):
                raise RuntimeError('release thread 시작 실패')
    except Exception as exc:
        try:
            guard_post_upgrade_path().unlink(missing_ok=True)
        except Exception:
            pass
        try:
            V2249_SELECTION_JOB.unlink(missing_ok=True)
        except Exception:
            pass
        _v2249_send_final_once('\n'.join([
            '📦 ❌ 업데이트 실패',
            f'- {type(exc).__name__}: {exc}',
            f'- 접수 후 {max(0.0,time.time()-start):.1f}s',
            '- 자동매수 OFF',
        ]))
    finally:
        try:
            V2249_SELECTION_LOCK.unlink(missing_ok=True)
        except Exception:
            pass

def _v2249_start_selection_thread():
    global _V2249_SELECTION_THREAD
    with _V2249_SELECTION_THREAD_LOCK:
        if _V2249_SELECTION_THREAD and _V2249_SELECTION_THREAD.is_alive():
            return True
        try:
            fd = os.open(str(V2249_SELECTION_LOCK), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            os.write(fd, str(os.getpid()).encode())
            os.close(fd)
        except FileExistsError:
            try:
                age = time.time() - V2249_SELECTION_LOCK.stat().st_mtime
                raw = V2249_SELECTION_LOCK.read_text(encoding='utf-8', errors='ignore').strip()
                owner_pid = int(raw) if raw.isdigit() else 0
                current_thread_live = bool(_V2249_SELECTION_THREAD and _V2249_SELECTION_THREAD.is_alive())
                if owner_pid == os.getpid():
                    if current_thread_live:
                        return True
                    V2249_SELECTION_LOCK.unlink(missing_ok=True)
                elif owner_pid and pid_alive(owner_pid) and age < 30.0:
                    return True
                else:
                    V2249_SELECTION_LOCK.unlink(missing_ok=True)
            except Exception:
                return False
            return _v2249_start_selection_thread()
        except Exception:
            return False
        _V2249_SELECTION_THREAD = threading.Thread(
            target=_v2249_selection_worker,
            name='guard-bundle-selection',
            daemon=True,
        )
        _V2249_SELECTION_THREAD.start()
        return True

def gupgrade_bundle_text(force=False,explicit=None,skip_git=False,post_commands=None):  # type: ignore[override]
    active=_load_release_job() or _v2249_selection_active()
