def _v2252_current_release_manifest_scope():
    out={'request':{},'bundle':'','review_target':'','review_restart_required':False,'review_recovery':False}
    try:
        req=_load_release_job() or {}
        if not isinstance(req,dict):return out
        out['request']=req
        bundle=_release_bundle_path(str(req.get('explicit') or ''))
        if not bundle or not Path(bundle).is_file():return out
        out['bundle']=Path(bundle).name
        with zipfile.ZipFile(bundle,'r') as z:
            raw=z.read('DEPLOY_BUNDLE.json')
        manifest=json.loads(raw.decode('utf-8'))
        if not isinstance(manifest,dict):return out
        workers=manifest.get('workers') if isinstance(manifest.get('workers'),dict) else {}
        review_target=str(workers.get('review') or '').strip()
        restart_required=bool(manifest.get('review_restart_required'))
        changed=manifest.get('changed_components') if isinstance(manifest.get('changed_components'),list) else []
        aliases=manifest.get('aliases') if isinstance(manifest.get('aliases'),dict) else {}
        owns_review=bool(review_target and (restart_required or 'review' in changed or aliases.get('review_worker.py')==review_target))
        out.update({'review_target':review_target,'review_restart_required':restart_required,'review_recovery':owns_review})
    except Exception as exc:
        out['error']=f'{type(exc).__name__}: {exc}'
    return out


def _v2252_token_owner_runtime_proof(allow_review_recovery=False):
    review_service=str(WORKER_SPECS.get('review',{}).get('service') or 'tradingbot-review-worker')
    scope=_v2252_current_release_manifest_scope() if allow_review_recovery else {}
    recovery=bool(allow_review_recovery and scope.get('review_recovery'))
    specs={
        'main':(MAIN_SERVICE,('TELEGRAM_TOKEN',)),
        'guard':(GUARD_SERVICE,('GUARD_BOT_TOKEN',)),
        'paper':(PAPER_SERVICE,('PAPER_BOT_TOKEN',)),
        'review':(review_service,()),
    }
    evidence={};issues=[]
    for label,(service,expected) in specs.items():
        pid=_service_main_pid(service);state=is_service_active(service)
        active=bool(state=='active' and pid and pid_alive(pid))
        env=_v2248_proc_env(pid) if active else {}
        actual=tuple(k for k in ('TELEGRAM_TOKEN','GUARD_BOT_TOKEN','PAPER_BOT_TOKEN') if env.get(k))
        row={'service':service,'state':state,'pid':pid,'token_keys':list(actual)}
        if label=='review' and not active and recovery:
            row.update({'recovery_allowed':True,'recovery_bundle':scope.get('bundle'),'manifest_target':scope.get('review_target')})
            # review.env static no-token proof already passed in
            # _v2248_env_file_contract; there is no process env to inspect yet.
            evidence[label]=row
            continue
        if not active:issues.append(f'{label}:service_not_active')
        if actual!=expected:issues.append(f'{label}:token_owner {list(actual)}->{list(expected)}')
        evidence[label]=row
    return not issues,evidence,issues


