CANONICAL_RUNTIME_WAIT_SEC=150.0
_REAL_IS_MAIN_SERVICE_ACTIVE=is_main_service_active


def is_main_service_active():  # type: ignore[override]
    """Hide only planned transient Main restart states from the periodic notifier.

    The deployment thread still reads systemd directly. This wrapper affects the
    Telegram polling main thread only and removes the old active->deactivating->
    active noise during a sealed bundle restart.
    """
    try:
        if threading.current_thread() is threading.main_thread() and CANONICAL_PLANNED_RESTART.exists():
            return 'active'
    except Exception:
        pass
    return _REAL_IS_MAIN_SERVICE_ACTIVE()


def _service_state(service):
    rc,out=run(['systemctl','is-active',str(service)],timeout=6)
    return str(out or '').strip(),rc


def _service_execstart(service):
    rc,out=run(['systemctl','show',str(service),'-p','ExecStart','--value'],timeout=7)
    return str(out or '').strip(),rc


def _safe_manifest_name(value):
    name=str(value or '').strip()
    if not name or Path(name).name!=name or '/' in name or '\\' in name or name in {'.','..'}:
        raise ValueError(f'unsafe manifest member: {name or "-"}')
    return name


def _read_bundle_manifest(bundle):
    with zipfile.ZipFile(bundle,'r') as z:
        bad=z.testzip()
        if bad:raise RuntimeError(f'zip damage: {bad}')
        try:raw=z.read('DEPLOY_BUNDLE.json')
        except KeyError:raise RuntimeError('DEPLOY_BUNDLE.json missing')
        obj=json.loads(raw.decode('utf-8'))
    if not isinstance(obj,dict):raise RuntimeError('DEPLOY_BUNDLE.json invalid')
    return obj


def _manifest_component_targets(manifest):
    """Return every manifest-owned deploy target from one canonical parser.

    Historical manifests place Main/Paper/Guard at the top level. Worker bundles
    also place Strategy/Review/Candle and the other existing workers at the top
    level, while some older bundles use the nested ``workers`` mapping. The old
    parser ignored top-level workers, so their aliases were copied but their
    services were never restarted or runtime-proved. Keep both existing formats
    and resolve each component exactly once.
    """
    out={}
    canonical_keys=('main','paper','guard','ws','micro','ws_sidecar','micro_sidecar',*tuple(WORKER_SPECS.keys()))
    for key in canonical_keys:
        value=str(manifest.get(key) or '').strip()
        if value:out[str(key)]=_safe_manifest_name(value)
    workers=manifest.get('workers') if isinstance(manifest.get('workers'),dict) else {}
    for key,value in workers.items():
        if str(value or '').strip():out[str(key)]=_safe_manifest_name(value)
    return out


def _manifest_aliases(manifest):
    raw=manifest.get('aliases') if isinstance(manifest.get('aliases'),dict) else {}
    out={}
    for alias,source in raw.items():
        out[_safe_manifest_name(alias)]=_safe_manifest_name(source)
    return out


def _python_identity(path,component):
    keys={
        'main':('BOT_VERSION','MAIN_VERSION','VERSION'),
        'paper':('VERSION','PAPER_VERSION'),
        'guard':('VERSION','GUARD_VERSION'),
    }.get(component,('VERSION',))
    version=''
    for key in keys:
        value=str(extract_assignment(path,key) or '').strip()
        if value and value!='?':version=value
    build=''
    for key in ('BUILD_LABEL','BUILD','GUARD_BUILD_LABEL'):
        value=str(extract_assignment(path,key) or '').strip()
        if value and value!='?':build=value
    return version,build


def _atomic_write_bytes(path,data,mode=None):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_name(f'.{path.name}.deploy_{os.getpid()}_{time.time_ns()}')
    with tmp.open('wb') as fh:
        fh.write(data);fh.flush();os.fsync(fh.fileno())
    if mode is not None:
        try:os.chmod(tmp,mode)
        except Exception:pass
    os.replace(tmp,path)


def _copy_if_changed(path,data):
    path=Path(path);new_hash=hashlib.sha256(data).hexdigest()
    old_hash=sha256_file(path) if path.is_file() else ''
    if old_hash==new_hash:return False,old_hash
    mode=None
    try:mode=stat.S_IMODE(path.stat().st_mode) if path.exists() else 0o755
    except Exception:mode=0o755
    _atomic_write_bytes(path,data,mode)
    actual=sha256_file(path)
    if actual!=new_hash:raise RuntimeError(f'atomic hash mismatch: {path.name}')
    return True,actual


def _write_deployed_marker(path,value):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    _atomic_write_bytes(path,(str(value).strip()+'\n').encode('utf-8'),0o600)
    return (read_file(path) or '').strip()==str(value).strip()


