V2269_RETENTION_SEC=30*86400
_V2269_PREV_PROTECTED=_v2047_is_protected

def _v2047_is_protected(path: Path):
    try: rel=path.relative_to(BOT_DIR).as_posix().lower()
    except Exception: rel=str(path).lower()
    name=path.name.lower()
    if name.startswith('.env') or any(x in name for x in ('token','secret','apikey','api_key','credential')): return True
    if any(x in rel for x in ('systemd','environmentfile','service_config')) or name.endswith(('.service','.timer')): return True
    if path.is_symlink(): return True
    return _V2269_PREV_PROTECTED(path)

