# =============================================================================
# Guard v2.6.83 / v2282
# Guard-self update bootstrap and canonical continuation.
# A guard-owned bundle is copied and compiled first, the pending request remains
# the single continuation owner, and only tradingbot-guard is restarted once.
# The new Guard MainPID resumes the same request and applies/verifies only the
# remaining manifest targets. No peer service is touched when it is unchanged.
# =============================================================================

def _v2282_expected_guard_version_from_source(text: str) -> str:
    # Guard source keeps historical VERSION assignments. Runtime identity is
    # always the final active assignment, never the first historical one.
    matches = re.findall(r"(?m)^VERSION\s*=\s*['\"]([^'\"]+)['\"]", str(text or ''))
    return str(matches[-1]) if matches else ''


def _v2282_guard_first_handoff(req: dict) -> tuple[bool, str]:
    """Restart Guard once before canonical apply when the sealed manifest owns Guard.

    Returns (continued_here, note). False means systemd restart was requested and
    this process must stop handling the release; the new MainPID resumes it.
    """
    bundle = _release_bundle_path(str((req or {}).get('explicit') or ''))
    if not bundle:
        return True, 'guard-first skip: bundle missing'
    try:
        with zipfile.ZipFile(bundle, 'r') as z:
            manifest = json.loads(z.read('DEPLOY_BUNDLE.json').decode('utf-8'))
            if not isinstance(manifest, dict):
                return True, 'guard-first skip: manifest invalid'
            target_name = str(manifest.get('guard') or '').strip()
            changed = manifest.get('changed_components') if isinstance(manifest.get('changed_components'), list) else []
            owns_guard = bool(target_name and ('guard' in [str(x) for x in changed] or manifest.get('guard_restart_required')))
            if not owns_guard:
                return True, 'guard unchanged'
            source_bytes = z.read(target_name)
            source_text = source_bytes.decode('utf-8', errors='ignore')
            expected_version = _v2282_expected_guard_version_from_source(source_text)
            aliases = manifest.get('aliases') if isinstance(manifest.get('aliases'), dict) else {}
            alias_name = next((str(a) for a,t in aliases.items() if str(t)==target_name and str(a).endswith('.py')), GUARD_ACTIVE_FILE)
        # Runtime identity, not file hash alone, decides whether self restart is due.
        runtime_matches = bool(expected_version and str(VERSION) == expected_version)
        target_path = BOT_DIR / target_name
        alias_path = BOT_DIR / alias_name
        target_hash = hashlib.sha256(source_bytes).hexdigest()
        alias_matches = alias_path.exists() and sha256_file(alias_path) == target_hash
        target_matches = target_path.exists() and sha256_file(target_path) == target_hash
        if runtime_matches and alias_matches and target_matches:
            # New Guard process resumes the same existing release job. Keep a
            # sealed marker so the normal final report includes the one restart.
            if (req or {}).get('guard_handoff_v2282'):
                req2 = dict(req or {})
                req2['guard_restart_completed_v2282'] = True
                req2['stage'] = 'APPLYING'
                write_json(guard_post_upgrade_path(), req2)
            return True, f'guard runtime already exact: {expected_version}'

        tmp_dir = BOT_DIR / 'runtime' / f'.guard_v2282_{os.getpid()}_{time.time_ns()}'
        tmp_dir.mkdir(parents=True, exist_ok=False)
        try:
            staged = tmp_dir / target_name
            staged.write_bytes(source_bytes)
            okc, out = py_compile(staged)
            if not okc:
                raise RuntimeError('Guard py_compile failed: ' + tail(out, 1000))
            _atomic_write_bytes(target_path, source_bytes, 0o755)
            _atomic_write_bytes(alias_path, source_bytes, 0o755)
            if sha256_file(target_path) != target_hash or sha256_file(alias_path) != target_hash:
                raise RuntimeError('Guard source/alias hash mismatch after atomic copy')
            try:
                (BOT_DIR / DEPLOYED_GUARD_FILE).write_text(target_name + '\n', encoding='utf-8')
            except Exception:
                pass
        finally:
            shutil.rmtree(tmp_dir, ignore_errors=True)

        req2 = dict(req or {})
        req2['stage'] = 'waiting_guard_ready'
        req2['guard_handoff_v2282'] = True
        req2['guard_target_v2282'] = target_name
        req2['guard_expected_version_v2282'] = expected_version
        req2['guard_restart_requested_ts_v2282'] = time.time()
        write_json(guard_post_upgrade_path(), req2)
        rc, out = run(['systemctl', 'restart', GUARD_SERVICE], timeout=30)
        if rc != 0:
            raise RuntimeError('Guard systemctl restart failed: ' + tail(out, 800))
        return False, f'guard restart requested once: {target_name}'
    except Exception as exc:
        raise RuntimeError(f'Guard first handoff failed: {type(exc).__name__}: {exc}')


_V2282_RESUME_BASE = resume_guard_release_job

def resume_guard_release_job():  # type: ignore[override]
    req = _load_release_job()
    if req:
        try:
            continue_here, _note = _v2282_guard_first_handoff(req)
            if not continue_here:
                return True
        except Exception as exc:
            text = '\n'.join([
                '📦 ❌ Guard 자체 적용 CHECK',
                f"- bundle: {req.get('explicit') or '-'}",
                f'- 원인: {type(exc).__name__}: {exc}',
                '- 다른 서비스 재시작·우회 적용 없음',
                '- 자동매수 OFF',
            ])
            _queue_release_final(req, False, text)
            try: guard_post_upgrade_path().unlink(missing_ok=True)
            except Exception: pass
            _deliver_pending_release_result_once()
            return True
    return _V2282_RESUME_BASE()


_V2282_APPLY_BASE = _apply_release_bundle_once

def _apply_release_bundle_once(req):  # type: ignore[override]
    """Keep the existing one-command bundle flow and account for the
    transparent Guard self-restart performed before continuation.
    """
    ok, body = _V2282_APPLY_BASE(req)
    req = req or {}
    if req.get('guard_handoff_v2282'):
        text = str(body or '')
        # Canonical continuation already proves the new Guard runtime. Reflect
        # the one real Guard restart in the existing final summary instead of
        # reporting restart 0 after the handoff.
        text = re.sub(r'(\- compile \d+ / source 변경 \d+ / alias 변경 \d+ / restart )0(\b)', r'\g<1>1\2', text, count=1)
        if '[restart]' in text and '- guard: PASS' not in text:
            text = text.replace('[restart]', '[restart]\n- guard: PASS · 자체 변경분 1회 재시작 · fresh runtime 증명', 1)
        body = text
    return ok, body


