# Guard v2.6.84 / v2283
# Existing /gupgrade_bundle stale waiting_guard_ready recovery.
# The normal one-command path is preserved. A dead handoff is closed once,
# recorded, unlocked, and the newly requested bundle proceeds immediately.
# No new command, worker, queue, cache, or alternate deployment path.
# =============================================================================

_V2283_GUPGRADE_BASE = gupgrade_bundle_text


def _v2283_release_lock_is_live() -> tuple[bool, dict]:
    lock = _read_release_apply_lock()
    try:
        pid = int(lock.get('pid') or 0)
    except Exception:
        pid = 0
    return bool(pid and pid_alive(pid)), lock


def _v2283_reclaim_stale_waiting_guard_ready(requested: str = '') -> tuple[bool, str]:
    req = _load_release_job(max_age_sec=86400.0)
    if not req:
        return False, ''
    stage = str(req.get('stage') or 'waiting_guard_ready')
    if stage in {'pending_apply', 'pending', 'waiting_guard'}:
        stage = 'waiting_guard_ready'
    if stage != 'waiting_guard_ready':
        return False, ''
    live_lock, lock = _v2283_release_lock_is_live()
    if live_lock:
        return False, ''
    now_ts = time.time()
    requested_ts = float(req.get('guard_restart_requested_ts_v2282') or req.get('started_ts') or req.get('created_ts') or 0.0)
    age = max(0.0, now_ts - requested_ts) if requested_ts else 999999.0
    # A normal Guard restart should settle quickly. Two minutes avoids racing a
    # real handoff while preventing an abandoned request from blocking forever.
    if age < 120.0:
        return False, ''
    old_bundle = str(req.get('explicit') or '-')
    old_request = str(req.get('request_id') or '-')
    text = '\n'.join([
        '📦 ❌ 이전 업데이트 대기 종료',
        f'- bundle: {old_bundle}',
        f'- request: {old_request}',
        f'- stage: waiting_guard_ready / age {age:.1f}s',
        '- 실제 apply lock·실행 PID 없음',
        '- 재적용 없이 STALE_HANDOFF로 종료하고 잠금 해제',
        f'- 다음 요청: {requested or "latest"}',
        '- 자동매수 OFF',
    ])
    try:
        _write_release_result(req, False, text, delivered=False, delivery_attempts=0)
    except Exception:
        pass
    for path in (guard_post_upgrade_path(), _release_apply_lock_path(), _release_inflight_path(), _release_final_pending_path()):
        try:
            path.unlink(missing_ok=True)
        except Exception:
            pass
    try:
        _ops_issue_append_once(
            f'v2283-stale-guard-handoff-{old_request}',
            BOT_DIR/'ledger'/'issue_ledger_events.jsonl',
            {
                'schema':'issue_ledger_event_v1','event_type':'ISSUE',
                'issue_id':'GUARD-WAITING-READY-STALE-LOCK',
                'version':'v2283','status':'RECOVERED','verify_result':'RUNTIME_RECOVERY',
                'created_ts':now_ts,'created_at':now(),'writer':'guard_v2.6.84',
                'title':'waiting_guard_ready 중단 요청 자동 종료·잠금 해제',
                'detail':text,'auto_buy':False,
            },
        )
    except Exception:
        pass
    return True, text


def gupgrade_bundle_text(force=False, explicit=None, skip_git=False, post_commands=None):  # type: ignore[override]
    requested = Path(str(explicit or '')).name if explicit else ''
    reclaimed, note = _v2283_reclaim_stale_waiting_guard_ready(requested)
    result = _V2283_GUPGRADE_BASE(force=force, explicit=explicit, skip_git=skip_git, post_commands=post_commands)
    if reclaimed and str(result or '').strip() and str(result) != V2181_SILENT_RESTART_REPLY:
        return note + '\n\n' + str(result)
    return result


_V2283_RESUME_BASE = resume_guard_release_job


def resume_guard_release_job():  # type: ignore[override]
    # On startup, close only an abandoned handoff. A live/young request follows
    # the existing canonical continuation unchanged.
    _v2283_reclaim_stale_waiting_guard_ready('startup-resume')
    return _V2283_RESUME_BASE()


